// ── Guidelines persistence (localStorage) ──
const MI_GUIDELINES_KEY = 'mi_template_guidelines';

function _loadGuidelinesOverrides() {
    try {
        const raw = localStorage.getItem(MI_GUIDELINES_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch { return {}; }
}

function _saveGuidelinesOverride(blockId, htmlContent) {
    const overrides = _loadGuidelinesOverrides();
    overrides[blockId] = htmlContent;
    localStorage.setItem(MI_GUIDELINES_KEY, JSON.stringify(overrides));
}

function _getEffectiveGuidelines(blockId, defaults) {
    const overrides = _loadGuidelinesOverrides();
    if (overrides[blockId] !== undefined) return overrides[blockId]; // stored as HTML string
    return null; // use defaults
}

