function exportInnovationProfileAsMarkdown() {
    if (!_ipCachedProfile) { alert('No Innovation Profile loaded.'); return; }
    const d = _ipCachedProfile;
    const sel = document.getElementById('ip-version-select');
    const version = sel ? sel.value : 'v2';

    let md;
    if (version === 'v2' && d.v2) {
        md = _ipExportV2Markdown(d);
    } else {
        md = _ipExportV1Markdown(d);
    }

    const blob = new Blob([md], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Innovation_Profile_${version}_${d.id.replace(/-/g, '_')}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function _ipExportV1Markdown(d) {
    const hc = d.hype_cycle_detail;
    let md = '';

    md += `# Innovation Profile: ${d.title}\n\n`;
    md += `*Hype Cycle Position: ${d.hype_cycle_position} | Benefit: ${hc.benefit_rating} | ${hc.years_to_plateau} to mainstream*\n\n`;
    md += `---\n\n`;

    md += `## Summary\n\n${d.summary}\n\n---\n\n`;

    md += `## Hype Cycle Placement\n\n`;
    md += `| Attribute | Value |\n|---|---|\n`;
    md += `| Position | ${hc.position_label} |\n`;
    md += `| Range | ${hc.range} |\n`;
    md += `| Maturity Level | ${hc.maturity_level} |\n`;
    md += `| Benefit Rating | ${hc.benefit_rating} |\n`;
    md += `| Time to Plateau | ${hc.years_to_plateau} |\n`;
    md += `| Market Penetration | ${hc.market_penetration} |\n\n---\n\n`;

    md += `## Analysis\n\n`;
    md += `### Overview\n\n${d.analysis.overview}\n\n`;
    md += `### Market Context\n\n${d.analysis.market_context}\n\n`;
    md += `### The Role of Knowledge Graphs\n\n${d.analysis.knowledge_graph_role}\n\n`;
    md += `### Why It Matters\n\n${d.analysis.why_it_matters}\n\n---\n\n`;

    md += `## Position & Adoption Speed Justification\n\n`;
    md += `### Current State\n\n${d.position_justification.current_state}\n\n`;
    md += `### Evidence Points\n\n`;
    d.position_justification.evidence_points.forEach(ep => { md += `- ${ep}\n`; });
    md += `\n### Adoption Speed Factors\n\n`;
    d.position_justification.adoption_speed_factors.forEach(f => { md += `- ${f}\n`; });
    md += `\n---\n\n`;

    md += `## SBD-AI Controls Framework Mapping\n\n`;
    md += `${d.sbd_ai_mapping.description}\n\n`;
    md += `### Primary Controls\n\n`;
    d.sbd_ai_mapping.primary_controls.forEach(c => {
        md += `#### ${c.id}: ${c.name}\n\n${c.relevance}\n\n*Maturity Signal:* ${c.maturity_signal}\n\n`;
    });
    md += `### Supporting Controls\n\n`;
    d.sbd_ai_mapping.supporting_controls.forEach(c => {
        md += `- **${c.id} — ${c.name}:** ${c.relevance}\n`;
    });
    md += `\n---\n\n`;

    md += `## Knowledge Graph Analysis\n\n`;
    md += `**Role:** ${d.knowledge_graph_analysis.role}\n\n${d.knowledge_graph_analysis.summary}\n\n`;
    md += `### Key Capabilities\n\n`;
    d.knowledge_graph_analysis.capabilities.forEach(cap => {
        md += `#### ${cap.name}\n\n${cap.description}\n\n`;
    });
    md += `### Adoption Barriers\n\n`;
    d.knowledge_graph_analysis.adoption_barriers.forEach(b => { md += `- ${b}\n`; });
    md += `\n---\n\n`;

    md += `## User Advice\n\n`;
    ['short_term', 'medium_term', 'long_term'].forEach(key => {
        const s = d.user_advice[key];
        md += `### ${s.timeframe}\n\n`;
        s.actions.forEach((a, i) => { md += `${i + 1}. ${a}\n`; });
        md += `\n`;
    });
    md += `---\n\n`;

    md += `## Sample Vendors\n\n`;
    md += `*${d.sample_vendors.note}*\n\n`;
    d.sample_vendors.categories.forEach(cat => {
        md += `### ${cat.category}\n\n`;
        cat.vendors.forEach(v => { md += `- **${v.name}:** ${v.relevance}\n`; });
        md += `\n`;
    });
    md += `---\n\n`;

    md += `## Recommended Reading\n\n`;
    d.recommended_reading.forEach(r => {
        md += `- **${r.title}** (${r.type}) — ${r.relevance}\n`;
    });
    md += `\n---\n\n`;
    md += `*Generated on ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}*\n`;
    md += `*Schema: ${d.schema} | Target Audience: ${d.metadata.target_audience}*\n`;

    return md;
}

// ── Innovation Profile v2 (Gartner IP Template) ──────────────────────

function onIPVersionChange() {
    const sel = document.getElementById('ip-version-select');
    const v1 = document.getElementById('ip-v1-container');
    const v2 = document.getElementById('ip-v2-container');
    if (!sel || !v1 || !v2) return;
    if (sel.value === 'v1') {
        v1.style.display = '';
        v2.style.display = 'none';
    } else {
        v1.style.display = 'none';
        v2.style.display = '';
    }
    // Re-render the active version
    if (_ipCachedProfile) {
        if (sel.value === 'v2') _ipRenderV2(_ipCachedProfile);
    }
}

function _ipRenderV2(d) {
    const v2 = d.v2;
    if (!v2) {
        document.getElementById('ip-v2-definition').innerHTML =
            '<p class="mi-empty">No v2 template data available for this profile.</p>';
        return;
    }
    const hc = d.hype_cycle_detail;

    // HC Position badge bar
    const badgeEl = document.getElementById('ip-v2-hc-badge');
    let bh = '<div style="display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 8px;">';
    const badges = [
        { label: 'Position', value: hc.position_label, color: '#0078d4' },
        { label: 'Maturity', value: hc.maturity_level, color: '#8661c5' },
        { label: 'Benefit', value: hc.benefit_rating, color: '#c50f1f' },
        { label: 'Time to Plateau', value: hc.years_to_plateau, color: '#107c10' },
        { label: 'Market Penetration', value: hc.market_penetration, color: '#c19c00' },
    ];
    badges.forEach(b => {
        bh += `<div style="background: ${b.color}12; border: 1px solid ${b.color}33; border-radius: 8px; padding: 8px 14px; flex: 1; min-width: 120px;">`;
        bh += `<div style="font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted); margin-bottom: 2px;">${b.label}</div>`;
        bh += `<div style="font-size: 13px; font-weight: 700; color: ${b.color};">${b.value}</div>`;
        bh += `</div>`;
    });
    bh += '</div>';
    badgeEl.innerHTML = bh;

    // Edit button helper
    function editBtn(sectionKey) {
        return `<button class="ip-edit-btn" onclick="_ipEditSection('${sectionKey}')" title="Edit this section" style="background: none; border: 1px solid var(--border-color); border-radius: 6px; padding: 4px 10px; font-size: 11px; cursor: pointer; color: var(--text-muted); margin-left: auto; flex-shrink: 0;">✏️ Edit</button>`;
    }

    // Section renderer helper
    function renderSection(elId, icon, title, content, type, sectionKey) {
        const el = document.getElementById(elId);
        if (!el) return;
        let h = '';
        h += `<div class="report-pillar-section" style="margin-bottom: 28px;">`;
        h += `<div class="report-pillar-header" style="display: flex; align-items: center;">`;
        h += `<span class="report-pillar-code">${icon}</span>`;
        h += `<div class="report-pillar-header-text" style="flex: 1;">`;
        h += `<h2 class="report-pillar-name">${title}</h2>`;
        h += `</div>`;
        h += editBtn(sectionKey);
        h += `</div>`;
        h += `<div class="report-sp-longform-card"><div class="report-sp-section" id="ip-v2-content-${sectionKey}">`;

        if (type === 'text') {
            h += `<p style="font-size: 14px; line-height: 1.8; color: var(--text-secondary);">${escapeHtml(content)}</p>`;
        } else if (type === 'bullets') {
            h += `<ul style="padding-left: 20px; margin: 0;">`;
            content.forEach(item => {
                h += `<li style="margin-bottom: 12px; font-size: 14px; line-height: 1.7; color: var(--text-secondary);">${escapeHtml(item)}</li>`;
            });
            h += `</ul>`;
        }

        h += `</div></div></div>`;
        el.innerHTML = h;
    }

    renderSection('ip-v2-definition', '📋', 'Definition', v2.definition, 'text', 'definition');
    renderSection('ip-v2-why-important', '⚡', 'Why This Is Important', v2.why_important, 'text', 'why_important');
    renderSection('ip-v2-business-impact', '💼', 'Business Impact', v2.business_impact, 'text', 'business_impact');
    renderSection('ip-v2-drivers', '🚀', 'Drivers', v2.drivers, 'bullets', 'drivers');
    renderSection('ip-v2-obstacles', '⚠️', 'Obstacles', v2.obstacles, 'bullets', 'obstacles');
    renderSection('ip-v2-user-recommendations', '🎯', 'User Recommendations', v2.user_recommendations, 'bullets', 'user_recommendations');

    // SBD-AI Mapping (compact version for v2)
    const sbdEl = document.getElementById('ip-v2-sbd-mapping');
    if (sbdEl && d.sbd_ai_mapping) {
        const m = d.sbd_ai_mapping;
        let sh = '<div class="report-pillar-section" style="margin-bottom: 28px;">';
        sh += '<div class="report-pillar-header">';
        sh += '<span class="report-pillar-code">🛡️</span>';
        sh += '<div class="report-pillar-header-text">';
        sh += '<h2 class="report-pillar-name">SBD-AI Controls Mapping</h2>';
        sh += `<p class="report-pillar-desc">${escapeHtml(m.description)}</p>`;
        sh += '</div></div>';

        sh += '<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 10px; margin-top: 12px;">';
        m.primary_controls.forEach(c => {
            const pc = c.id.split('-')[0];
            const colors = { TRM: '#8661c5', DSO: '#0078d4', REL: '#107c10', NDS: '#c19c00', IAM: '#c50f1f', INF: '#666', SAF: '#e74c3c' };
            const clr = colors[pc] || '#0078d4';
            sh += `<div class="report-sp-longform-card" style="margin: 0; border-left: 4px solid ${clr};">`;
            sh += `<div class="report-sp-section">`;
            sh += `<div style="margin-bottom: 6px;"><span style="background: ${clr}18; color: ${clr}; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px;">${c.id}</span> <strong style="font-size: 13px;">${escapeHtml(c.name)}</strong></div>`;
            sh += `<p style="font-size: 12px; color: var(--text-secondary); margin: 0 0 6px; line-height: 1.5;">${escapeHtml(c.relevance)}</p>`;
            sh += `<div style="font-size: 11px; color: var(--text-muted);"><em>Maturity Signal:</em> ${escapeHtml(c.maturity_signal)}</div>`;
            sh += `</div></div>`;
        });
        sh += '</div></div>';
        sbdEl.innerHTML = sh;
    }

    // Knowledge Graphs (compact for v2)
    const kgEl = document.getElementById('ip-v2-knowledge-graphs');
    if (kgEl && d.knowledge_graph_analysis) {
        const kg = d.knowledge_graph_analysis;
        let kh = '<div class="report-pillar-section" style="margin-bottom: 28px;">';
        kh += '<div class="report-pillar-header">';
        kh += '<span class="report-pillar-code">🔗</span>';
        kh += '<div class="report-pillar-header-text">';
        kh += '<h2 class="report-pillar-name">Knowledge Graphs as Enabler</h2>';
        kh += `<p class="report-pillar-desc">${escapeHtml(kg.summary)}</p>`;
        kh += '</div></div>';
        kh += '<div class="report-sp-longform-card"><div class="report-sp-section">';
        kh += '<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 10px;">';
        kg.capabilities.forEach(cap => {
            kh += `<div style="background: var(--bg-tertiary); border-radius: 8px; padding: 12px;">`;
            kh += `<div style="font-weight: 700; font-size: 13px; margin-bottom: 4px;">${escapeHtml(cap.name)}</div>`;
            kh += `<p style="font-size: 12px; color: var(--text-secondary); margin: 0; line-height: 1.5;">${escapeHtml(cap.description)}</p>`;
            kh += `</div>`;
        });
        kh += '</div></div></div></div>';
        kgEl.innerHTML = kh;
    }

    // Sample Vendors (compact for v2)
    const svEl = document.getElementById('ip-v2-sample-vendors');
    if (svEl && d.sample_vendors) {
        const sv = d.sample_vendors;
        let vh = '<div class="report-pillar-section" style="margin-bottom: 28px;">';
        vh += '<div class="report-pillar-header">';
        vh += '<span class="report-pillar-code">🏢</span>';
        vh += '<div class="report-pillar-header-text">';
        vh += '<h2 class="report-pillar-name">Sample Vendors</h2>';
        vh += '</div></div>';
        vh += `<div style="background: #c19c0010; border: 1px solid #c19c0033; border-radius: 8px; padding: 10px 14px; margin-bottom: 12px; font-size: 12px; color: var(--text-secondary);">&#9888;&#65039; ${escapeHtml(sv.note)}</div>`;
        const catClr = ['#0078d4', '#8661c5', '#107c10', '#c19c00'];
        sv.categories.forEach((cat, ci) => {
            const clr = catClr[ci % catClr.length];
            vh += `<div style="margin-bottom: 12px;">`;
            vh += `<h4 style="font-size: 13px; margin: 0 0 6px; color: ${clr};">${escapeHtml(cat.category)}</h4>`;
            vh += `<div style="display: flex; flex-wrap: wrap; gap: 6px;">`;
            cat.vendors.forEach(v => {
                vh += `<span style="background: ${clr}10; border: 1px solid ${clr}25; border-radius: 6px; padding: 4px 10px; font-size: 12px;" title="${escapeHtml(v.relevance)}">${escapeHtml(v.name)}</span>`;
            });
            vh += `</div></div>`;
        });
        vh += '</div>';
        svEl.innerHTML = vh;
    }
}

/* ── IP v2 inline editing ─────────────────────────────────────────── */

function _ipEditSection(sectionKey) {
    if (!_ipCachedProfile || !_ipCachedProfile.v2) return;
    const v2 = _ipCachedProfile.v2;
    const contentEl = document.getElementById('ip-v2-content-' + sectionKey);
    if (!contentEl) return;

    const current = v2[sectionKey];
    const isList = Array.isArray(current);

    let h = '';
    if (isList) {
        current.forEach((item, i) => {
            h += `<div style="display: flex; gap: 8px; margin-bottom: 8px; align-items: flex-start;">`;
            h += `<span style="color: var(--text-muted); font-size: 12px; padding-top: 8px; flex-shrink: 0;">${i + 1}.</span>`;
            h += `<textarea class="ip-edit-item" data-idx="${i}" style="flex: 1; min-height: 60px; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-secondary); color: var(--text-primary); font-size: 13px; line-height: 1.6; resize: vertical; font-family: inherit;">${escapeHtml(item)}</textarea>`;
            h += `<button onclick="_ipRemoveBullet('${sectionKey}', ${i})" title="Remove" style="background: none; border: none; color: #c50f1f; cursor: pointer; font-size: 16px; padding: 6px; flex-shrink: 0;">&#x2715;</button>`;
            h += `</div>`;
        });
        h += `<button onclick="_ipAddBullet('${sectionKey}')" style="background: none; border: 1px dashed var(--border-color); border-radius: 6px; padding: 6px 14px; font-size: 12px; color: var(--text-muted); cursor: pointer; width: 100%; margin-bottom: 10px;">+ Add item</button>`;
    } else {
        h += `<textarea id="ip-edit-textarea-${sectionKey}" style="width: 100%; min-height: 150px; padding: 10px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-secondary); color: var(--text-primary); font-size: 14px; line-height: 1.8; resize: vertical; font-family: inherit;">${escapeHtml(current)}</textarea>`;
    }

    h += `<div style="display: flex; gap: 8px; margin-top: 8px;">`;
    h += `<button onclick="_ipSaveSection('${sectionKey}')" style="padding: 6px 16px; border-radius: 6px; border: none; background: #0078d4; color: white; font-size: 12px; cursor: pointer;">Save</button>`;
    h += `<button onclick="_ipCancelEdit('${sectionKey}')" style="padding: 6px 16px; border-radius: 6px; border: 1px solid var(--border-color); background: none; color: var(--text-secondary); font-size: 12px; cursor: pointer;">Cancel</button>`;
    h += `</div>`;

    contentEl.innerHTML = h;
}

function _ipAddBullet(sectionKey) {
    if (!_ipCachedProfile || !_ipCachedProfile.v2) return;
    _ipCachedProfile.v2[sectionKey].push('');
    _ipEditSection(sectionKey);
    // Focus the last textarea
    const els = document.querySelectorAll('#ip-v2-content-' + sectionKey + ' .ip-edit-item');
    if (els.length) els[els.length - 1].focus();
}

function _ipRemoveBullet(sectionKey, idx) {
    if (!_ipCachedProfile || !_ipCachedProfile.v2) return;
    _ipCachedProfile.v2[sectionKey].splice(idx, 1);
    _ipEditSection(sectionKey);
}

async function _ipSaveSection(sectionKey) {
    if (!_ipCachedProfile || !_ipCachedProfile.v2) return;
    const v2 = _ipCachedProfile.v2;
    const isList = Array.isArray(v2[sectionKey]);

    if (isList) {
        const items = document.querySelectorAll('#ip-v2-content-' + sectionKey + ' .ip-edit-item');
        v2[sectionKey] = Array.from(items).map(ta => ta.value.trim()).filter(s => s.length > 0);
    } else {
        const ta = document.getElementById('ip-edit-textarea-' + sectionKey);
        if (ta) v2[sectionKey] = ta.value.trim();
    }

    // Save to server
    try {
        const resp = await fetch('/api/innovation-profiles', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(_ipCachedProfile)
        });
        if (!resp.ok) throw new Error('Save failed');
    } catch (e) {
        alert('Failed to save: ' + e.message);
        return;
    }

    // Re-render
    _ipRenderV2(_ipCachedProfile);
}

function _ipCancelEdit(sectionKey) {
    if (_ipCachedProfile) _ipRenderV2(_ipCachedProfile);
}

/* ── IP HTML Export ───────────────────────────────────────────────── */

function exportInnovationProfileAsHTML() {
    if (!_ipCachedProfile) { alert('No Innovation Profile loaded.'); return; }
    const d = _ipCachedProfile;
    const sel = document.getElementById('ip-version-select');
    const version = sel ? sel.value : 'v2';

    let html;
    if (version === 'v2' && d.v2) {
        html = _ipBuildV2HTML(d);
    } else {
        html = _ipBuildV1HTML(d);
    }

    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Innovation_Profile_${version}_${d.id.replace(/-/g, '_')}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function _ipBuildV2HTML(d) {
    const v2 = d.v2;
    const hc = d.hype_cycle_detail;
    const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

    let h = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Innovation Profile: ${esc(d.title)}</title>
<style>
  :root { --bg: #fff; --bg2: #f8f9fa; --bg3: #e9ecef; --text: #212529; --text2: #495057; --text3: #868e96; --border: #dee2e6; --blue: #0078d4; --purple: #8661c5; --red: #c50f1f; --green: #107c10; --gold: #c19c00; }
  @media (prefers-color-scheme: dark) { :root { --bg: #1a1b1e; --bg2: #25262b; --bg3: #2c2e33; --text: #e4e5e7; --text2: #adb5bd; --text3: #868e96; --border: #373a40; } }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; max-width: 900px; margin: 0 auto; padding: 40px 24px; }
  h1 { font-size: 28px; margin-bottom: 8px; }
  h2 { font-size: 20px; margin: 32px 0 12px; padding-bottom: 8px; border-bottom: 2px solid var(--border); }
  p { font-size: 15px; line-height: 1.8; color: var(--text2); margin-bottom: 16px; }
  ul { padding-left: 24px; margin-bottom: 16px; }
  li { font-size: 15px; line-height: 1.7; color: var(--text2); margin-bottom: 10px; }
  .subtitle { font-size: 14px; color: var(--text3); margin-bottom: 24px; }
  .badges { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 28px; }
  .badge { border-radius: 8px; padding: 8px 14px; flex: 1; min-width: 120px; }
  .badge-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text3); margin-bottom: 2px; }
  .badge-value { font-size: 13px; font-weight: 700; }
  .control-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 10px; margin: 12px 0 24px; }
  .control-card { background: var(--bg2); border-radius: 8px; padding: 12px; border-left: 4px solid var(--blue); }
  .control-id { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px; display: inline-block; margin-bottom: 4px; }
  .control-name { font-weight: 700; font-size: 13px; }
  .control-rel { font-size: 12px; color: var(--text2); line-height: 1.5; margin: 4px 0; }
  .control-mat { font-size: 11px; color: var(--text3); font-style: italic; }
  .footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid var(--border); font-size: 12px; color: var(--text3); }
</style>
</head>
<body>
<h1>${esc(d.title)}</h1>
<p class="subtitle">Hype Cycle Innovation Profile</p>
<div class="badges">`;

    const badges = [
        { label: 'Position', value: hc.position_label, color: 'var(--blue)' },
        { label: 'Maturity', value: hc.maturity_level, color: 'var(--purple)' },
        { label: 'Benefit', value: hc.benefit_rating, color: 'var(--red)' },
        { label: 'Time to Plateau', value: hc.years_to_plateau, color: 'var(--green)' },
        { label: 'Market Penetration', value: hc.market_penetration, color: 'var(--gold)' },
    ];
    badges.forEach(b => {
        h += `<div class="badge" style="background: ${b.color}12; border: 1px solid ${b.color}33;">`;
        h += `<div class="badge-label">${b.label}</div>`;
        h += `<div class="badge-value" style="color: ${b.color};">${esc(b.value)}</div>`;
        h += `</div>`;
    });
    h += `</div>`;

    // Core sections
    const sections = [
        { title: 'Definition', content: v2.definition, type: 'text' },
        { title: 'Why This Is Important', content: v2.why_important, type: 'text' },
        { title: 'Business Impact', content: v2.business_impact, type: 'text' },
        { title: 'Drivers', content: v2.drivers, type: 'bullets' },
        { title: 'Obstacles', content: v2.obstacles, type: 'bullets' },
        { title: 'User Recommendations', content: v2.user_recommendations, type: 'bullets' },
    ];

    sections.forEach(s => {
        h += `<h2>${s.title}</h2>`;
        if (s.type === 'text') {
            h += `<p>${esc(s.content)}</p>`;
        } else {
            h += `<ul>`;
            s.content.forEach(item => { h += `<li>${esc(item)}</li>`; });
            h += `</ul>`;
        }
    });

    // SBD-AI Controls
    if (d.sbd_ai_mapping) {
        h += `<h2>SBD-AI Controls Mapping</h2>`;
        h += `<p>${esc(d.sbd_ai_mapping.description)}</p>`;
        h += `<div class="control-grid">`;
        const pillarColors = { TRM: 'var(--purple)', DSO: 'var(--blue)', REL: 'var(--green)', NDS: 'var(--gold)', IAM: 'var(--red)' };
        d.sbd_ai_mapping.primary_controls.forEach(c => {
            const clr = pillarColors[c.id.split('-')[0]] || 'var(--blue)';
            h += `<div class="control-card" style="border-left-color: ${clr};">`;
            h += `<span class="control-id" style="background: ${clr}18; color: ${clr};">${c.id}</span> `;
            h += `<span class="control-name">${esc(c.name)}</span>`;
            h += `<p class="control-rel">${esc(c.relevance)}</p>`;
            h += `<div class="control-mat">Maturity Signal: ${esc(c.maturity_signal)}</div>`;
            h += `</div>`;
        });
        h += `</div>`;
    }

    h += `<div class="footer">`;
    h += `Generated on ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}`;
    h += ` | Schema: ${esc(d.schema)}`;
    if (d.metadata) h += ` | ${esc(d.metadata.target_audience)}`;
    h += `</div>`;
    h += `</body></html>`;
    return h;
}

function _ipBuildV1HTML(d) {
    const hc = d.hype_cycle_detail;
    const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    let h = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Innovation Profile: ${esc(d.title)}</title>`;
    h += `<style>body{font-family:-apple-system,sans-serif;max-width:900px;margin:0 auto;padding:40px 24px;line-height:1.6;}h1{font-size:28px;}h2{font-size:20px;margin-top:32px;border-bottom:2px solid #dee2e6;padding-bottom:8px;}p{font-size:15px;color:#495057;}ul{padding-left:24px;}li{margin-bottom:8px;font-size:15px;color:#495057;}</style></head><body>`;
    h += `<h1>${esc(d.title)}</h1>`;
    h += `<p><em>Position: ${esc(hc.position_label)} | Benefit: ${esc(hc.benefit_rating)} | ${esc(hc.years_to_plateau)} to mainstream</em></p>`;
    h += `<h2>Summary</h2><p>${esc(d.summary)}</p>`;
    h += `<h2>Analysis</h2>`;
    h += `<h3>Overview</h3><p>${esc(d.analysis.overview)}</p>`;
    h += `<h3>Market Context</h3><p>${esc(d.analysis.market_context)}</p>`;
    h += `<h3>Knowledge Graph Role</h3><p>${esc(d.analysis.knowledge_graph_role)}</p>`;
    h += `<h3>Why It Matters</h3><p>${esc(d.analysis.why_it_matters)}</p>`;
    h += `<h2>Position Justification</h2><p>${esc(d.position_justification.current_state)}</p>`;
    h += `<h3>Evidence</h3><ul>`;
    d.position_justification.evidence_points.forEach(ep => { h += `<li>${esc(ep)}</li>`; });
    h += `</ul>`;
    h += `<h2>User Advice</h2>`;
    ['short_term','medium_term','long_term'].forEach(k => {
        const s = d.user_advice[k];
        h += `<h3>${esc(s.timeframe)}</h3><ol>`;
        s.actions.forEach(a => { h += `<li>${esc(a)}</li>`; });
        h += `</ol>`;
    });
    h += `<p style="margin-top:40px;font-size:12px;color:#868e96;">Generated on ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}</p>`;
    h += `</body></html>`;
    return h;
}

function _ipExportV2Markdown(d) {
    const v2 = d.v2;
    const hc = d.hype_cycle_detail;
    let md = '';

    md += `# Innovation Profile: ${d.title}\n\n`;
    md += `| Attribute | Value |\n|---|---|\n`;
    md += `| Position | ${hc.position_label} |\n`;
    md += `| Maturity | ${hc.maturity_level} |\n`;
    md += `| Benefit | ${hc.benefit_rating} |\n`;
    md += `| Time to Plateau | ${hc.years_to_plateau} |\n`;
    md += `| Market Penetration | ${hc.market_penetration} |\n\n---\n\n`;

    md += `## Definition\n\n${v2.definition}\n\n---\n\n`;
    md += `## Why This Is Important\n\n${v2.why_important}\n\n---\n\n`;
    md += `## Business Impact\n\n${v2.business_impact}\n\n---\n\n`;

    md += `## Drivers\n\n`;
    v2.drivers.forEach(d => { md += `- ${d}\n\n`; });
    md += `---\n\n`;

    md += `## Obstacles\n\n`;
    v2.obstacles.forEach(o => { md += `- ${o}\n\n`; });
    md += `---\n\n`;

    md += `## User Recommendations\n\n`;
    v2.user_recommendations.forEach((r, i) => { md += `${i + 1}. ${r}\n\n`; });
    md += `---\n\n`;

    // Include SBD-AI mapping
    if (d.sbd_ai_mapping) {
        md += `## SBD-AI Controls Mapping\n\n${d.sbd_ai_mapping.description}\n\n`;
        d.sbd_ai_mapping.primary_controls.forEach(c => {
            md += `### ${c.id}: ${c.name}\n\n${c.relevance}\n\n*Maturity Signal:* ${c.maturity_signal}\n\n`;
        });
        md += `---\n\n`;
    }

    md += `*Generated on ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}*\n`;
    return md;
}

