function openEditModal(type, idOrCode, name, descriptionOrDef) {
    const modal = document.getElementById('edit-modal');
    const form = document.getElementById('edit-form');
    const idField = document.getElementById('edit-id');
    const nameField = document.getElementById('edit-name');
    const descField = document.getElementById('edit-description');
    
    idField.value = idOrCode;
    nameField.value = name;
    descField.value = descriptionOrDef;
    
    // Store the type and id for saving
    form.dataset.editType = type;
    form.dataset.editId = idOrCode;
    
    modal.classList.add('show');
}

function setupEditFormHandler() {
    const form = document.getElementById('edit-form');
    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        
        const type = form.dataset.editType;
        const id = form.dataset.editId;
        const name = document.getElementById('edit-name').value;
        const description = document.getElementById('edit-description').value;
        
        try {
            const response = await fetch('/api/update-definition', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    type: type,
                    id: id,
                    name: name,
                    description: description
                })
            });
            
            if (response.ok) {
                // Close modal and refresh legend
                document.getElementById('edit-modal').classList.remove('show');
                // Reload metadata to update the display
                const metadataResponse = await fetch('/api/metadata');
                const metadata = await metadataResponse.json();
                appState.fieldMetadata = metadata.field_metadata;
                appState.scoreLegend = metadata.score_legend;
                appState.pillarsGrouped = metadata.pillars_grouped || [];
                populateLegendView();
            } else {
                alert('Failed to save changes');
            }
        } catch (error) {
            alert('Error saving changes');
        }
    });
}

function updateDashboard() {
    const vendors = appState.vendors;
    
    // Calculate statistics
    const stats = {
        total: vendors.length,
        aiFirst: vendors.filter(v => v.is_ai_first).length,
        startups: vendors.filter(v => v.is_startup).length,
        global: vendors.filter(v => v.region === 'Global').length
    };
    
    // Update stat cards
    document.getElementById('stat-total-vendors').textContent = stats.total;
    document.getElementById('stat-ai-first').textContent = stats.aiFirst;
    document.getElementById('stat-startups').textContent = stats.startups;
    document.getElementById('stat-global').textContent = stats.global;
    
    // Region distribution
    const regionDist = {};
    vendors.forEach(v => {
        regionDist[v.region] = (regionDist[v.region] || 0) + 1;
    });
    
    // Pillar averages (respects current score mode)
    const pillarAvgs = {};
    getActivePillarCodes().forEach(p => { pillarAvgs[p] = 0; });
    vendors.forEach(v => {
        const scores = getEffectivePillarScores(v);
        Object.keys(pillarAvgs).forEach(p => {
            if (scores[p]) pillarAvgs[p] += Number(scores[p]);
        });
    });
    Object.keys(pillarAvgs).forEach(p => {
        pillarAvgs[p] = (pillarAvgs[p] / vendors.length).toFixed(2);
    });
    
    // Render charts
    renderRegionChart(regionDist);
    renderPillarChart(pillarAvgs);

    // Render overall ranking table
    renderRankingTable();
}

function renderRegionChart(data) {
    const chart = document.getElementById('region-chart');
    const sorted = Object.entries(data)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 8);
    
    const maxValue = Math.max(...sorted.map(d => d[1]));
    
    chart.innerHTML = sorted.map(([region, count]) => {
        const percentage = (count / maxValue) * 100;
        return `
            <div style="margin-bottom: 12px;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                    <span style="font-size: 12px;">${region}</span>
                    <span style="font-size: 12px; font-weight: bold;">${count}</span>
                </div>
                <div style="height: 24px; background: var(--bg-tertiary); border-radius: 4px; overflow: hidden;">
                    <div style="height: 100%; width: ${percentage}%; background: linear-gradient(90deg, #0078d4, #107c10);"></div>
                </div>
            </div>
        `;
    }).join('');
}

function renderPillarChart(data) {
    const chart = document.getElementById('pillar-chart');
    const pillars = Object.entries(data).sort((a, b) => b[1] - a[1]);
    const mode = (appState.scoreMode || 'validated').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    
    chart.innerHTML = `
        <div style="font-size: 10px; color: var(--text-secondary); margin-bottom: 6px; text-align: right;">Mode: <strong>${mode}</strong></div>
        <div style="display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px;">
            ${pillars.map(([pillar, avg]) => `
                <div style="text-align: center;">
                    <div style="font-size: 20px; font-weight: bold; color: var(--color-primary);">${avg}</div>
                    <div style="font-size: 11px; color: var(--text-secondary); margin-top: 4px;">${pillar}</div>
                </div>
            `).join('')}
        </div>
    `;
}

/* ═══════════════════════════════════════════════════════════════════
   OVERALL VENDOR RANKING  –  Evidence-Quality Refined Scoring
   Score range 0-5 in 0.2 increments (25 discrete values).
   Each integer band (e.g. 4.0-4.8) has 5 sub-scores:
   4.0, 4.2, 4.4, 4.6, 4.8  –  determined by evidence quality.
   ═══════════════════════════════════════════════════════════════════ */

/**
 * Compute an evidence quality factor (0-1) for a vendor + sub-pillar.
 * Factors considered:
 *   - Number of source URLs (more diverse sources = better)
 *   - Number of excerpts / hits
 *   - Specificity ratio (specific_hit_count / hit_count)
 *   - ai_signal_score relative to base score
 *   - Total specific term count across excerpts
 * Returns a value 0..1 where 1 = strongest possible evidence.
 */
function computeEvidenceQuality(vendor, subPillarId) {
    const evidence = vendor.sub_pillar_evidence;
    if (!evidence || !evidence[subPillarId]) return 0.5; // neutral if no evidence data

    const ev = evidence[subPillarId];
    const sourceCount = Array.isArray(ev.source_urls) ? ev.source_urls.length : 0;
    const hitCount = typeof ev.hit_count === 'number' ? ev.hit_count : 0;
    const specificHits = typeof ev.specific_hit_count === 'number' ? ev.specific_hit_count : 0;
    const aiSignal = typeof ev.ai_signal_score === 'number' ? ev.ai_signal_score : 0;
    const excerpts = Array.isArray(ev.excerpts) ? ev.excerpts : [];

    // 1. Source diversity (0-1): 1 source=0.2, 2=0.5, 3=0.7, 4+=1.0
    const sourceFactor = Math.min(sourceCount / 4, 1);

    // 2. Evidence volume (0-1): based on excerpt count, cap at 6
    const volumeFactor = Math.min(excerpts.length / 6, 1);

    // 3. Specificity ratio (0-1): higher specific terms = better evidence
    let specificityFactor = 0.5;
    if (hitCount > 0) {
        specificityFactor = Math.min(specificHits / Math.max(hitCount * 2, 1), 1);
    }
    // Also look at per-excerpt specific_term_count
    let totalSpecificTerms = 0;
    excerpts.forEach(ex => {
        totalSpecificTerms += (typeof ex.specific_term_count === 'number' ? ex.specific_term_count : 0);
    });
    const termDensity = Math.min(totalSpecificTerms / Math.max(excerpts.length * 4, 1), 1);

    // 4. AI signal alignment (0-1): how close ai_signal_score is to max (5)
    const aiSignalFactor = Math.min(aiSignal / 5, 1);

    // Weighted combination
    const quality = (
        sourceFactor     * 0.15 +
        volumeFactor     * 0.20 +
        specificityFactor * 0.20 +
        termDensity      * 0.25 +
        aiSignalFactor   * 0.20
    );

    return Math.max(0, Math.min(1, quality));
}

/**
 * Refine a base score (integer 0-5) into a 0.2-increment score (e.g. 4.0-4.8)
 * based on the evidence quality factor (0-1).
 * Maps quality 0..1 → sub-score index 0..4 → offset 0.0, 0.2, 0.4, 0.6, 0.8
 */
function refineScoreWithEvidence(baseScore, evidenceQuality) {
    if (baseScore === null || baseScore === undefined || isNaN(baseScore)) return null;
    const base = Math.floor(Math.max(0, Math.min(5, baseScore)));
    // Map evidence quality (0-1) to one of 5 buckets: 0, 1, 2, 3, 4
    const bucket = Math.min(4, Math.floor(evidenceQuality * 5));
    const refined = base + bucket * 0.2;
    return Math.min(5.0, parseFloat(refined.toFixed(1)));
}

/**
 * Compute full refined scoring for a single vendor.
 * Returns: {
 *   vendor, overallAvg, refinedOverall,
 *   pillarScores: { PLA: { base, refined, subPillars: { 'PLA-01': { base, evidence, refined }, ... } }, ... },
 *   evidenceAvg
 * }
 */

/**
 * Return a color for a 0-5 score value, matching the level-N badge palette.
 *   0-1: red (#d13438)   — No evidence / No AI
 *   1-2: orange (#ff8c00) — Generic claims
 *   2-3: gold (#c19c00)   — AI-Augmented
 *   3-4: green (#107c10)  — Advanced AI
 *   4-5: blue (#005a9e)   — Fully Agentic / Best-in-class
 */
function getScoreColor(score) {
    if (score == null || isNaN(score)) return 'var(--text-secondary)';
    const s = Number(score);
    if (s >= 4)   return '#005a9e';   // blue   — strong / advanced
    if (s >= 3)   return '#107c10';   // green  — demonstrated / competitive
    if (s >= 2.5) return '#c19c00';   // gold   — below target
    if (s >= 2)   return '#ff8c00';   // orange — marketing/basic (v3 score 2)
    return '#d13438';                 // red    — no/minimal capability (v3 score 1)
}

function computeVendorRefinedScoring(vendor) {
    const pillarCodes = getActivePillarCodes();
    const pillarScores = getEffectivePillarScores(vendor);
    const granular = getEffectiveGranularMapping(vendor);
    const mode = appState.scoreMode || 'validated';
    const applyRefinement = (mode === 'evidence_refined');
    const result = { vendor: vendor.vendor, pillarData: {}, subPillarDetails: {} };

    let totalScore = 0;
    let totalBaseSum = 0;
    let pillarCount = 0;
    let evidenceSum = 0;
    let evidenceCount = 0;

    pillarCodes.forEach(pCode => {
        const group = (appState.pillarsGrouped || []).find(g => g.code === pCode);
        const subPillarIds = group
            ? (group.sub_pillars || []).map(sp => sp.id)
            : [`${pCode}-01`, `${pCode}-02`, `${pCode}-03`, `${pCode}-04`];

        const pillarGranular = granular?.[pCode] || {};
        let spScoreSum = 0;
        let spCount = 0;
        const spDetails = {};

        subPillarIds.forEach(spId => {
            const baseScore = pillarGranular[spId];
            if (baseScore === undefined || baseScore === null || isNaN(Number(baseScore))) return;
            const base = Number(baseScore);
            const evQuality = computeEvidenceQuality(vendor, spId);
            // Only apply evidence refinement when in evidence_refined mode
            const displayScore = applyRefinement ? refineScoreWithEvidence(base, evQuality) : base;

            spDetails[spId] = { base, evidenceQuality: evQuality, refined: displayScore };
            spScoreSum += displayScore;
            spCount++;
            evidenceSum += evQuality;
            evidenceCount++;
        });

        const pillarBase = pillarScores[pCode] !== undefined ? Number(pillarScores[pCode]) : null;
        const pillarDisplayScore = spCount > 0 ? parseFloat((spScoreSum / spCount).toFixed(2)) : pillarBase;

        result.pillarData[pCode] = {
            base: pillarBase,
            refined: pillarDisplayScore,
            subPillarCount: spCount
        };
        result.subPillarDetails[pCode] = spDetails;

        if (pillarDisplayScore !== null && pillarDisplayScore !== undefined) {
            totalScore += pillarDisplayScore;
            totalBaseSum += (pillarBase || 0);
            pillarCount++;
        }
    });

    result.overallBase = pillarCount > 0 ? parseFloat((totalBaseSum / pillarCount).toFixed(2)) : 0;
    result.overallRefined = pillarCount > 0 ? parseFloat((totalScore / pillarCount).toFixed(2)) : 0;
    result.evidenceAvg = evidenceCount > 0 ? parseFloat((evidenceSum / evidenceCount).toFixed(3)) : 0;
    result.pillarCount = pillarCount;

    return result;
}

/**
 * Compute rankings for all vendors, sorted by refined overall score.
 * Ties in refined score are further broken by evidence quality average.
 */
function computeOverallRanking(vendors) {
    const scored = vendors.map(v => computeVendorRefinedScoring(v));

    // Sort: primary = overallRefined DESC, secondary = evidenceAvg DESC, tertiary = vendor name ASC
    scored.sort((a, b) => {
        if (b.overallRefined !== a.overallRefined) return b.overallRefined - a.overallRefined;
        if (b.evidenceAvg !== a.evidenceAvg) return b.evidenceAvg - a.evidenceAvg;
        return a.vendor.localeCompare(b.vendor);
    });

    // Assign ranks (handle ties – same refined score = same rank)
    let rank = 1;
    scored.forEach((item, idx) => {
        if (idx > 0 && scored[idx - 1].overallRefined === item.overallRefined &&
            scored[idx - 1].evidenceAvg === item.evidenceAvg) {
            item.rank = scored[idx - 1].rank;
        } else {
            item.rank = rank;
        }
        rank = idx + 2;
    });

    return scored;
}

/**
 * Render the overall vendor ranking table on the dashboard.
 */
function renderRankingTable() {
    const container = document.getElementById('ranking-table-container');
    if (!container) return;

    const vendors = appState.vendors;
    if (!vendors || vendors.length === 0) {
        container.innerHTML = '<p style="color: var(--text-secondary); padding: 16px;">No vendor data loaded.</p>';
        return;
    }

    const ranking = computeOverallRanking(vendors);
    const topNSelect = document.getElementById('ranking-top-n');
    const topN = topNSelect ? parseInt(topNSelect.value) : 20;
    const displayData = topN > 0 ? ranking.slice(0, topN) : ranking;

    const pillarCodes = getActivePillarCodes();
    const expanded = container.classList.contains('ranking-expanded');

    // Get sub-pillar labels
    const spLabels = {};
    (appState.pillarsGrouped || []).forEach(g => {
        (g.sub_pillars || []).forEach(sp => {
            spLabels[sp.id] = sp.name || sp.id;
        });
    });

    const scoreMode = appState.scoreMode || 'validated';
    const modeLabel = scoreMode.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    const isEvMode = (scoreMode === 'evidence_refined');

    // Build header
    let headerHtml = `
        <tr>
            <th class="rank-col">Rank</th>
            <th class="vendor-col">Vendor</th>
            <th class="score-col">Score</th>`;

    if (isEvMode) {
        headerHtml += `<th class="score-col evidence-col">Ev. Qual</th>`;
    }

    pillarCodes.forEach(p => {
        headerHtml += `<th class="score-col pillar-detail-col">${p}</th>`;
        if (isEvMode) {
            headerHtml += `<th class="score-col pillar-detail-col evidence-col">${p} EQ</th>`;
        }
    });

    if (expanded) {
        pillarCodes.forEach(pCode => {
            const group = (appState.pillarsGrouped || []).find(g => g.code === pCode);
            const sps = group ? (group.sub_pillars || []) : [];
            sps.forEach(sp => {
                headerHtml += `<th class="score-col sub-pillar-detail-col" title="${spLabels[sp.id] || sp.id}">${sp.id}</th>`;
            });
        });
    }

    headerHtml += '</tr>';

    // Build rows
    let bodyHtml = '';
    displayData.forEach(item => {
        const rankClass = item.rank <= 3 ? `rank-top-${item.rank}` : '';
        const rankIcon = item.rank === 1 ? '🥇' : item.rank === 2 ? '🥈' : item.rank === 3 ? '🥉' : '';
        const evPct = (item.evidenceAvg * 100).toFixed(0);
        const evColor = item.evidenceAvg >= 0.7 ? '#107c10' : item.evidenceAvg >= 0.4 ? '#ff8c00' : '#d13438';

        bodyHtml += `<tr class="${rankClass}">`;
        bodyHtml += `<td class="rank-col">${rankIcon} ${item.rank}</td>`;
        bodyHtml += `<td class="vendor-col">${item.vendor}</td>`;
        bodyHtml += `<td class="score-col"><strong style="color:${getScoreColor(item.overallRefined)}">${item.overallRefined.toFixed(2)}</strong></td>`;

        if (isEvMode) {
            bodyHtml += `<td class="score-col evidence-col"><span style="color:${evColor}">${evPct}%</span></td>`;
        }

        pillarCodes.forEach(p => {
            const pd = item.pillarData[p];
            const scoreVal = pd && pd.refined !== null ? pd.refined : (pd && pd.base !== null ? pd.base : null);
            const scoreText = scoreVal !== null ? scoreVal.toFixed(2) : '–';
            const scoreClr = scoreVal !== null ? getScoreColor(scoreVal) : 'var(--text-secondary)';
            bodyHtml += `<td class="score-col pillar-detail-col"><span style="color:${scoreClr}">${scoreText}</span></td>`;
            if (isEvMode) {
                // Per-pillar evidence quality
                const spDetails = item.subPillarDetails[p] || {};
                const spKeys = Object.keys(spDetails);
                let pillarEv = 0;
                if (spKeys.length > 0) {
                    pillarEv = spKeys.reduce((sum, k) => sum + spDetails[k].evidenceQuality, 0) / spKeys.length;
                }
                const pillarEvPct = (pillarEv * 100).toFixed(0);
                const pillarEvColor = pillarEv >= 0.7 ? '#107c10' : pillarEv >= 0.4 ? '#ff8c00' : '#d13438';
                bodyHtml += `<td class="score-col pillar-detail-col evidence-col"><span style="color:${pillarEvColor}">${pillarEvPct}%</span></td>`;
            }
        });

        if (expanded) {
            pillarCodes.forEach(pCode => {
                const group = (appState.pillarsGrouped || []).find(g => g.code === pCode);
                const sps = group ? (group.sub_pillars || []) : [];
                const spDetails = item.subPillarDetails[pCode] || {};
                sps.forEach(sp => {
                    const d = spDetails[sp.id];
                    if (d) {
                        const spScoreColor = getScoreColor(d.refined);
                        bodyHtml += `<td class="score-col sub-pillar-detail-col" title="Base: ${d.base}, Evidence: ${(d.evidenceQuality * 100).toFixed(0)}%"><span style="color:${spScoreColor}">${d.refined.toFixed(1)}</span></td>`;
                    } else {
                        bodyHtml += `<td class="score-col sub-pillar-detail-col">–</td>`;
                    }
                });
            });
        }

        bodyHtml += '</tr>';
    });

    container.innerHTML = `
        <table class="ranking-table">
            <thead>${headerHtml}</thead>
            <tbody>${bodyHtml}</tbody>
        </table>
        <div class="ranking-footer">
            <span>Showing ${displayData.length} of ${ranking.length} vendors</span>
            <span>Score mode: <strong>${modeLabel}</strong> · Refined in 0.2 increments via evidence quality</span>
        </div>
    `;
}

// Initialize ranking controls
function initRankingControls() {
    const topNSelect = document.getElementById('ranking-top-n');
    if (topNSelect) {
        topNSelect.addEventListener('change', () => renderRankingTable());
    }

    const expandBtn = document.getElementById('ranking-expand-toggle');
    if (expandBtn) {
        expandBtn.addEventListener('click', () => {
            const container = document.getElementById('ranking-table-container');
            if (container) {
                container.classList.toggle('ranking-expanded');
                expandBtn.textContent = container.classList.contains('ranking-expanded') ? 'Detail ◂' : 'Detail ▸';
                renderRankingTable();
            }
        });
    }
}
// Analytics Tab Functions
// Widget visibility state
const DEFAULT_VISIBLE_WIDGETS = [
    'region-chart',
    'pillar-chart',
    'specialization-chart',
    'type-chart',
    'ai-chart',
    'startup-chart',
    'pillar-radar-chart',
    'comparison-radar-chart',
    'validation-comparison-chart',
    'summary-stats'
];

const widgetState = {
    visibleWidgets: new Set(DEFAULT_VISIBLE_WIDGETS)
};

// Load widget preferences from localStorage
function loadWidgetPreferences() {
    const saved = localStorage.getItem('visibleWidgets');
    if (saved) {
        try {
            widgetState.visibleWidgets = new Set(JSON.parse(saved));
        } catch {
            widgetState.visibleWidgets = new Set(DEFAULT_VISIBLE_WIDGETS);
        }

        // Migration: if new default widgets exist, show them by default
        DEFAULT_VISIBLE_WIDGETS.forEach(w => widgetState.visibleWidgets.add(w));
    }
    
    // Load widget sizes
    const savedSizes = localStorage.getItem('widgetSizes');
    if (savedSizes) {
        const sizes = JSON.parse(savedSizes);
        Object.entries(sizes).forEach(([widget, size]) => {
            const element = document.querySelector(`[data-widget="${widget}"]`);
            if (element) {
                element.style.setProperty('--col-span', size.colSpan);
                element.style.setProperty('--row-span', size.rowSpan);
                element.setAttribute('data-col-span', size.colSpan);
                element.setAttribute('data-row-span', size.rowSpan);
            }
        });
    }
}

// Save widget preferences to localStorage
function saveWidgetPreferences() {
    localStorage.setItem('visibleWidgets', JSON.stringify(Array.from(widgetState.visibleWidgets)));
    
    // Save widget sizes
    const sizes = {};
    document.querySelectorAll('[data-widget]').forEach(widget => {
        const widgetName = widget.getAttribute('data-widget');
        sizes[widgetName] = {
            colSpan: parseInt(widget.getAttribute('data-col-span')) || 1,
            rowSpan: parseInt(widget.getAttribute('data-row-span')) || 1
        };
    });
    localStorage.setItem('widgetSizes', JSON.stringify(sizes));
}

// Toggle widget visibility
function toggleWidget(widgetName, visible) {
    const widget = document.querySelector(`[data-widget="${widgetName}"]`);
    if (widget) {
        if (visible) {
            widget.classList.remove('hidden');
            widgetState.visibleWidgets.add(widgetName);
        } else {
            widget.classList.add('hidden');
            widgetState.visibleWidgets.delete(widgetName);
        }
    }
}

// Initialize widget customization UI
// Widget definitions for modal preview (type-chart label updated dynamically)
const widgetDefinitions = {
    'region-chart': 'Vendor Distribution by Region',
    'pillar-chart': 'Average Pillar Capabilities',
    'specialization-chart': 'Specialization Breakdown',
    'type-chart': 'Type Distribution',
    'ai-chart': 'AI-First vs Traditional',
    'startup-chart': 'Startup vs Established',
    'pillar-radar-chart': 'Pillar Capabilities Radar',
    'comparison-radar-chart': 'Comparison Radar (5-way)',
    'validation-comparison-chart': 'Score Layer Comparison',
    'summary-stats': 'Summary Statistics'
};

// Comparison Radar state
const comparisonRadarState = {
    type: 'vendor',
    selections: ['', '', '', '', ''],
    axes: 'pillars' // pillars | subpillars | both
};

const COMPARISON_RADAR_STORAGE_KEY = 'comparisonRadarState';

function loadComparisonRadarState() {
    try {
        const raw = localStorage.getItem(COMPARISON_RADAR_STORAGE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') {
            if (typeof parsed.type === 'string') comparisonRadarState.type = parsed.type;
            if (typeof parsed.axes === 'string') comparisonRadarState.axes = parsed.axes;
            if (Array.isArray(parsed.selections) && parsed.selections.length === 5) {
                comparisonRadarState.selections = parsed.selections.map(v => (typeof v === 'string' ? v : ''));
            }
        }
    } catch {
        // Ignore invalid persisted state
    }
}

function saveComparisonRadarState() {
    try {
        localStorage.setItem(COMPARISON_RADAR_STORAGE_KEY, JSON.stringify({
            type: comparisonRadarState.type,
            axes: comparisonRadarState.axes,
            selections: comparisonRadarState.selections
        }));
    } catch {
        // Ignore storage errors (quota, privacy mode)
    }
}

function initializeComparisonRadarWidget() {
    const typeSelect = document.getElementById('comparison-radar-type');
    if (!typeSelect) return;

    // Avoid double binding
    if (typeSelect.dataset.bound === 'true') return;
    typeSelect.dataset.bound = 'true';

    // Load persisted state (once per page load)
    if (!initializeComparisonRadarWidget._loadedState) {
        loadComparisonRadarState();
        initializeComparisonRadarWidget._loadedState = true;
    }

    typeSelect.value = comparisonRadarState.type;
    const axesSelect = document.getElementById('comparison-radar-axes');
    if (axesSelect) axesSelect.value = comparisonRadarState.axes;

    // Config modal wiring
    const configBtn = document.getElementById('comparison-radar-config-btn');
    const modal = document.getElementById('comparison-radar-config-modal');
    const closeBtn = document.getElementById('comparison-radar-config-close');
    const saveBtn = document.getElementById('comparison-radar-config-save');
    const cancelBtn = document.getElementById('comparison-radar-config-cancel');

    let draftState = {
        type: comparisonRadarState.type,
        axes: comparisonRadarState.axes,
        selections: [...comparisonRadarState.selections]
    };

    function syncInputsFromDraft() {
        if (typeSelect) typeSelect.value = draftState.type;
        if (axesSelect) axesSelect.value = draftState.axes;
        populateComparisonRadarDropdowns();
    }

    function openModal() {
        if (!modal) return;
        draftState = {
            type: comparisonRadarState.type,
            axes: comparisonRadarState.axes,
            selections: [...comparisonRadarState.selections]
        };
        syncInputsFromDraft();
        modal.classList.add('show');
    }

    function closeModal() {
        if (!modal) return;
        modal.classList.remove('show');
    }

    function applyDraftToState() {
        comparisonRadarState.type = draftState.type;
        comparisonRadarState.axes = draftState.axes;
        comparisonRadarState.selections = [...draftState.selections];
        saveComparisonRadarState();
        populateComparisonRadarDropdowns();
    }

    function cancelDraft() {
        draftState = {
            type: comparisonRadarState.type,
            axes: comparisonRadarState.axes,
            selections: [...comparisonRadarState.selections]
        };
        closeModal();
    }

    if (configBtn && !configBtn.dataset.bound) {
        configBtn.dataset.bound = 'true';
        configBtn.addEventListener('click', openModal);
    }

    if (closeBtn && !closeBtn.dataset.bound) {
        closeBtn.dataset.bound = 'true';
        closeBtn.addEventListener('click', cancelDraft);
    }

    if (cancelBtn && !cancelBtn.dataset.bound) {
        cancelBtn.dataset.bound = 'true';
        cancelBtn.addEventListener('click', cancelDraft);
    }

    if (saveBtn && !saveBtn.dataset.bound) {
        saveBtn.dataset.bound = 'true';
        saveBtn.addEventListener('click', () => {
            // Read current inputs into draft
            draftState.type = typeSelect.value;
            if (axesSelect) draftState.axes = axesSelect.value;
            ['s1', 's2', 's3', 's4', 's5'].forEach((sid, idx) => {
                const el = document.getElementById(`comparison-radar-${sid}`);
                if (el) draftState.selections[idx] = el.value;
            });

            applyDraftToState();
            renderComparisonRadar();
            closeModal();
        });
    }

    if (modal && !modal.dataset.bound) {
        modal.dataset.bound = 'true';
        modal.addEventListener('click', (e) => {
            if (e.target === modal) cancelDraft();
        });
    }

    typeSelect.addEventListener('change', () => {
        draftState.type = typeSelect.value;
        // Reset selections when changing type
        draftState.selections = ['', '', '', '', ''];
        // Keep underlying state untouched until Save
        populateComparisonRadarDropdowns();

        // Clear UI selects explicitly (so we don't preserve stale values)
        ['s1', 's2', 's3', 's4', 's5'].forEach((sid) => {
            const el = document.getElementById(`comparison-radar-${sid}`);
            if (el) el.value = '';
        });
    });

    if (axesSelect) {
        axesSelect.addEventListener('change', () => {
            draftState.axes = axesSelect.value;
        });
    }

    ['s1', 's2', 's3', 's4', 's5'].forEach((sid, idx) => {
        const el = document.getElementById(`comparison-radar-${sid}`);
        if (!el) return;
        el.addEventListener('change', () => {
            draftState.selections[idx] = el.value;
        });
    });
}

function getComparisonOptions(typeOverride = null) {
    const vendors = (appState.filteredVendors && appState.filteredVendors.length)
        ? appState.filteredVendors
        : (appState.vendors || []);
    const type = typeOverride || comparisonRadarState.type;

    if (type === 'vendor') {
        return vendors
            .map(v => v.vendor)
            .filter(Boolean)
            .sort((a, b) => String(a).localeCompare(String(b)));
    }

    if (type === 'region') {
        const regions = Array.from(new Set(vendors.map(v => v.region).filter(Boolean))).sort((a, b) => String(a).localeCompare(String(b)));
        const macros = new Set();
        const joined = regions.join(' ').toLowerCase();
        ['america', 'europe', 'emea', 'apac', 'asia', 'global', 'latam', 'middle east', 'africa'].forEach(tok => {
            if (joined.includes(tok)) macros.add(tok);
        });
        const macroList = Array.from(macros).map(s => s.replace(/\b\w/g, c => c.toUpperCase()));
        return [...regions, ...macroList];
    }

    if (type === 'ai_first') {
        return ['AI-First', 'Not AI-First'];
    }

    if (type === 'startup') {
        return ['Startup', 'Established'];
    }

    if (type === getVendorTypeField()) {
        return Array.from(new Set(vendors.map(v => v[getVendorTypeField()]).filter(Boolean))).sort((a, b) => String(a).localeCompare(String(b)));
    }

    return [];
}

function populateComparisonRadarDropdowns() {
    const typeSelect = document.getElementById('comparison-radar-type');
    const modal = document.getElementById('comparison-radar-config-modal');
    const isModalOpen = !!(modal && modal.classList.contains('show'));
    const effectiveType = typeSelect ? typeSelect.value : comparisonRadarState.type;

    const opts = getComparisonOptions(effectiveType);
    const emptyLabel = effectiveType === 'vendor' ? 'Select vendor…' : 'Select value…';
    const ids = ['s1', 's2', 's3', 's4', 's5'];

    const previousValues = ids.map((sid) => {
        const el = document.getElementById(`comparison-radar-${sid}`);
        return el ? el.value : '';
    });

    ids.forEach((sid, idx) => {
        const el = document.getElementById(`comparison-radar-${sid}`);
        if (!el) return;
        el.innerHTML = '';

        const empty = document.createElement('option');
        empty.value = '';
        empty.textContent = `${idx + 1}: ${emptyLabel}`;
        el.appendChild(empty);

        opts.forEach(v => {
            const opt = document.createElement('option');
            opt.value = String(v);
            opt.textContent = String(v);
            el.appendChild(opt);
        });

        const desired = (isModalOpen ? previousValues[idx] : (comparisonRadarState.selections[idx] || ''));
        const hasOption = desired && Array.from(el.options).some(o => o.value === desired);
        el.value = hasOption ? desired : '';

        if (!isModalOpen && desired && !hasOption) {
            comparisonRadarState.selections[idx] = '';
            saveComparisonRadarState();
        }
    });
}

function matchVendorsForSelection(selectionValue, vendorsForAverages) {
    const allVendors = appState.vendors || [];
    const type = comparisonRadarState.type;
    const val = (selectionValue || '').trim();
    if (!val) return { label: '', vendors: [] };

    if (type === 'vendor') {
        const v = allVendors.find(x => String(x.vendor) === val);
        return { label: val, vendors: v ? [v] : [] };
    }

    if (type === 'region') {
        const needle = val.toLowerCase();
        const matched = (vendorsForAverages || []).filter(v => String(v.region || '').toLowerCase().includes(needle));
        return { label: val, vendors: matched };
    }

    if (type === 'ai_first') {
        const want = val === 'AI-First';
        const matched = (vendorsForAverages || []).filter(v => !!v.is_ai_first === want);
        return { label: val, vendors: matched };
    }

    if (type === 'startup') {
        const want = val === 'Startup';
        const matched = (vendorsForAverages || []).filter(v => !!v.is_startup === want);
        return { label: val, vendors: matched };
    }

    if (type === getVendorTypeField()) {
        const matched = (vendorsForAverages || []).filter(v => String(v[getVendorTypeField()] || '') === val);
        return { label: val, vendors: matched };
    }

    return { label: val, vendors: [] };
}

function computePillarAveragesForVendors(vendors) {
    const pillars = getActivePillarCodes();
    const sums = {};
    const counts = {};
    pillars.forEach(p => { sums[p] = 0; counts[p] = 0; });

    (vendors || []).forEach(v => {
        const scores = getEffectivePillarScores(v) || {};
        pillars.forEach(p => {
            const x = scores[p];
            if (x !== undefined && x !== null && x !== '' && !Number.isNaN(Number(x))) {
                sums[p] += Number(x);
                counts[p] += 1;
            }
        });
    });

    const out = {};
    pillars.forEach(p => {
        out[p] = counts[p] ? (sums[p] / counts[p]) : 0;
    });
    return out;
}

function computeSubPillarAveragesForVendors(vendors) {
    const ordered = (appState.subPillars || []).map(s => s.id);
    const sums = {};
    const counts = {};
    ordered.forEach(id => { sums[id] = 0; counts[id] = 0; });

    (vendors || []).forEach(v => {
        const mapping = getEffectiveGranularMapping(v) || {};
        Object.values(mapping).forEach(pillarObj => {
            if (!pillarObj || typeof pillarObj !== 'object') return;
            Object.entries(pillarObj).forEach(([sid, val]) => {
                if (!(sid in sums)) return;
                const n = Number(val);
                if (Number.isNaN(n)) return;
                sums[sid] += n;
                counts[sid] += 1;
            });
        });
    });

    const out = {};
    ordered.forEach(id => {
        out[id] = counts[id] ? (sums[id] / counts[id]) : 0;
    });
    return out;
}

function renderComparisonRadar(vendorsForAverages = null) {
    const container = document.getElementById('comparison-radar-chart');
    if (!container) return;
    // Don't do work if widget is hidden
    const widgetEl = container.closest('[data-widget="comparison-radar-chart"]');
    if (widgetEl && widgetEl.classList.contains('hidden')) return;

    const baseVendors = vendorsForAverages || appState.filteredVendors || appState.vendors || [];
    const pillarAxes = getActivePillarCodes();
    const subPillarAxes = (appState.subPillars || []).map(s => s.id);
    const axesMode = comparisonRadarState.axes || 'pillars';
    const axes = axesMode === 'subpillars'
        ? subPillarAxes
        : axesMode === 'both'
            ? [...pillarAxes, ...subPillarAxes]
            : pillarAxes;

    const seriesColors = [
        { stroke: '#0078d4', fill: 'rgba(0, 120, 212, 0.18)' },
        { stroke: '#107c10', fill: 'rgba(16, 124, 16, 0.18)' },
        { stroke: '#d83b01', fill: 'rgba(216, 59, 1, 0.18)' },
        { stroke: '#5c2d91', fill: 'rgba(92, 45, 145, 0.18)' },
        { stroke: '#a4262c', fill: 'rgba(164, 38, 44, 0.18)' }
    ];

    const selected = comparisonRadarState.selections
        .map((v, idx) => ({ v, idx }))
        .filter(x => x.v && x.v.trim().length > 0);

    if (selected.length === 0) {
        container.innerHTML = '<div style="color: var(--text-secondary); font-size: 12px; padding: 10px;">Click the gear (⚙) to configure up to 5 comparison series.</div>';
        return;
    }

    const computedSeries = selected.map(({ v, idx }) => {
        const { label, vendors } = matchVendorsForSelection(v, baseVendors);
        const pillarAvg = computePillarAveragesForVendors(vendors);
        const subAvg = computeSubPillarAveragesForVendors(vendors);
        const scores = axes.map(a => (pillarAxes.includes(a) ? (pillarAvg[a] || 0) : (subAvg[a] || 0)));
        return {
            label,
            count: (vendors || []).length,
            scores,
            color: seriesColors[idx % seriesColors.length]
        };
    }).filter(s => s.count > 0 || comparisonRadarState.type === 'vendor');

    const { width: measuredWidth, height: measuredHeight } = _getSafeContainerDimensions(container, {
        minWidth: 320,
        minHeight: 260,
        fallbackWidth: 600,
        fallbackHeight: 420
    });
    const { width, height, cx, cy, radius } = _getSafeRadarGeometry({ width: measuredWidth, height: measuredHeight, padding: 40 });

    const scaleMax = 5;
    const radar = _getRadarAxisLayout({ axes, cx, cy, denseFont: 8, mediumFont: 9, sparseFont: 12 });

    // Background + grid
    let svg = `
        <svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Comparison radar chart">
            <rect x="0" y="0" width="${width}" height="${height}" fill="transparent" />
    `;

    // Rings
    for (let i = 1; i <= scaleMax; i++) {
        const r = (radius * i) / scaleMax;
        svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border-color)" stroke-width="1" opacity="0.6" />`;
    }

    // Axes + labels
    radar.entries.forEach(({ axis: p, i, angle: a }) => {
        const end = radar.pt(a, radius);
        svg += `<line x1="${cx}" y1="${cy}" x2="${end.x}" y2="${end.y}" stroke="var(--border-color)" stroke-width="1" opacity="0.8" />`;

        if (i % radar.labelEvery === 0) {
            const labelPos = radar.pt(a, radius + 16);
            const anchor = (Math.cos(a) > 0.2) ? 'start' : (Math.cos(a) < -0.2) ? 'end' : 'middle';
            svg += `<text x="${labelPos.x}" y="${labelPos.y}" font-size="${radar.labelFont}" fill="var(--text-secondary)" text-anchor="${anchor}" dominant-baseline="middle"><title>${p}</title>${p}</text>`;
        }
    });

    // Series polygons
    computedSeries.forEach((s) => {
        const points = s.scores.map((val, i) => {
            const a = radar.angleForIndex(i);
            const r = radius * (Math.max(0, Math.min(scaleMax, Number(val))) / scaleMax);
            const p = radar.pt(a, r);
            return `${p.x},${p.y}`;
        }).join(' ');

        svg += `<polygon points="${points}" fill="${s.color.fill}" stroke="${s.color.stroke}" stroke-width="2" />`;
        // Dots
        s.scores.forEach((val, i) => {
            const a = radar.angleForIndex(i);
            const r = radius * (Math.max(0, Math.min(scaleMax, Number(val))) / scaleMax);
            const p = radar.pt(a, r);
            svg += `<circle cx="${p.x}" cy="${p.y}" r="3" fill="${s.color.stroke}" />`;
        });
    });

    svg += `</svg>`;

    const legend = computedSeries.map((s, i) => {
        const suffix = comparisonRadarState.type === 'vendor' ? '' : ` (n=${s.count})`;
        return `
            <div style="display:flex; align-items:center; gap:8px; font-size:12px; color:var(--text-secondary); margin:2px 0;">
                <span style="display:inline-block; width:10px; height:10px; border-radius:2px; background:${s.color.stroke};"></span>
                <span>${s.label}${suffix}</span>
            </div>
        `;
    }).join('');

    container.innerHTML = `
        <div style="display:grid; grid-template-columns: 1fr 220px; gap: 12px; align-items: start; height: 100%;">
            <div style="min-width: 0;">${svg}</div>
            <div style="padding: 8px; border: 1px solid var(--border-color); border-radius: 8px; background: var(--bg-secondary);">
                <div style="font-weight: 600; font-size: 12px; color: var(--text-primary); margin-bottom: 6px;">Series</div>
                ${legend}
                <div style="margin-top: 8px; font-size: 11px; color: var(--text-secondary);">
                    Uses <strong>${appState.scoreMode}</strong> scores (${axesMode}).
                </div>
            </div>
        </div>
    `;
}

// ==================== Researched vs Validated Comparison Widget ====================

const validationComparisonState = {
    categoryType: 'all',  // all | region | startup | ai_first | ir_focus_type
    categoryValue: '',    // e.g., "Global", "Startup"
    axes: 'pillars',      // pillars | subpillars | both
    showDelta: true       // Show delta/difference metrics
};

const VALIDATION_COMPARISON_STORAGE_KEY = 'validationComparisonState';

function loadValidationComparisonState() {
    try {
        const raw = localStorage.getItem(VALIDATION_COMPARISON_STORAGE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') {
            if (typeof parsed.categoryType === 'string') validationComparisonState.categoryType = parsed.categoryType;
            if (typeof parsed.categoryValue === 'string') validationComparisonState.categoryValue = parsed.categoryValue;
            if (typeof parsed.axes === 'string') validationComparisonState.axes = parsed.axes;
            if (typeof parsed.showDelta === 'boolean') validationComparisonState.showDelta = parsed.showDelta;
        }
    } catch {
        // Ignore invalid persisted state
    }
}

function saveValidationComparisonState() {
    try {
        localStorage.setItem(VALIDATION_COMPARISON_STORAGE_KEY, JSON.stringify({
            categoryType: validationComparisonState.categoryType,
            categoryValue: validationComparisonState.categoryValue,
            axes: validationComparisonState.axes,
            showDelta: validationComparisonState.showDelta
        }));
    } catch {
        // Ignore storage errors
    }
}

function getValidationComparisonCategoryValues(categoryType) {
    const vendors = appState.filteredVendors || appState.vendors || [];
    
    if (categoryType === 'all') {
        return [];
    }
    
    if (categoryType === 'region') {
        return Array.from(new Set(vendors.map(v => v.region).filter(Boolean))).sort((a, b) => String(a).localeCompare(String(b)));
    }
    
    if (categoryType === 'startup') {
        return ['Startup', 'Established'];
    }
    
    if (categoryType === 'ai_first') {
        return ['AI-First', 'Traditional'];
    }
    
    if (categoryType === getVendorTypeField()) {
        return Array.from(new Set(vendors.map(v => v[getVendorTypeField()]).filter(Boolean))).sort((a, b) => String(a).localeCompare(String(b)));
    }
    
    return [];
}

function filterVendorsByValidationCategory(vendors, categoryType, categoryValue) {
    if (!categoryType || categoryType === 'all') return vendors;
    
    const val = categoryValue.toLowerCase();
    return (vendors || []).filter(v => {
        if (categoryType === 'region') {
            return String(v.region || '').toLowerCase().includes(val);
        }
        if (categoryType === 'startup') {
            const want = val === 'startup';
            return !!v.is_startup === want;
        }
        if (categoryType === 'ai_first') {
            const want = val === 'ai-first';
            return !!v.is_ai_first === want;
        }
        if (categoryType === getVendorTypeField()) {
            return String(v[getVendorTypeField()] || '') === categoryValue;
        }
        return false;
    });
}

function initializeValidationComparisonWidget() {
    const configBtn = document.getElementById('validation-comparison-config-btn');
    const modal = document.getElementById('validation-comparison-config-modal');
    const closeBtn = document.getElementById('validation-comparison-config-close');
    const saveBtn = document.getElementById('validation-comparison-config-save');
    const cancelBtn = document.getElementById('validation-comparison-config-cancel');
    
    if (!configBtn || !modal) return;
    
    if (!initializeValidationComparisonWidget._loadedState) {
        loadValidationComparisonState();
        initializeValidationComparisonWidget._loadedState = true;
    }
    
    const categoryTypeSelect = document.getElementById('validation-comparison-category-type');
    const categoryValueSelect = document.getElementById('validation-comparison-category-value');
    const axesSelect = document.getElementById('validation-comparison-axes');
    const showDeltaCheckbox = document.getElementById('validation-comparison-show-delta');
    
    let draftState = JSON.parse(JSON.stringify(validationComparisonState));
    
    function populateCategoryValues() {
        const categoryType = draftState.categoryType;
        const values = getValidationComparisonCategoryValues(categoryType);
        
        categoryValueSelect.innerHTML = categoryType === 'all' 
            ? '<option value="">N/A - All Vendors</option>'
            : '<option value="">Select...</option>';
        
        values.forEach(v => {
            const opt = document.createElement('option');
            opt.value = v;
            opt.textContent = v;
            categoryValueSelect.appendChild(opt);
        });
        
        categoryValueSelect.disabled = categoryType === 'all';
        categoryValueSelect.value = categoryType === 'all' ? '' : (draftState.categoryValue || '');
    }
    
    function openModal() {
        draftState = JSON.parse(JSON.stringify(validationComparisonState));
        categoryTypeSelect.value = draftState.categoryType;
        axesSelect.value = draftState.axes;
        showDeltaCheckbox.checked = draftState.showDelta;
        populateCategoryValues();
        modal.classList.add('show');
    }
    
    function closeModal() {
        modal.classList.remove('show');
    }
    
    function applyDraftToState() {
        validationComparisonState.categoryType = draftState.categoryType;
        validationComparisonState.categoryValue = draftState.categoryValue;
        validationComparisonState.axes = draftState.axes;
        validationComparisonState.showDelta = draftState.showDelta;
        saveValidationComparisonState();
        renderValidationComparison();
        closeModal();
    }
    
    if (configBtn && !configBtn.dataset.bound) {
        configBtn.dataset.bound = 'true';
        configBtn.addEventListener('click', openModal);
    }
    
    if (closeBtn && !closeBtn.dataset.bound) {
        closeBtn.dataset.bound = 'true';
        closeBtn.addEventListener('click', () => {
            draftState = JSON.parse(JSON.stringify(validationComparisonState));
            closeModal();
        });
    }
    
    if (cancelBtn && !cancelBtn.dataset.bound) {
        cancelBtn.dataset.bound = 'true';
        cancelBtn.addEventListener('click', () => {
            draftState = JSON.parse(JSON.stringify(validationComparisonState));
            closeModal();
        });
    }
    
    if (saveBtn && !saveBtn.dataset.bound) {
        saveBtn.dataset.bound = 'true';
        saveBtn.addEventListener('click', () => {
            draftState.categoryType = categoryTypeSelect.value;
            draftState.categoryValue = categoryValueSelect.value;
            draftState.axes = axesSelect.value;
            draftState.showDelta = showDeltaCheckbox.checked;
            applyDraftToState();
        });
    }
    
    if (categoryTypeSelect && !categoryTypeSelect.dataset.bound) {
        categoryTypeSelect.dataset.bound = 'true';
        categoryTypeSelect.addEventListener('change', () => {
            draftState.categoryType = categoryTypeSelect.value;
            draftState.categoryValue = '';
            populateCategoryValues();
        });
    }
    
    if (categoryValueSelect && !categoryValueSelect.dataset.bound) {
        categoryValueSelect.dataset.bound = 'true';
        categoryValueSelect.addEventListener('change', () => {
            draftState.categoryValue = categoryValueSelect.value;
        });
    }
    
    if (modal && !modal.dataset.bound) {
        modal.dataset.bound = 'true';
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                draftState = JSON.parse(JSON.stringify(validationComparisonState));
                closeModal();
            }
        });
    }
}

function computeAveragesForScoreMode(vendors, scoreMode) {
    const pillars = getActivePillarCodes();
    const subPillars = (appState.subPillars || []).map(s => s.id);
    
    const pillarSums = {};
    const pillarCounts = {};
    pillars.forEach(p => { pillarSums[p] = 0; pillarCounts[p] = 0; });
    const subPillarSums = {};;
    const subPillarCounts = {};
    
    subPillars.forEach(id => { subPillarSums[id] = 0; subPillarCounts[id] = 0; });
    
    (vendors || []).forEach(v => {
        // Get scores based on mode
        let pillarScores, subPillarScores;
        
        if (scoreMode === 'evidence_refined') {
            pillarScores = v.pillar_scores_evidence_refined || {};
            subPillarScores = v.sub_pillar_scores_evidence_refined || {};
            
            if (!v.pillar_scores_evidence_refined && subPillarScores && Object.keys(subPillarScores).length > 0) {
                pillarScores = buildPillarScoresFromSubPillars(subPillarScores);
            }
        } else if (scoreMode === 'ai_researched') {
            pillarScores = v.pillar_scores_ai_researched || {};
            subPillarScores = v.sub_pillar_scores_ai_researched || {};
            
            if (!v.pillar_scores_ai_researched && subPillarScores && Object.keys(subPillarScores).length > 0) {
                pillarScores = buildPillarScoresFromSubPillars(subPillarScores);
            }
        } else if (scoreMode === 'researched') {
            pillarScores = v.pillar_scores_researched || {};
            subPillarScores = v.sub_pillar_scores_researched || {};
            
            if (!v.pillar_scores_researched && subPillarScores && Object.keys(subPillarScores).length > 0) {
                pillarScores = buildPillarScoresFromSubPillars(subPillarScores);
            }
        } else if (scoreMode === 'v2_researched') {
            pillarScores = v.pillar_scores_v2_researched || {};
            subPillarScores = v.sub_pillar_scores_v2_researched || {};
            
            if (!v.pillar_scores_v2_researched && subPillarScores && Object.keys(subPillarScores).length > 0) {
                pillarScores = buildPillarScoresFromSubPillars(subPillarScores);
            }
        } else if (scoreMode === 'current') {
            subPillarScores = v.sub_pillar_scores_current || v.sub_pillar_scores || {};
            pillarScores = v.pillar_gtm_scores || buildPillarScoresFromSubPillars(subPillarScores);
        } else {
            // validated
            pillarScores = v.pillar_scores_validated || v.pillar_scores || v.pillar_gtm_scores || {};
            subPillarScores = v.sub_pillar_scores_validated || v.sub_pillar_scores || {};
        }
        
        // Accumulate pillar scores
        pillars.forEach(p => {
            const val = pillarScores[p];
            if (val !== undefined && val !== null && !Number.isNaN(Number(val))) {
                pillarSums[p] += Number(val);
                pillarCounts[p] += 1;
            }
        });
        
        // Accumulate sub-pillar scores directly from sub_pillar_scores object
        Object.entries(subPillarScores || {}).forEach(([sid, val]) => {
            if (!(sid in subPillarSums)) return;
            // PMR dual-score format: val is {gtm_messaging_score, ...}
            const raw = (val && typeof val === 'object' && !Array.isArray(val)) ? val.gtm_messaging_score : val;
            const n = Number(raw);
            if (Number.isNaN(n)) return;
            subPillarSums[sid] += n;
            subPillarCounts[sid] += 1;
        });
    });
    
    const pillarAvgs = {};
    pillars.forEach(p => {
        pillarAvgs[p] = pillarCounts[p] ? (pillarSums[p] / pillarCounts[p]) : 0;
    });
    
    const subPillarAvgs = {};
    subPillars.forEach(id => {
        subPillarAvgs[id] = subPillarCounts[id] ? (subPillarSums[id] / subPillarCounts[id]) : 0;
    });
    
    return { pillars: pillarAvgs, subPillars: subPillarAvgs, vendorCount: vendors.length };
}

function buildPillarScoresFromSubPillars(subPillarScores) {
    const pillars = {};
    getActivePillarCodes().forEach(p => { pillars[p] = []; });
    
    Object.entries(subPillarScores || {}).forEach(([subId, score]) => {
        const pillarCode = subId.split('-')[0];
        if (pillars[pillarCode]) {
            pillars[pillarCode].push(Number(score));
        }
    });
    
    const result = {};
    Object.entries(pillars).forEach(([pillar, scores]) => {
        if (scores.length > 0) {
            result[pillar] = scores.reduce((a, b) => a + b, 0) / scores.length;
        } else {
            result[pillar] = 0;
        }
    });
    
    return result;
}

function _getSafeContainerDimensions(container, options = {}) {
    const {
        minWidth = 320,
        minHeight = 260,
        fallbackWidth = 600,
        fallbackHeight = 420
    } = options;

    const parentWidth = container?.parentElement?.clientWidth || container?.parentElement?.offsetWidth || 0;
    const parentHeight = container?.parentElement?.clientHeight || container?.parentElement?.offsetHeight || 0;
    const width = Math.max(minWidth, container?.clientWidth || container?.offsetWidth || parentWidth || fallbackWidth);
    const height = Math.max(minHeight, container?.clientHeight || container?.offsetHeight || parentHeight || fallbackHeight);

    return { width, height };
}

function _getSafeRadarGeometry({ width, height, padding }) {
    const safeWidth = Math.max(160, Number(width) || 0);
    const safeHeight = Math.max(160, Number(height) || 0);
    const safePadding = Math.max(0, Number(padding) || 0);
    const radius = Math.max(24, (Math.min(safeWidth, safeHeight) / 2) - safePadding);

    return {
        width: safeWidth,
        height: safeHeight,
        padding: safePadding,
        cx: safeWidth / 2,
        cy: safeHeight / 2,
        radius
    };
}

function _getRadarAxisLayout({ axes = [], cx, cy, denseFont = 8, mediumFont = 9, sparseFont = 10 }) {
    const axisCount = Math.max(axes.length, 1);
    const angleStep = (Math.PI * 2) / axisCount;
    const startAngle = -Math.PI / 2;
    const labelEvery = axes.length > 22 ? 3 : axes.length > 12 ? 2 : 1;
    const labelFont = axes.length > 22 ? denseFont : axes.length > 12 ? mediumFont : sparseFont;

    function pt(angle, r) {
        return { x: cx + Math.cos(angle) * r, y: cy + Math.sin(angle) * r };
    }

    function angleForIndex(i) {
        return startAngle + i * angleStep;
    }

    const entries = axes.map((axis, i) => ({ axis, i, angle: angleForIndex(i) }));

    return {
        axisCount,
        angleStep,
        startAngle,
        labelEvery,
        labelFont,
        pt,
        angleForIndex,
        entries
    };
}

function renderValidationRadar(container, data, title) {
    const pillarAxes = getActivePillarCodes();
    const subPillarAxes = (appState.subPillars || []).map(s => s.id);
    const axesMode = validationComparisonState.axes || 'pillars';
    const axes = axesMode === 'subpillars'
        ? subPillarAxes
        : axesMode === 'both'
            ? [...pillarAxes, ...subPillarAxes]
            : pillarAxes;
    
    // Use fixed dimensions - SVG will scale responsively via viewBox
    const { width, height, cx, cy, radius } = _getSafeRadarGeometry({ width: 350, height: 320, padding: 35 });
    
    const scaleMax = 5;
    const radar = _getRadarAxisLayout({ axes, cx, cy, denseFont: 8, mediumFont: 9, sparseFont: 10 });
    
    // Build SVG
    let svg = `
        <svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${title} radar chart">
            <rect x="0" y="0" width="${width}" height="${height}" fill="transparent" />
    `;
    
    // Rings
    for (let i = 1; i <= scaleMax; i++) {
        const r = (radius * i) / scaleMax;
        svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border-color)" stroke-width="1" opacity="0.6" />`;
    }
    
    // Axes
    radar.entries.forEach(({ axis: p, i, angle: a }) => {
        const end = radar.pt(a, radius);
        svg += `<line x1="${cx}" y1="${cy}" x2="${end.x}" y2="${end.y}" stroke="var(--border-color)" stroke-width="1" opacity="0.8" />`;
        
        if (i % radar.labelEvery === 0) {
            const labelPos = radar.pt(a, radius + 14);
            const anchor = (Math.cos(a) > 0.2) ? 'start' : (Math.cos(a) < -0.2) ? 'end' : 'middle';
            svg += `<text x="${labelPos.x}" y="${labelPos.y}" font-size="${radar.labelFont}" fill="var(--text-secondary)" text-anchor="${anchor}" dominant-baseline="middle"><title>${p}</title>${p}</text>`;
        }
    });
    
    // Data polygon
    const points = axes.map((axis, i) => {
        const val = pillarAxes.includes(axis) ? data.pillars[axis] : data.subPillars[axis];
        const a = radar.angleForIndex(i);
        const r = radius * (Math.max(0, Math.min(scaleMax, Number(val || 0))) / scaleMax);
        const p = radar.pt(a, r);
        return `${p.x},${p.y}`;
    }).join(' ');
    
    const color = title.includes('Researched') 
        ? { stroke: '#0078d4', fill: 'rgba(0, 120, 212, 0.18)' }
        : { stroke: '#107c10', fill: 'rgba(16, 124, 16, 0.18)' };
    
    svg += `<polygon points="${points}" fill="${color.fill}" stroke="${color.stroke}" stroke-width="2" />`;
    
    // Dots
    axes.forEach((axis, i) => {
        const val = pillarAxes.includes(axis) ? data.pillars[axis] : data.subPillars[axis];
        const a = radar.angleForIndex(i);
        const r = radius * (Math.max(0, Math.min(scaleMax, Number(val || 0))) / scaleMax);
        const p = radar.pt(a, r);
        svg += `<circle cx="${p.x}" cy="${p.y}" r="3" fill="${color.stroke}" />`;
    });
    
    svg += `</svg>`;
    
    container.innerHTML = svg;
}

function renderValidationRadarOverlay(container, researchedData, validatedData, aiResearchedData) {
    const pillarAxes = getActivePillarCodes();
    const subPillarAxes = (appState.subPillars || []).map(s => s.id);
    const axesMode = validationComparisonState.axes || 'pillars';
    const axes = axesMode === 'subpillars'
        ? subPillarAxes
        : axesMode === 'both'
            ? [...pillarAxes, ...subPillarAxes]
            : pillarAxes;
    
    // Use fixed dimensions - SVG will scale responsively via viewBox
    const { width, height, cx, cy, radius } = _getSafeRadarGeometry({ width: 450, height: 400, padding: 40 });
    
    const scaleMax = 5;
    const radar = _getRadarAxisLayout({ axes, cx, cy, denseFont: 8, mediumFont: 9, sparseFont: 10 });
    
    // Build SVG
    let svg = `
        <svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Score Comparison radar chart">
            <defs>
                <filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">
                    <feDropShadow dx="0" dy="0" stdDeviation="1" flood-opacity="0.1"/>
                </filter>
            </defs>
            <rect x="0" y="0" width="${width}" height="${height}" fill="transparent" />
    `;
    
    // Rings
    for (let i = 1; i <= scaleMax; i++) {
        const r = (radius * i) / scaleMax;
        svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border-color)" stroke-width="1" opacity="0.6" />`;
    }
    
    // Scale labels
    svg += `<text x="${cx + 10}" y="${cy - radius - 8}" font-size="10" fill="var(--text-secondary)" opacity="0.7">5</text>`;
    svg += `<text x="${cx + 10}" y="${cy - radius * 0.8 - 8}" font-size="10" fill="var(--text-secondary)" opacity="0.7">4</text>`;
    svg += `<text x="${cx + 10}" y="${cy - radius * 0.6 - 8}" font-size="10" fill="var(--text-secondary)" opacity="0.7">3</text>`;
    
    // Axes
    radar.entries.forEach(({ axis: p, i, angle: a }) => {
        const end = radar.pt(a, radius);
        svg += `<line x1="${cx}" y1="${cy}" x2="${end.x}" y2="${end.y}" stroke="var(--border-color)" stroke-width="1" opacity="0.8" />`;
        
        if (i % radar.labelEvery === 0) {
            const labelPos = radar.pt(a, radius + 18);
            const anchor = (Math.cos(a) > 0.2) ? 'start' : (Math.cos(a) < -0.2) ? 'end' : 'middle';
            svg += `<text x="${labelPos.x}" y="${labelPos.y}" font-size="${radar.labelFont}" fill="var(--text-secondary)" text-anchor="${anchor}" dominant-baseline="middle"><title>${p}</title>${p}</text>`;
        }
    });
    
    // Render all polygons (validated first as base, then researched, then ai_researched on top)
    const datasets = [
        { data: validatedData, color: { stroke: '#107c10', fill: 'rgba(16, 124, 16, 0.15)' }, title: 'Validated' },
        { data: researchedData, color: { stroke: '#0078d4', fill: 'rgba(0, 120, 212, 0.15)' }, title: 'Researched' }
    ];
    
    if (aiResearchedData) {
        datasets.push({ data: aiResearchedData, color: { stroke: '#8b5cf6', fill: 'rgba(139, 92, 246, 0.15)' }, title: 'AI Researched' });
    }
    
    datasets.forEach(dataset => {
        const points = axes.map((axis, i) => {
            const val = pillarAxes.includes(axis) ? dataset.data.pillars[axis] : dataset.data.subPillars[axis];
            const a = radar.angleForIndex(i);
            const r = radius * (Math.max(0, Math.min(scaleMax, Number(val || 0))) / scaleMax);
            const p = radar.pt(a, r);
            return `${p.x},${p.y}`;
        }).join(' ');
        
        svg += `<polygon points="${points}" fill="${dataset.color.fill}" stroke="${dataset.color.stroke}" stroke-width="2.5" filter="url(#shadow)" />`;
        
        // Dots
        axes.forEach((axis, i) => {
            const val = pillarAxes.includes(axis) ? dataset.data.pillars[axis] : dataset.data.subPillars[axis];
            const a = radar.angleForIndex(i);
            const r = radius * (Math.max(0, Math.min(scaleMax, Number(val || 0))) / scaleMax);
            const p = radar.pt(a, r);
            svg += `<circle cx="${p.x}" cy="${p.y}" r="3.5" fill="${dataset.color.stroke}" stroke="white" stroke-width="1.5" />`;
        });
    });
    
    svg += `</svg>`;
    
    container.innerHTML = svg;
}

function renderValidationComparison(vendorsForAverages = null) {
    const container = document.getElementById('validation-comparison-chart');
    if (!container) return;
    
    const widgetEl = container.closest('[data-widget="validation-comparison-chart"]');
    if (widgetEl && widgetEl.classList.contains('hidden')) return;
    
    const baseVendors = vendorsForAverages || appState.filteredVendors || appState.vendors || [];
    const categoryType = validationComparisonState.categoryType;
    const categoryValue = validationComparisonState.categoryValue;
    
    const filteredVendors = filterVendorsByValidationCategory(baseVendors, categoryType, categoryValue);
    
    if (filteredVendors.length === 0) {
        container.innerHTML = '<div style="color: var(--text-secondary); font-size: 12px; padding: 16px; text-align: center;">No vendors match the selected category. Click the gear (⚙) to configure.</div>';
        return;
    }
    
    const researchedData = computeAveragesForScoreMode(filteredVendors, 'researched');
    const validatedData = computeAveragesForScoreMode(filteredVendors, 'validated');
    const aiResearchedData = computeAveragesForScoreMode(filteredVendors, 'ai_researched');
    
    const categoryLabel = categoryType === 'all' 
        ? 'All Vendors'
        : `${categoryType.toUpperCase()}: ${categoryValue}`;
    
    // Build HTML structure
    let html = `
        <div style="display: flex; flex-direction: column; gap: 12px; padding: 12px;">
            <div style="font-size: 13px; color: var(--text-primary); font-weight: 500; text-align: center;">
                ${categoryLabel} (n=${filteredVendors.length})
            </div>
            <div style="display: flex; gap: 16px; justify-content: center; font-size: 12px; flex-wrap: wrap;">
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="display: inline-block; width: 12px; height: 2px; background: #107c10;"></span>
                    <span style="color: #107c10;">Validated</span>
                </div>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="display: inline-block; width: 12px; height: 2px; background: #0078d4;"></span>
                    <span style="color: #0078d4;">Researched</span>
                </div>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span style="display: inline-block; width: 12px; height: 2px; background: #8b5cf6;"></span>
                    <span style="color: #8b5cf6;">AI Researched</span>
                </div>
            </div>
            <div class="validation-comparison-radar-container">
                <div class="validation-comparison-radar-section" style="grid-column: 1 / -1;">
                    <div class="validation-comparison-radar-chart" id="overlay-radar"></div>
                </div>
            </div>
    `;
    
    if (validationComparisonState.showDelta) {
        const pillarAxes = getActivePillarCodes();
        const subPillarAxes = (appState.subPillars || []).map(s => s.id);
        const axesMode = validationComparisonState.axes || 'pillars';
        const axes = axesMode === 'subpillars'
            ? subPillarAxes
            : axesMode === 'both'
                ? [...pillarAxes, ...subPillarAxes]
                : pillarAxes;
        
        const deltaRows = axes.map(axis => {
            const isSubPillar = !pillarAxes.includes(axis);
            const resValue = isSubPillar ? (researchedData.subPillars[axis] || 0) : (researchedData.pillars[axis] || 0);
            const valValue = isSubPillar ? (validatedData.subPillars[axis] || 0) : (validatedData.pillars[axis] || 0);
            const aiValue = isSubPillar ? (aiResearchedData.subPillars[axis] || 0) : (aiResearchedData.pillars[axis] || 0);
            const deltaRV = valValue - resValue;
            const deltaRA = aiValue - resValue;
            const deltaRVClass = deltaRV > 0.05 ? 'validation-comparison-delta-positive' : deltaRV < -0.05 ? 'validation-comparison-delta-negative' : 'validation-comparison-delta-neutral';
            const deltaRAClass = deltaRA > 0.05 ? 'validation-comparison-delta-positive' : deltaRA < -0.05 ? 'validation-comparison-delta-negative' : 'validation-comparison-delta-neutral';
            
            return `
                <tr>
                    <td>${axis}</td>
                    <td style="color: #107c10;">${valValue.toFixed(2)}</td>
                    <td style="color: #0078d4;">${resValue.toFixed(2)}</td>
                    <td style="color: #8b5cf6;">${aiValue.toFixed(2)}</td>
                    <td class="${deltaRVClass}">${deltaRV > 0 ? '+' : ''}${deltaRV.toFixed(2)}</td>
                    <td class="${deltaRAClass}">${deltaRA > 0 ? '+' : ''}${deltaRA.toFixed(2)}</td>
                </tr>
            `;
        }).join('');
        
        html += `
            <div class="validation-comparison-delta-metrics">
                <div class="validation-comparison-delta-title">Delta Analysis</div>
                <table class="validation-comparison-delta-table">
                    <thead>
                        <tr>
                            <th>Metric</th>
                            <th style="color: #107c10;">Valid.</th>
                            <th style="color: #0078d4;">Res.</th>
                            <th style="color: #8b5cf6;">AI Res.</th>
                            <th>Δ V-R</th>
                            <th>Δ AI-R</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${deltaRows}
                    </tbody>
                </table>
            </div>
        `;
    }
    
    html += `</div>`;
    
    container.innerHTML = html;
    
    // Render overlaid radar
    setTimeout(() => {
        const overlayRadar = document.getElementById('overlay-radar');
        
        if (overlayRadar) renderValidationRadarOverlay(overlayRadar, researchedData, validatedData, aiResearchedData);
    }, 0);
}

// Store preview widget sizes for modal
const previewWidgetSizes = {};

function initializeWidgetCustomization() {
    loadWidgetPreferences();
    
    // Apply saved preferences to main dashboard
    document.querySelectorAll('[data-widget]').forEach(widget => {
        const widgetName = widget.getAttribute('data-widget');
        if (!widgetState.visibleWidgets.has(widgetName)) {
            widget.classList.add('hidden');
        }
    });
    
    // Customize button
    const customizeBtn = document.getElementById('customize-widgets-btn');
    const modal = document.getElementById('widget-customization-modal');
    const closeBtn = document.getElementById('modal-close-btn');
    const saveBtn = document.getElementById('save-widgets-btn');
    const cancelBtn = document.getElementById('cancel-widgets-btn');
    
    if (!customizeBtn) return;
    
    customizeBtn.addEventListener('click', () => {
        // Update checkboxes based on current state
        document.querySelectorAll('.widget-checkbox-group input[type="checkbox"]').forEach(checkbox => {
            checkbox.checked = widgetState.visibleWidgets.has(checkbox.value);
        });
        // Build preview grid
        buildWidgetPreviewGrid();
        modal.classList.add('active');
    });
    
    closeBtn.addEventListener('click', () => {
        modal.classList.remove('active');
    });
    
    cancelBtn.addEventListener('click', () => {
        modal.classList.remove('active');
    });
    
    saveBtn.addEventListener('click', () => {
        // Update visible widgets based on checkboxes
        document.querySelectorAll('.widget-checkbox-group input[type="checkbox"]').forEach(checkbox => {
            toggleWidget(checkbox.value, checkbox.checked);
        });
        
        // Apply preview sizes to main dashboard
        Object.entries(previewWidgetSizes).forEach(([widgetName, sizes]) => {
            const widget = document.querySelector(`[data-widget="${widgetName}"]`);
            if (widget) {
                widget.setAttribute('data-col-span', sizes.colSpan);
                widget.setAttribute('data-row-span', sizes.rowSpan);
                widget.style.setProperty('--col-span', sizes.colSpan);
                widget.style.setProperty('--row-span', sizes.rowSpan);
                widget.style.minHeight = (300 * sizes.rowSpan + 20 * (sizes.rowSpan - 1)) + 'px';
            }
        });
        
        saveWidgetPreferences();
        modal.classList.remove('active');
    });
    
    // Close modal when clicking outside
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.classList.remove('active');
        }
    });
}

function buildWidgetPreviewGrid() {
    const previewGrid = document.getElementById('widget-preview-grid');
    previewGrid.innerHTML = '';
    previewWidgetSizes.length = 0; // Clear previous state
    
    let draggedWidget = null;
    let dragOffset = { x: 0, y: 0 };
    
    Object.entries(widgetDefinitions).forEach(([widgetId, widgetTitle]) => {
        const isVisible = widgetState.visibleWidgets.has(widgetId);
        
        // Get current sizes from main dashboard
        const mainWidget = document.querySelector(`[data-widget="${widgetId}"]`);
        const colSpan = mainWidget ? (parseInt(mainWidget.getAttribute('data-col-span')) || 1) : 1;
        const rowSpan = mainWidget ? (parseInt(mainWidget.getAttribute('data-row-span')) || 1) : 1;
        
        // Store preview sizes
        previewWidgetSizes[widgetId] = { colSpan, rowSpan };
        
        const previewWidget = document.createElement('div');
        previewWidget.className = `preview-widget ${!isVisible ? 'disabled' : ''}`;
        previewWidget.setAttribute('data-widget-id', widgetId);
        previewWidget.draggable = !isVisible ? false : true;
        previewWidget.style.setProperty('--col-span', colSpan);
        previewWidget.style.setProperty('--row-span', rowSpan);
        previewWidget.style.gridColumn = `span ${colSpan}`;
        previewWidget.style.gridRow = `span ${rowSpan}`;
        previewWidget.innerHTML = `
            <div style="text-align: center; width: 100%; cursor: grab; user-select: none;">
                <div style="font-weight: 500; margin-bottom: 4px;">⋮⋮ ${widgetTitle}</div>
                <div style="font-size: 10px; color: var(--text-secondary);">${colSpan}×${rowSpan}</div>
            </div>
            <div class="preview-resize-handle"></div>
        `;
        
        previewGrid.appendChild(previewWidget);
        
        // Add drag functionality
        previewWidget.addEventListener('dragstart', (e) => {
            draggedWidget = previewWidget;
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/html', previewWidget.innerHTML);
            previewWidget.style.opacity = '0.5';
        });
        
        previewWidget.addEventListener('dragover', (e) => {
            if (draggedWidget && draggedWidget !== previewWidget && !previewWidget.classList.contains('disabled')) {
                e.preventDefault();
                e.dataTransfer.dropEffect = 'move';
                
                // Visual feedback
                previewWidget.style.borderColor = '#0078d4';
                previewWidget.style.borderWidth = '2px';
            }
        });
        
        previewWidget.addEventListener('dragleave', (e) => {
            if (previewWidget !== draggedWidget) {
                previewWidget.style.borderColor = '';
                previewWidget.style.borderWidth = '';
            }
        });
        
        previewWidget.addEventListener('drop', (e) => {
            e.preventDefault();
            if (draggedWidget && draggedWidget !== previewWidget) {
                // Swap the widgets in the DOM
                const draggedId = draggedWidget.getAttribute('data-widget-id');
                const targetId = previewWidget.getAttribute('data-widget-id');
                
                // Store current properties
                const draggedSizes = previewWidgetSizes[draggedId];
                const targetSizes = previewWidgetSizes[targetId];
                
                // Swap positions by swapping in the grid
                previewGrid.insertBefore(draggedWidget, previewWidget);
            }
        });
        
        previewWidget.addEventListener('dragend', (e) => {
            if (draggedWidget) {
                draggedWidget.style.opacity = '1';
                draggedWidget.style.borderColor = '';
                draggedWidget.style.borderWidth = '';
            }
            draggedWidget = null;
        });
        
        // Add resize functionality to preview widget
        const resizeHandle = previewWidget.querySelector('.preview-resize-handle');
        resizeHandle.addEventListener('mousedown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const startX = e.clientX;
            const startY = e.clientY;
            const startColSpan = previewWidgetSizes[widgetId].colSpan;
            const startRowSpan = previewWidgetSizes[widgetId].rowSpan;
            
            function handleMouseMove(moveEvent) {
                const deltaX = moveEvent.clientX - startX;
                const deltaY = moveEvent.clientY - startY;
                
                // Each grid cell is approximately 100px (3 columns in ~300px area)
                let newColSpan = startColSpan + Math.round(deltaX / 110);
                let newRowSpan = startRowSpan + Math.round(deltaY / 110);
                
                // Clamp values
                newColSpan = Math.max(1, Math.min(3, newColSpan));
                newRowSpan = Math.max(1, Math.min(2, newRowSpan));
                
                previewWidget.style.gridColumn = `span ${newColSpan}`;
                previewWidget.style.gridRow = `span ${newRowSpan}`;
                
                // Update size indicator
                const sizeDiv = previewWidget.querySelector('div:last-of-type');
                if (sizeDiv) {
                    sizeDiv.innerHTML = `${newColSpan}×${newRowSpan}`;
                }
                
                // Update stored size
                previewWidgetSizes[widgetId] = { colSpan: newColSpan, rowSpan: newRowSpan };
            }
            
            function handleMouseUp() {
                document.removeEventListener('mousemove', handleMouseMove);
                document.removeEventListener('mouseup', handleMouseUp);
            }
            
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        });
    });
}

// Query Builder State
const queryBuilderState = {
    filters: [] // Array of {field, operator, value}
};

// Define available fields and their operators
const queryBuilderFields = {
    vendor: {
        label: 'Vendor Name',
        operators: ['contains', 'equals', 'does not equal'],
        type: 'text'
    },
    region: {
        label: 'Region',
        operators: ['equals', 'does not equal', 'contains'],
        type: 'select',
        values: []
    },
    specialization: {
        label: 'Specialization',
        operators: ['contains', 'equals', 'does not equal'],
        type: 'select',
        values: []
    },
    // Schema-specific type field (ir_focus_type / vendor_type / primary_trism_layer)
    // added dynamically by rebuildVendorAttributeButtons()
    is_ai_first: {
        label: 'AI-First',
        operators: ['yes', 'no'],
        type: 'boolean'
    },
    is_startup: {
        label: 'Startup',
        operators: ['yes', 'no'],
        type: 'boolean'
    },
    pillar: {
        label: 'Pillar',
        operators: ['equals', 'does not equal'],
        type: 'select',
        values: []  // populated dynamically by rebuildQueryBuilderPillarFields
    }
    // Pillar score fields (PLA, INV, etc.) and sub-pillar fields (PLA-01, etc.)
    // are now added dynamically by rebuildQueryBuilderPillarFields()
};

/**
 * Rebuild the "Vendor Attributes" buttons in the Add Filters sidebar
 * based on the current schema's fields. Also adds/removes schema-specific
 * entries in queryBuilderFields (ir_focus_type, vendor_type, primary_trism_layer).
 */
function rebuildVendorAttributeButtons() {
    // Common vendor attribute definitions (always present)
    const commonAttrs = [
        { field: 'vendor', label: 'Vendor Name' },
        { field: 'region', label: 'Region' },
        { field: 'specialization', label: 'Specialization' }
    ];
    const extraAttrs = getSchemaExtraVendorAttrs();
    const tailAttrs = [
        { field: 'is_ai_first', label: 'AI-First' },
        { field: 'is_startup', label: 'Startup' }
    ];
    const allAttrs = [...commonAttrs, ...extraAttrs, ...tailAttrs];

    // Remove old schema-specific entries from queryBuilderFields
    ['ir_focus_type', 'vendor_type', 'primary_trism_layer'].forEach(k => {
        delete queryBuilderFields[k];
    });
    // Re-add the current schema's extra fields
    extraAttrs.forEach(attr => {
        queryBuilderFields[attr.field] = {
            label: attr.label,
            operators: ['equals', 'does not equal', 'contains'],
            type: attr.type || 'select',
            values: []
        };
    });

    // Rebuild sidebar buttons
    const container = document.getElementById('vendor-attribute-buttons');
    if (container) {
        container.innerHTML = '';
        allAttrs.forEach(attr => {
            const btn = document.createElement('button');
            btn.className = 'field-selector-btn';
            btn.dataset.field = attr.field;
            btn.textContent = attr.label;
            btn.addEventListener('click', () => addQueryFilter(attr.field));
            container.appendChild(btn);
        });
    }

    // Update "Type" chart title
    const typeChartTitle = document.querySelector('[data-widget="type-chart"] h3');
    if (typeChartTitle) {
        typeChartTitle.textContent = getVendorTypeLabel() + ' Distribution';
    }
    // Also update widgetDefinitions so modal preview uses correct label
    widgetDefinitions['type-chart'] = getVendorTypeLabel() + ' Distribution';
    // Update widget toggle label in the customization modal
    const widgetToggleLabel = document.getElementById('type-chart-widget-label');
    if (widgetToggleLabel) {
        widgetToggleLabel.textContent = getVendorTypeLabel() + ' Distribution';
    }

    // Update comparison radar "type" dropdown option
    const radarTypeSelect = document.getElementById('comparison-radar-type');
    if (radarTypeSelect) {
        const typeOpt = radarTypeSelect.querySelector('option[value="ir_focus_type"], option[value="vendor_type"], option[value="primary_trism_layer"]');
        if (typeOpt) {
            typeOpt.value = getVendorTypeField();
            typeOpt.textContent = getVendorTypeLabel();
        }
    }

    // Update validation comparison category type dropdown
    const valCatType = document.getElementById('validation-comparison-category-type');
    if (valCatType) {
        const typeOpt = valCatType.querySelector('option[value="ir_focus_type"], option[value="vendor_type"], option[value="primary_trism_layer"]');
        if (typeOpt) {
            typeOpt.value = getVendorTypeField();
            typeOpt.textContent = getVendorTypeLabel();
        }
    }

    // Update Reports-tab filter label
    const filterLabel = document.querySelector('label[for="filter-ir-focus"]');
    if (filterLabel) {
        filterLabel.textContent = getVendorTypeLabel() + ':';
    }

    // Update table header info icon data-field
    const typeInfoIcon = document.querySelector('#header-row-1 .info-icon[data-field="ir_focus_type"], #header-row-1 .info-icon[data-field="vendor_type"]');
    if (typeInfoIcon) {
        typeInfoIcon.dataset.field = getVendorTypeField();
    }
    // Update table header text for "Type" column
    const typeHeaderText = typeInfoIcon?.previousElementSibling;
    if (typeHeaderText && typeHeaderText.classList.contains('header-text')) {
        typeHeaderText.textContent = getVendorTypeLabel().replace(' Type', '').replace(' Layer', '') || 'Type';
    }

    // Update column visibility modal "Type" label and checkbox data-column
    const typeColLabel = document.getElementById('type-col-visibility-label');
    if (typeColLabel) {
        const cb = typeColLabel.querySelector('.col-visibility-check');
        if (cb) cb.dataset.column = getVendorTypeField();
        // Update label text (checkbox + text node)
        const textNode = Array.from(typeColLabel.childNodes).find(n => n.nodeType === 3);
        if (textNode) textNode.textContent = ' ' + getVendorTypeLabel();
        else typeColLabel.appendChild(document.createTextNode(' ' + getVendorTypeLabel()));
    }

    // Update validation comparison axes counts
    const valAxes = document.getElementById('validation-comparison-axes');
    if (valAxes) {
        const pCount = getActivePillarCodes().length;
        const spCount = (appState.subPillars || []).length;
        Array.from(valAxes.options).forEach(opt => {
            if (opt.value === 'pillars') opt.textContent = `Pillars (${pCount})`;
            else if (opt.value === 'subpillars') opt.textContent = `Sub-pillars (${spCount})`;
            else if (opt.value === 'both') opt.textContent = `Both (${pCount + spCount})`;
        });
    }
}

/**
 * Rebuild the pillar and sub-pillar entries in queryBuilderFields
 * based on the currently active schema. Removes old pillar/sub-pillar
 * keys and inserts new ones from appState.pillarsGrouped.
 */
function rebuildQueryBuilderPillarFields() {
    // Remove existing pillar and sub-pillar keys
    Object.keys(queryBuilderFields).forEach(key => {
        if (/^[A-Z]{2,4}$/.test(key) && key !== 'PLA' || /^[A-Z]{2,4}-\d+$/.test(key)) {
            delete queryBuilderFields[key];
        }
    });
    // Also remove known DFIR pillar codes explicitly
    ['PLA', 'INV', 'REM', 'PMG', 'LAW'].forEach(k => delete queryBuilderFields[k]);
    ['PLA-01','PLA-02','PLA-03','PLA-04','INV-01','INV-02','INV-03','INV-04',
     'REM-01','REM-02','REM-03','REM-04','PMG-01','PMG-02','PMG-03','PMG-04',
     'LAW-01','LAW-02','LAW-03','LAW-04'].forEach(k => delete queryBuilderFields[k]);
    // Remove TRiSM keys as well
    ['GOV','RUN','INF'].forEach(k => delete queryBuilderFields[k]);
    ['GOV-01','GOV-02','GOV-03','GOV-04','RUN-01','RUN-02','RUN-03','RUN-04',
     'INF-01','INF-02','INF-03','INF-04'].forEach(k => delete queryBuilderFields[k]);

    const groups = appState.pillarsGrouped || [];
    const pillarValues = groups.map(g => ({ label: g.name || g.code, value: g.code }));

    // Update pillar selector values
    if (queryBuilderFields.pillar) {
        queryBuilderFields.pillar.values = pillarValues;
    }

    // Add pillar score fields
    groups.forEach(g => {
        queryBuilderFields[g.code] = {
            label: `${g.name || g.code} (Pillar Score)`,
            operators: ['=', '<', '>', '<=', '>=', '<>'],
            type: 'numeric'
        };
    });

    // Add sub-pillar score fields
    groups.forEach(g => {
        (g.sub_pillars || []).forEach(sp => {
            queryBuilderFields[sp.id] = {
                label: sp.name || sp.id,
                operators: ['=', '<', '>', '<=', '>=', '<>'],
                type: 'numeric'
            };
        });
    });

    // Rebuild sidebar pillar/sub-pillar buttons
    const btnContainer = document.getElementById('pillar-field-buttons');
    if (btnContainer) {
        btnContainer.innerHTML = '';
        groups.forEach(g => {
            const pillarBtn = document.createElement('button');
            pillarBtn.className = 'field-selector-btn pillar-btn';
            pillarBtn.dataset.field = g.code;
            pillarBtn.textContent = g.name || g.code;
            pillarBtn.addEventListener('click', () => addQueryFilter(g.code));
            btnContainer.appendChild(pillarBtn);

            (g.sub_pillars || []).forEach(sp => {
                const spBtn = document.createElement('button');
                spBtn.className = 'field-selector-btn sub-pillar-btn';
                spBtn.dataset.field = sp.id;
                spBtn.textContent = sp.name || sp.id;
                spBtn.addEventListener('click', () => addQueryFilter(sp.id));
                btnContainer.appendChild(spBtn);
            });
        });
    }
}

function initializeAnalyticsTab() {
    // Only initialize once - check if already initialized
    if (window.analyticsInitialized) {
        rebuildVendorAttributeButtons();
        rebuildQueryBuilderPillarFields();
        updateAnalytics();
        return;
    }
    
    // Initialize widget customization
    initializeWidgetCustomization();
    
    // Populate field values
    const regions = [...new Set(appState.vendors.map(v => v.region))].sort();
    const specializations = [...new Set(appState.vendors.map(v => v.specialization))].sort();
    const _tf = getVendorTypeField();
    const types = [...new Set(appState.vendors.map(v => v[_tf]))].filter(Boolean).sort();
    
    queryBuilderFields.region.values = regions;
    queryBuilderFields.specialization.values = specializations;
    // Populate the schema-specific type field values
    if (queryBuilderFields[_tf]) {
        queryBuilderFields[_tf].values = types;
    }
    
    // Build vendor attribute buttons and pillar/sub-pillar fields dynamically
    rebuildVendorAttributeButtons();
    rebuildQueryBuilderPillarFields();
    
    // Setup field selector buttons (only once)
    document.querySelectorAll('.field-selector-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const field = btn.dataset.field;
            addQueryFilter(field);
        });
    });
    
    // Reset button
    document.getElementById('add-filter-btn')?.addEventListener('click', () => {
        // This button is hidden for now, filters are added via field selector
    });
    
    // Mark as initialized
    window.analyticsInitialized = true;
    
    // Initial render
    renderQueryFilters();
    initializeComparisonRadarWidget();
    initializeValidationComparisonWidget();
    populateComparisonRadarDropdowns();
    renderValidationComparison();
    updateAnalytics();
}

function addQueryFilter(field) {
    // Add a new filter row with default operator
    const fieldConfig = queryBuilderFields[field];
    if (!fieldConfig) return;
    
    const operators = fieldConfig.operators;
    queryBuilderState.filters.push({
        logicalOperator: queryBuilderState.filters.length > 0 ? 'AND' : null,
        field: field,
        operator: operators[0],
        value: ''
    });
    
    renderQueryFilters();
}

function removeQueryFilter(index) {
    queryBuilderState.filters.splice(index, 1);
    renderQueryFilters();
    updateAnalytics();
}

function updateQueryFilter(index, property, value) {
    if (queryBuilderState.filters[index]) {
        queryBuilderState.filters[index][property] = value;
        updateAnalytics();
    }
}

function renderQueryFilters() {
    const container = document.getElementById('query-filters');
    container.innerHTML = '';
    
    if (queryBuilderState.filters.length === 0) {
        container.innerHTML = '<div class="no-filters-message">No filters applied. Select a field from the left to add filters.</div>';
        return;
    }
    
    queryBuilderState.filters.forEach((filter, index) => {
        const fieldConfig = queryBuilderFields[filter.field];
        if (!fieldConfig) return;
        
        const row = document.createElement('div');
        row.className = 'query-filter-row';
        
        // Logical operator (AND/OR) - only for filters after the first
        if (filter.logicalOperator) {
            const logicalOpSelect = document.createElement('select');
            logicalOpSelect.className = 'filter-logical-op';
            ['AND', 'OR'].forEach(op => {
                const option = document.createElement('option');
                option.value = op;
                option.textContent = op;
                if (op === filter.logicalOperator) option.selected = true;
                logicalOpSelect.appendChild(option);
            });
            logicalOpSelect.addEventListener('change', (e) => {
                updateQueryFilter(index, 'logicalOperator', e.target.value);
            });
            row.appendChild(logicalOpSelect);
        }
        
        // Field select
        const fieldSelect = document.createElement('select');
        fieldSelect.className = 'filter-field';
        Object.entries(queryBuilderFields).forEach(([key, config]) => {
            const option = document.createElement('option');
            option.value = key;
            option.textContent = config.label;
            if (key === filter.field) option.selected = true;
            fieldSelect.appendChild(option);
        });
        fieldSelect.addEventListener('change', (e) => {
            updateQueryFilter(index, 'field', e.target.value);
            renderQueryFilters();
        });
        
        // Operator select
        const operatorSelect = document.createElement('select');
        operatorSelect.className = 'filter-operator';
        fieldConfig.operators.forEach(op => {
            const option = document.createElement('option');
            option.value = op;
            option.textContent = op.charAt(0).toUpperCase() + op.slice(1);
            if (op === filter.operator) option.selected = true;
            operatorSelect.appendChild(option);
        });
        operatorSelect.addEventListener('change', (e) => {
            updateQueryFilter(index, 'operator', e.target.value);
        });
        
        // Value input/select
        let valueInput;
        if (fieldConfig.type === 'boolean') {
            valueInput = document.createElement('select');
            valueInput.className = 'filter-value';
            ['Yes', 'No'].forEach((val, i) => {
                const option = document.createElement('option');
                option.value = i === 0;
                option.textContent = val;
                if (String(filter.value) === String(i === 0)) option.selected = true;
                valueInput.appendChild(option);
            });
        } else if (fieldConfig.type === 'numeric') {
            valueInput = document.createElement('input');
            valueInput.className = 'filter-value';
            valueInput.type = 'number';
            valueInput.placeholder = 'Enter value (1-5)...';
            valueInput.min = '1';
            valueInput.max = '5';
            valueInput.value = filter.value;
        } else if (fieldConfig.type === 'select' && fieldConfig.values.length > 0) {
            valueInput = document.createElement('select');
            valueInput.className = 'filter-value';
            fieldConfig.values.forEach(val => {
                const option = document.createElement('option');
                // Handle both simple string values and object values (for pillar with label/value)
                if (typeof val === 'object') {
                    option.value = val.value;
                    option.textContent = val.label;
                    if (val.value === filter.value) option.selected = true;
                } else {
                    option.value = val;
                    option.textContent = val;
                    if (val === filter.value) option.selected = true;
                }
                valueInput.appendChild(option);
            });
        } else {
            valueInput = document.createElement('input');
            valueInput.className = 'filter-value';
            valueInput.type = 'text';
            valueInput.placeholder = 'Enter value...';
            valueInput.value = filter.value;
        }
        valueInput.addEventListener('change', (e) => {
            updateQueryFilter(index, 'value', e.target.value);
        });
        
        // Remove button
        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-filter-btn';
        removeBtn.textContent = '✕';
        removeBtn.addEventListener('click', () => removeQueryFilter(index));
        
        row.appendChild(fieldSelect);
        row.appendChild(operatorSelect);
        row.appendChild(valueInput);
        row.appendChild(removeBtn);
        
        container.appendChild(row);
    });
}

function updateAnalytics() {
    // Filter vendors based on query builder filters with logical operators (AND/OR)
    let filtered = appState.vendors;
    
    if (queryBuilderState.filters.length > 0) {
        filtered = filtered.filter(vendor => {
            let result = true;
            
            for (let i = 0; i < queryBuilderState.filters.length; i++) {
                const filter = queryBuilderState.filters[i];
                
                // Get vendor value - handle special cases for pillar scores, pillar, and nested granular_mapping for capabilities
                let vendorValue;
                
                if (isActivePillarCode(filter.field)) {
                    // Pillar score fields: prefer validated/computed pillar scores
                    vendorValue = getEffectivePillarScores(vendor)?.[filter.field];
                } else if (filter.field === 'pillar') {
                    // Check if vendor has the pillar score
                    vendorValue = getEffectivePillarScores(vendor)?.[filter.value] ? filter.value : null;
                } else if (isActiveSubPillarCode(filter.field)) {
                    // Extract pillar code (first 3 chars, e.g., "PLA" from "PLA-01")
                    const pillarCode = filter.field.substring(0, 3);
                    vendorValue = getEffectiveGranularMapping(vendor)?.[pillarCode]?.[filter.field];
                } else {
                    vendorValue = vendor[filter.field];
                }
                
                const filterValue = filter.value;
                let filterMatches = false;
                
                switch (filter.operator) {
                    case 'equals':
                        filterMatches = String(vendorValue) === String(filterValue);
                        break;
                    case 'does not equal':
                        filterMatches = String(vendorValue) !== String(filterValue);
                        break;
                    case 'contains':
                        filterMatches = String(vendorValue).toLowerCase().includes(String(filterValue).toLowerCase());
                        break;
                    case 'does not contain':
                        filterMatches = !String(vendorValue).toLowerCase().includes(String(filterValue).toLowerCase());
                        break;
                    case '=':
                        filterMatches = Number(vendorValue) === Number(filterValue);
                        break;
                    case '<':
                        filterMatches = Number(vendorValue) < Number(filterValue);
                        break;
                    case '>':
                        filterMatches = Number(vendorValue) > Number(filterValue);
                        break;
                    case '<=':
                        filterMatches = Number(vendorValue) <= Number(filterValue);
                        break;
                    case '>=':
                        filterMatches = Number(vendorValue) >= Number(filterValue);
                        break;
                    case '<>':
                        filterMatches = Number(vendorValue) !== Number(filterValue);
                        break;
                    default:
                        filterMatches = true;
                }
                
                // Apply logical operator
                if (i === 0) {
                    result = filterMatches;
                } else {
                    const logicalOp = filter.logicalOperator;
                    if (logicalOp === 'AND') {
                        result = result && filterMatches;
                    } else if (logicalOp === 'OR') {
                        result = result || filterMatches;
                    }
                }
            }
            
            return result;
        });
    }
    
    const filteredVendors = filtered;
    
    // Update statistics
    const totalCount = filteredVendors.length;
    const aiFirstCount = filteredVendors.filter(v => v.is_ai_first).length;
    const startupCount = filteredVendors.filter(v => v.is_startup).length;
    
    // Calculate average scores (score-mode-aware)
    let totalScore = 0;
    let scoreCount = 0;
    filteredVendors.forEach(v => {
        const scores = getEffectivePillarScores(v) || {};
        Object.values(scores).forEach(score => {
            if (score) {
                totalScore += score;
                scoreCount++;
            }
        });
    });
    const avgScore = scoreCount > 0 ? (totalScore / scoreCount).toFixed(2) : 0;
    
    // Update stat displays
    document.getElementById('analysis-stat-count').textContent = totalCount;
    document.getElementById('analysis-stat-avg-score').textContent = avgScore;
    document.getElementById('analysis-stat-ai-pct').textContent = 
        totalCount > 0 ? ((aiFirstCount / totalCount) * 100).toFixed(0) + '%' : '0%';
    document.getElementById('analysis-stat-startup-pct').textContent = 
        totalCount > 0 ? ((startupCount / totalCount) * 100).toFixed(0) + '%' : '0%';
    
    // Update charts
    renderAnalyticsRegionChart(filteredVendors);
    renderAnalyticsPillarChart(filteredVendors);
    renderAnalyticsPillarRadarChart(filteredVendors);
    renderAnalyticsSpecializationChart(filteredVendors);
    renderAnalyticsTypeChart(filteredVendors);
    renderAnalyticsAIChart(filteredVendors);
    renderAnalyticsStartupChart(filteredVendors);
    renderValidationComparison(filteredVendors);
}

function renderAnalyticsRegionChart(vendors) {
    const regionDist = {};
    vendors.forEach(v => {
        regionDist[v.region] = (regionDist[v.region] || 0) + 1;
    });
    
    const sorted = Object.entries(regionDist).sort((a, b) => b[1] - a[1]);
    const maxValue = Math.max(...sorted.map(d => d[1]));
    const chart = document.getElementById('analysis-region-chart');
    
    chart.innerHTML = sorted.map(([region, count]) => {
        const percentage = (count / maxValue) * 100;
        return `
            <div style="margin-bottom: 12px;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                    <span style="font-size: 12px;">${region}</span>
                    <span style="font-size: 12px; font-weight: bold;">${count}</span>
                </div>
                <div style="height: 24px; background: var(--bg-tertiary); border-radius: 4px; overflow: hidden;">
                    <div style="height: 100%; width: ${percentage}%; background: linear-gradient(90deg, #0078d4, #107c10);"></div>
                </div>
            </div>
        `;
    }).join('');
}

function renderAnalyticsPillarChart(vendors) {
    const activePillars = getActivePillarCodes();
    const pillarAvgs = {};
    const pillarCounts = {};
    activePillars.forEach(p => { pillarAvgs[p] = 0; pillarCounts[p] = 0; });
    
    // Initialize sub-pillar tracking
    const subPillarAvgs = {};
    const subPillarCounts = {};
    const groups = appState.pillarsGrouped || [];
    if (Array.isArray(groups) && groups.length) {
        groups.forEach(g => {
            (g.sub_pillars || []).forEach(sp => {
                subPillarAvgs[sp.id] = 0;
                subPillarCounts[sp.id] = 0;
            });
        });
    } else {
        activePillars.forEach(pillar => {
            for (let i = 1; i <= 4; i++) {
                const code = `${pillar}-0${i}`;
                subPillarAvgs[code] = 0;
                subPillarCounts[code] = 0;
            }
        });
    }
    
    vendors.forEach(v => {
        const granularMapping = getEffectiveGranularMapping(v);
        
        // Calculate pillar averages
        Object.keys(pillarAvgs).forEach(p => {
            const score = computePillarScoreFromGranular(v, p);
            if (score !== null && score !== undefined && score !== '') {
                pillarAvgs[p] += Number(score);
                pillarCounts[p]++;
            }
        });
        
        // Calculate sub-pillar averages from granular_mapping
        Object.keys(granularMapping).forEach(pillar => {
            const pillarData = granularMapping[pillar];
            if (pillarData && typeof pillarData === 'object') {
                // Iterate over all sub-pillar keys present in pillarData
                Object.entries(pillarData).forEach(([code, value]) => {
                    if (code in subPillarAvgs && value !== undefined && value !== null && value !== '' && !Number.isNaN(Number(value))) {
                        subPillarAvgs[code] += Number(value) || 0;
                        subPillarCounts[code]++;
                    }
                });
            }
        });
    });
    
    Object.keys(pillarAvgs).forEach(p => {
        pillarAvgs[p] = pillarCounts[p] > 0 ? (pillarAvgs[p] / pillarCounts[p]).toFixed(2) : 0;
    });
    
    Object.keys(subPillarAvgs).forEach(code => {
        subPillarAvgs[code] = subPillarCounts[code] > 0 ? (subPillarAvgs[code] / subPillarCounts[code]).toFixed(2) : 0;
    });
    
    const chart = document.getElementById('analysis-pillar-chart');
    const pillars = Object.entries(pillarAvgs).sort((a, b) => b[1] - a[1]);
    
    // Derive pillar names and sub-pillar mapping dynamically from metadata
    const pillarNames = {};
    const subPillarMapping = {};
    const pGroups = appState.pillarsGrouped || [];
    if (Array.isArray(pGroups) && pGroups.length) {
        pGroups.forEach(g => {
            pillarNames[g.code] = g.name || g.code;
            subPillarMapping[g.code] = (g.sub_pillars || []).map(sp => sp.id);
        });
    } else {
        activePillars.forEach(p => {
            pillarNames[p] = appState.fieldMetadata?.[p]?.name || p;
            subPillarMapping[p] = [];
            for (let i = 1; i <= 4; i++) subPillarMapping[p].push(`${p}-0${i}`);
        });
    }
    
    const numPillars = pillars.length;
    chart.innerHTML = `
        <div style="display: grid; grid-template-columns: repeat(${numPillars}, 1fr); gap: 16px;">
            ${pillars.map(([pillar, avg]) => `
                <div>
                    <!-- Pillar -->
                    <div style="text-align: center; margin-bottom: 8px; cursor: help; padding: 8px; border-radius: 4px; transition: background-color 0.2s;" title="${pillarNames[pillar]}">
                        <div style="font-size: 20px; font-weight: bold; color: var(--color-primary);">${avg}</div>
                        <div style="font-size: 12px; color: var(--text-secondary); font-weight: 600; margin-top: 4px;">${pillar}</div>
                    </div>
                    
                    <!-- Sub-pillars -->
                    <div style="font-size: 10px; border-top: 1px solid var(--border-color); padding-top: 8px;">
                        ${(subPillarMapping[pillar] || []).map(subPillarCode => {
                            const subPillarLabel = queryBuilderFields[subPillarCode]?.label || subPillarCode;
                            const subPillarAvg = subPillarAvgs[subPillarCode] || 0;
                            return `
                                <div style="display: flex; justify-content: space-between; align-items: center; padding: 4px 0; cursor: help;" title="${subPillarLabel}">
                                    <span style="color: var(--text-secondary);">${subPillarCode}</span>
                                    <span style="color: var(--text-primary); font-weight: 500;">${subPillarAvg}</span>
                                </div>
                            `;
                        }).join('')}
                    </div>
                </div>
            `).join('')}
        </div>
    `;
}

function renderAnalyticsPillarRadarChart(vendors) {
    const chart = document.getElementById('analysis-pillar-radar-chart');
    if (!chart) return;
    
    // Pillar list at function scope so all sections can reference it
    const pillarList = getActivePillarCodes();
    
    // Determine which score layers have data for this schema
    const allPossibleLayers = [
        { key: 'validated',        label: 'Validated',        color: '#107c10', fillColor: 'rgba(16, 124, 16, 0.15)',  pKey: 'pillar_scores_validated',        spKey: 'sub_pillar_scores_validated' },
        { key: 'researched',       label: 'Researched',       color: '#0078d4', fillColor: 'rgba(0, 120, 212, 0.15)', pKey: 'pillar_scores_researched',       spKey: 'sub_pillar_scores_researched' },
        { key: 'v2_researched',    label: 'V2 Researched',    color: '#0078d4', fillColor: 'rgba(0, 120, 212, 0.15)', pKey: 'pillar_scores_v2_researched',    spKey: 'sub_pillar_scores_v2_researched' },
        { key: 'ai_researched',    label: 'AI Researched',    color: '#8b5cf6', fillColor: 'rgba(139, 92, 246, 0.15)', pKey: 'pillar_scores_ai_researched',    spKey: 'sub_pillar_scores_ai_researched' },
        { key: 'evidence_refined', label: 'Evidence Refined', color: '#e3008c', fillColor: 'rgba(227, 0, 140, 0.15)', pKey: 'pillar_scores_evidence_refined', spKey: 'sub_pillar_scores_evidence_refined' },
        { key: 'v3_current',       label: 'V3 Current',       color: '#0078d4', fillColor: 'rgba(0, 120, 212, 0.15)', pKey: null,                            spKey: 'sub_pillar_scores_v3' },
        { key: 'current',          label: 'Current',          color: '#ff8c00', fillColor: 'rgba(255, 140, 0, 0.15)',  pKey: null,                            spKey: 'sub_pillar_scores_current' },
    ];
    
    // Only keep layers that have data in at least one vendor
    const scoreLayers = allPossibleLayers.filter(layer => {
        if (layer.key === 'validated') return true; // always show validated
        return (vendors || []).some(v => {
            if (layer.pKey && v[layer.pKey] && typeof v[layer.pKey] === 'object' && Object.keys(v[layer.pKey]).length > 0) return true;
            if (layer.spKey && v[layer.spKey] && typeof v[layer.spKey] === 'object' && Object.keys(v[layer.spKey]).length > 0) return true;
            return false;
        });
    });
    
    // Check for existing toggle state or create it
    if (!window.radarChartState) {
        const defaultLayers = {};
        scoreLayers.forEach(l => { defaultLayers[l.key] = true; });
        window.radarChartState = {
            showSubPillars: true,
            showPillars: true,
            layers: defaultLayers
        };
    }
    // Ensure layers exist for all available layers
    if (!window.radarChartState.layers) {
        window.radarChartState.layers = {};
    }
    scoreLayers.forEach(l => {
        if (window.radarChartState.layers[l.key] === undefined) {
            window.radarChartState.layers[l.key] = true;
        }
    });
    
    // Compute averages per score layer
    const layerData = {};
    scoreLayers.forEach(layer => {
        layerData[layer.key] = computeAveragesForScoreMode(vendors, layer.key);
    });
    
    // Sub-pillar labels lookup
    const subPillarLabels = {};
    const radarGroups = appState.pillarsGrouped || [];
    if (Array.isArray(radarGroups) && radarGroups.length) {
        radarGroups.forEach(g => {
            (g.sub_pillars || []).forEach(sp => {
                subPillarLabels[sp.id] = sp.name || queryBuilderFields[sp.id]?.label || sp.id;
            });
        });
    } else {
        getActivePillarCodes().forEach(pillar => {
            for (let i = 1; i <= 4; i++) {
                const code = `${pillar}-0${i}`;
                subPillarLabels[code] = queryBuilderFields[code]?.label || code;
            }
        });
    }
    
    // Create SVG radar chart with sub-pillars
    // Guard against initial renders before layout settles: empty/hidden containers can report 0 height,
    // which previously produced negative circle radii like -3/-6/-9/-12/-15.
    const { width: measuredWidth, height: measuredHeight } = _getSafeContainerDimensions(chart, {
        minWidth: 320,
        minHeight: 320,
        fallbackWidth: 480,
        fallbackHeight: 420
    });
    const size = Math.max(260, Math.min(measuredWidth - 40, measuredHeight - 40));
    const center = size / 2;
    const radius = _getSafeRadarGeometry({ width: size, height: size, padding: size * 0.125 }).radius;
    const levels = 5;
    const maxValue = 5;
    const chartCenter = center + 20;
    
    // All sub-pillars in order
    const subPillars = (appState.subPillars || []).map(s => s.id);
    if (!subPillars.length) {
        pillarList.forEach(pillar => {
            for (let i = 1; i <= 4; i++) {
                subPillars.push(`${pillar}-0${i}`);
            }
        });
    }
    
    // Compute how many sub-pillars per pillar (may vary by schema)
    const pillarSubcount = pillarList.length > 0 ? Math.ceil(subPillars.length / pillarList.length) : 4;
    
    const radar = _getRadarAxisLayout({ axes: subPillars, cx: chartCenter, cy: chartCenter, denseFont: 9, mediumFont: 9, sparseFont: 9 });
    const angles = radar.entries.map(entry => entry.angle);
    
    // Create container for controls and chart
    let html = `
        <div style="padding: 12px 0;">
            <div style="display: flex; gap: 12px; margin-bottom: 8px; justify-content: center; flex-wrap: wrap;">
                <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 12px; color: var(--text-primary);">
                    <input type="checkbox" id="radar-show-subpillars" ${window.radarChartState.showSubPillars ? 'checked' : ''} style="cursor: pointer;">
                    <span>Sub-Pillars</span>
                </label>
                <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 12px; color: var(--text-primary);">
                    <input type="checkbox" id="radar-show-pillars" ${window.radarChartState.showPillars ? 'checked' : ''} style="cursor: pointer;">
                    <span>Pillars</span>
                </label>
            </div>
            <div style="display: flex; gap: 12px; margin-bottom: 12px; justify-content: center; flex-wrap: wrap; border-top: 1px solid var(--border-color); padding-top: 8px;">
                <span style="font-size: 11px; color: var(--text-secondary); font-weight: 600;">Score Layers:</span>
                ${scoreLayers.map(layer => `
                    <label style="display: flex; align-items: center; gap: 5px; cursor: pointer; font-size: 12px;">
                        <input type="checkbox" id="radar-layer-${layer.key}" ${window.radarChartState.layers[layer.key] ? 'checked' : ''} style="cursor: pointer; accent-color: ${layer.color};">
                        <span style="color: ${layer.color}; font-weight: 500;">${layer.label}</span>
                    </label>
                `).join('')}
            </div>
        </div>
    `;
    
    let svg = `<svg width="${size + 40}" height="${size + 40}" style="margin: auto; display: block;">`;
    svg += `<defs><style>
        .sub-pillar-label { font-size: 9px; }
        .pillar-label { font-size: 11px; font-weight: 600; }
        .level-label { font-size: 9px; fill: var(--text-secondary); }
    </style></defs>`;
    
    // Draw center point (0)
    svg += `<circle cx="${chartCenter}" cy="${chartCenter}" r="2" fill="var(--text-secondary)" opacity="0.5"/>`;
    svg += `<text x="${chartCenter - 8}" y="${chartCenter - 5}" class="level-label" font-size="8">0</text>`;
    
    // Draw level circles and labels
    for (let i = 1; i <= levels; i++) {
        const r = (radius * i) / levels;
        svg += `<circle cx="${chartCenter}" cy="${chartCenter}" r="${r}" stroke="var(--border-color)" stroke-width="1" fill="none" opacity="0.3"/>`;
        
        // Add level labels (1 at innermost, 5 at outermost)
        const levelValue = i;
        svg += `<text x="${chartCenter + r + 3}" y="${chartCenter - 3}" class="level-label">${levelValue}</text>`;
    }
    
    // Draw grid lines
    angles.forEach((angle) => {
        const x1 = chartCenter;
        const y1 = chartCenter;
        const x2 = chartCenter + radius * Math.cos(angle);
        const y2 = chartCenter + radius * Math.sin(angle);
        
        svg += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="var(--border-color)" stroke-width="0.5" opacity="0.3"/>`;
    });
    
    // Draw polygons for each enabled score layer
    const enabledLayers = scoreLayers.filter(l => window.radarChartState.layers[l.key]);
    // Dash patterns by layer index: solid, dashed, dotted, dash-dot, ...
    const dashPatterns = ['none', '4,2', '6,3', '8,3,2,3', '2,2'];
    
    enabledLayers.forEach((layer, layerIdx) => {
        const data = layerData[layer.key];
        const dash = dashPatterns[layerIdx % dashPatterns.length];
        
        // Draw sub-pillar polygon - conditional
        if (window.radarChartState.showSubPillars) {
            let subPillarPathData = '';
            angles.forEach((angle, i) => {
                const value = parseFloat(data.subPillars[subPillars[i]] || 0);
                const scaledRadius = (value / maxValue) * radius;
                const x = chartCenter + scaledRadius * Math.cos(angle);
                const y = chartCenter + scaledRadius * Math.sin(angle);
                subPillarPathData += (i === 0 ? 'M' : 'L') + x + ',' + y;
            });
            subPillarPathData += 'Z';
            
            svg += `<path d="${subPillarPathData}" stroke="${layer.color}" stroke-width="2" fill="${layer.fillColor}" stroke-dasharray="${dash}"/>`;
        }
        
        // Draw pillar overlay polygon - conditional
        if (window.radarChartState.showPillars && !window.radarChartState.showSubPillars) {
            let pillarPathData = '';
            angles.forEach((angle, i) => {
                const pillarIndex = Math.floor(i / pillarSubcount);
                const pillar = pillarList[pillarIndex];
                const value = parseFloat(data.pillars[pillar] || 0);
                const scaledRadius = (value / maxValue) * radius;
                const x = chartCenter + scaledRadius * Math.cos(angle);
                const y = chartCenter + scaledRadius * Math.sin(angle);
                pillarPathData += (i === 0 ? 'M' : 'L') + x + ',' + y;
            });
            pillarPathData += 'Z';
            
            svg += `<path d="${pillarPathData}" stroke="${layer.color}" stroke-width="2" fill="${layer.fillColor}" stroke-dasharray="${dash}"/>`;
        }
    });
    
    // Add pillar labels (at the midpoint of each pillar's sub-pillars)
    pillarList.forEach((pillar, pillarIdx) => {
        const startIdx = pillarIdx * pillarSubcount;
        const midIdx = startIdx + Math.floor(pillarSubcount / 2);
        const midAngle = angles[midIdx];
        const labelRadius = radius + 50;
        const labelX = chartCenter + labelRadius * Math.cos(midAngle);
        const labelY = chartCenter + labelRadius * Math.sin(midAngle);
        
        svg += `<text x="${labelX}" y="${labelY}" text-anchor="middle" dominant-baseline="middle" class="pillar-label" fill="var(--color-primary)" cursor="help" title="${pillar}">${pillar}</text>`;
    });
    
    // Add sub-pillar labels around the radar
    angles.forEach((angle, i) => {
        const labelRadius = radius + 30;
        const labelX = chartCenter + labelRadius * Math.cos(angle);
        const labelY = chartCenter + labelRadius * Math.sin(angle);
        const subPillarCode = subPillars[i];
        
        svg += `<text x="${labelX}" y="${labelY}" text-anchor="middle" dominant-baseline="middle" class="sub-pillar-label" fill="var(--text-secondary)" cursor="help" title="${subPillarLabels[subPillarCode]}">${subPillarCode}</text>`;
    });
    
    // Add dots for each enabled layer
    enabledLayers.forEach(layer => {
        const data = layerData[layer.key];
        
        // Add sub-pillar value dots - conditional
        if (window.radarChartState.showSubPillars) {
            angles.forEach((angle, i) => {
                const value = parseFloat(data.subPillars[subPillars[i]] || 0);
                const scaledRadius = (value / maxValue) * radius;
                const x = chartCenter + scaledRadius * Math.cos(angle);
                const y = chartCenter + scaledRadius * Math.sin(angle);
                
                svg += `<circle cx="${x}" cy="${y}" r="3" fill="${layer.color}" stroke="white" stroke-width="1.5"/>`;
            });
        }
        
        // Add pillar value dots - conditional
        if (window.radarChartState.showPillars && !window.radarChartState.showSubPillars) {
            pillarList.forEach((pillar, pillarIdx) => {
                const startIdx = pillarIdx * pillarSubcount;
                const midIdx = startIdx + Math.floor(pillarSubcount / 2);
                const midAngle = angles[midIdx];
                const value = parseFloat(data.pillars[pillar] || 0);
                const scaledRadius = (value / maxValue) * radius;
                const x = chartCenter + scaledRadius * Math.cos(midAngle);
                const y = chartCenter + scaledRadius * Math.sin(midAngle);
                
                svg += `<circle cx="${x}" cy="${y}" r="3.5" fill="${layer.color}" stroke="white" stroke-width="1.5"/>`;
            });
        }
    });
    
    svg += `</svg>`;
    
    html += svg;
    
    chart.innerHTML = html;
    
    // Add toggle event listeners
    setTimeout(() => {
        const subPillarsCheckbox = document.getElementById('radar-show-subpillars');
        const pillarsCheckbox = document.getElementById('radar-show-pillars');
        
        if (subPillarsCheckbox) {
            subPillarsCheckbox.addEventListener('change', (e) => {
                window.radarChartState.showSubPillars = e.target.checked;
                renderAnalyticsPillarRadarChart(vendors);
            });
        }
        
        if (pillarsCheckbox) {
            pillarsCheckbox.addEventListener('change', (e) => {
                window.radarChartState.showPillars = e.target.checked;
                renderAnalyticsPillarRadarChart(vendors);
            });
        }
        
        // Score layer checkboxes
        scoreLayers.forEach(layer => {
            const cb = document.getElementById(`radar-layer-${layer.key}`);
            if (cb) {
                cb.addEventListener('change', (e) => {
                    window.radarChartState.layers[layer.key] = e.target.checked;
                    renderAnalyticsPillarRadarChart(vendors);
                });
            }
        });
    }, 100);
}

function renderAnalyticsSpecializationChart(vendors) {
    const specDist = {};
    vendors.forEach(v => {
        specDist[v.specialization] = (specDist[v.specialization] || 0) + 1;
    });
    
    const sorted = Object.entries(specDist).sort((a, b) => b[1] - a[1]).slice(0, 8);
    const chart = document.getElementById('analysis-specialization-chart');
    
    chart.innerHTML = sorted.map(([spec, count]) => `
        <div style="margin-bottom: 12px; font-size: 12px;">
            <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                <span>${spec}</span>
                <span style="font-weight: bold;">${count}</span>
            </div>
        </div>
    `).join('');
}

function renderAnalyticsTypeChart(vendors) {
    const _tf = getVendorTypeField();
    const typeDist = {};
    vendors.forEach(v => {
        typeDist[v[_tf] || 'Unknown'] = (typeDist[v[_tf] || 'Unknown'] || 0) + 1;
    });
    
    const chart = document.getElementById('analysis-type-chart');
    const total = vendors.length;
    
    chart.innerHTML = Object.entries(typeDist).map(([type, count]) => {
        const percentage = (count / total) * 100;
        return `
            <div style="margin-bottom: 16px;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                    <span style="font-size: 12px;">${type}</span>
                    <span style="font-size: 12px; font-weight: bold;">${count} (${percentage.toFixed(0)}%)</span>
                </div>
                <div style="height: 24px; background: var(--bg-tertiary); border-radius: 4px; overflow: hidden;">
                    <div style="height: 100%; width: ${percentage}%; background: linear-gradient(90deg, #ffb900, #107c10);"></div>
                </div>
            </div>
        `;
    }).join('');
}

function renderAnalyticsAIChart(vendors) {
    const aiCount = vendors.filter(v => v.is_ai_first).length;
    const nonAiCount = vendors.length - aiCount;
    const chart = document.getElementById('analysis-ai-chart');
    
    const aiPct = vendors.length > 0 ? (aiCount / vendors.length) * 100 : 0;
    
    chart.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div style="text-align: center;">
                <div style="font-size: 28px; font-weight: bold; color: #0078d4;">${aiCount}</div>
                <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">AI-First</div>
                <div style="font-size: 14px; color: var(--text-primary); margin-top: 8px; font-weight: 600;">${aiPct.toFixed(0)}%</div>
            </div>
            <div style="text-align: center;">
                <div style="font-size: 28px; font-weight: bold; color: #605e5c;">${nonAiCount}</div>
                <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">Traditional</div>
                <div style="font-size: 14px; color: var(--text-primary); margin-top: 8px; font-weight: 600;">${(100 - aiPct).toFixed(0)}%</div>
            </div>
        </div>
    `;
}

function renderAnalyticsStartupChart(vendors) {
    const startupCount = vendors.filter(v => v.is_startup).length;
    const establishedCount = vendors.length - startupCount;
    const chart = document.getElementById('analysis-startup-chart');
    
    const startupPct = vendors.length > 0 ? (startupCount / vendors.length) * 100 : 0;
    
    chart.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div style="text-align: center;">
                <div style="font-size: 28px; font-weight: bold; color: #107c10;">${startupCount}</div>
                <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">Startups</div>
                <div style="font-size: 14px; color: var(--text-primary); margin-top: 8px; font-weight: 600;">${startupPct.toFixed(0)}%</div>
            </div>
            <div style="text-align: center;">
                <div style="font-size: 28px; font-weight: bold; color: #605e5c;">${establishedCount}</div>
                <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">Established</div>
                <div style="font-size: 14px; color: var(--text-primary); margin-top: 8px; font-weight: 600;">${(100 - startupPct).toFixed(0)}%</div>
            </div>
        </div>
    `;
}

function resetAnalyticsFilters() {
    document.getElementById('analysis-region-filter').value = '';
    document.getElementById('analysis-specialization-filter').value = '';
    document.getElementById('analysis-type-filter').value = '';
    document.getElementById('analysis-ai-first-filter').checked = false;
    document.getElementById('analysis-startup-filter').checked = false;
    updateAnalytics();
}

// ═══════════════════════════════════════════════════════════════════════════
// 90-Day Adoption Roadmap — Interactive Gantt Chart
// ═══════════════════════════════════════════════════════════════════════════

const GANTT_PHASE_COLORS = ['#0078d4', '#107c10', '#d83b01', '#5c2d91'];
const GANTT_RMF_COLORS = { Govern: '#0078d4', Map: '#107c10', Measure: '#d83b01', Manage: '#5c2d91' };
const GANTT_PILLAR_COLORS = { INF: '#0078d4', IAM: '#107c10', NDS: '#d83b01', DSO: '#5c2d91', TRM: '#008080' };
let _ganttPlanData = null;
let _ganttDragState = null;

// ── Agentic Security Operations Adoption Framework (ASAF) View ──────────────

// ── ASMF Target Radar ────────────────────────────────────────────────────────

async function populateASMFRadar() {
    const el = document.getElementById('asmf-radar-content');
    if (!el) return;
    if (!_asmfFramework) {
        try { const r = await fetch('/api/asmf-framework'); _asmfFramework = await r.json(); }
        catch(e) { el.innerHTML = `<p style="color:#ef4444">${escapeHtml(String(e))}</p>`; return; }
    }
    const fw = _asmfFramework;
    const dims = Object.entries(fw.dimensions || {});
    const labels = dims.map(([id, d]) => `${id}\n${d.name}`);
    const weights = dims.map(([,d]) => Math.round((d.weight||0)*100));

    // Stage 5 = max (100% normalised), stage 0 = min typical
    // We represent capability coverage per dimension per stage as 0-100
    const stage5  = dims.map(() => 100);
    const stage3  = dims.map(([,d]) => 62);
    const stage1  = dims.map(([,d]) => 22);

    const hostW = Math.max(320, Math.floor(el.clientWidth || 760));
    const canvasMaxW = hostW < 920 ? Math.max(320, Math.min(620, hostW - 36)) : 560;
    const canvasMaxH = Math.round(canvasMaxW * 1.07);

    el.innerHTML = `
    <div style="margin-bottom:20px;font-size:13px;color:var(--text-secondary);line-height:1.6;max-width:100%;">
      Each axis represents one of the 11 ASMF dimensions. The outer ring (Stage 5 — Fully Agentic) shows the target state.
      The middle band is Stage 3 (Directed Autonomy) — a realistic 3-year goal for most enterprises.
      The inner band is Stage 1 (Assisted) — typical today.
    </div>
        <div class="asmf-radar-layout" style="display:flex;gap:32px;flex-wrap:wrap;align-items:flex-start;width:100%;">
                        <canvas id="asmf-radar-chart" width="${canvasMaxW}" height="${canvasMaxH}" style="width:min(100%,${canvasMaxW}px);max-width:100%;height:${canvasMaxH}px;flex:1 1 360px;"></canvas>
      <div style="flex:1;min-width:220px;">
        <div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:12px;">Dimension Weights</div>
        ${dims.map(([id, d]) => {
            const w = Math.round((d.weight||0)*100);
            const col = _asmfDimColor(d.plane||'');
            return `<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
              <span style="width:8px;height:8px;border-radius:50%;background:${col};flex-shrink:0;display:inline-block;"></span>
              <span style="font-size:12px;color:var(--text-secondary);flex:1;">${escapeHtml(id)} — ${escapeHtml(d.name)}</span>
              <span style="font-size:12px;font-weight:700;color:${col};" title="Framework adoption weight — this dimension's share of overall ASAF score">${w}% <span style="font-size:10px;font-weight:400;color:#475569;">weight</span></span>
            </div>`;
        }).join('')}
        <div style="margin-top:20px;padding-top:14px;border-top:1px solid var(--border-color);">
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:var(--text-muted);margin-bottom:8px;">Legend</div>
          <div style="display:flex;flex-direction:column;gap:6px;font-size:12px;">
            <div style="display:flex;align-items:center;gap:8px;"><span style="width:20px;height:3px;background:#22c55e;display:inline-block;border-radius:2px;"></span><span style="color:var(--text-secondary);">Stage 5 — Fully Agentic (target)</span></div>
            <div style="display:flex;align-items:center;gap:8px;"><span style="width:20px;height:3px;background:#f59e0b;display:inline-block;border-radius:2px;"></span><span style="color:var(--text-secondary);">Stage 3 — Directed Autonomy (3-yr goal)</span></div>
            <div style="display:flex;align-items:center;gap:8px;"><span style="width:20px;height:3px;background:#6b7280;display:inline-block;border-radius:2px;border-style:dashed;"></span><span style="color:var(--text-secondary);">Stage 1 — Assisted (typical today)</span></div>
          </div>
        </div>
      </div>
    </div>`;

    // Draw radar with Canvas API (no external dep)
    const canvas = document.getElementById('asmf-radar-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const drawW = Math.max(320, Math.floor(canvas.clientWidth || canvasMaxW));
    const drawH = Math.max(340, Math.floor(canvas.clientHeight || canvasMaxH));
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(drawW * dpr);
    canvas.height = Math.floor(drawH * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const margin = Math.max(42, Math.min(70, drawW * 0.12));
    const cx = drawW / 2;
    const cy = (drawH / 2) + 8;
    const R = Math.max(110, (Math.min(drawW, drawH) / 2) - margin);
    const gridFont = Math.max(9, Math.min(11, Math.round(drawW / 56)));
    const axisCodeFont = Math.max(9, Math.min(12, Math.round(drawW / 50)));
    const axisLinePct = drawW < 420 ? 103 : 105;
    const axisLabelPct = drawW < 420 ? 114 : 120;
    const n = dims.length;
    const angle0 = -Math.PI/2;

    function radarPoint(i, val) {
        const a = angle0 + (2*Math.PI*i/n);
        const r = R * val / 100;
        return [cx + r*Math.cos(a), cy + r*Math.sin(a)];
    }

    ctx.clearRect(0,0,drawW,drawH);

    // Grid rings
    [20,40,60,80,100].forEach(pct => {
        ctx.beginPath();
        for (let i=0;i<n;i++) {
            const [x,y]=radarPoint(i,pct);
            i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);
        }
        ctx.closePath();
        ctx.strokeStyle = pct===100 ? '#334155' : '#1e293b';
        ctx.lineWidth = pct===100?1.5:0.8;
        ctx.stroke();
        ctx.fillStyle='#475569';
        ctx.font=`${gridFont}px system-ui`;
        ctx.textAlign='center';
        const [lx,ly]=radarPoint(0,pct);
        ctx.fillText(pct+'%', lx+4, ly-4);
    });

    // Axis spokes + labels
    dims.forEach(([id,d],i) => {
        const a = angle0 + (2*Math.PI*i/n);
        const [x2,y2]=radarPoint(i,axisLinePct);
        ctx.beginPath();
        ctx.moveTo(cx,cy);
        ctx.lineTo(x2,y2);
        ctx.strokeStyle='#1e293b';ctx.lineWidth=0.8;ctx.stroke();
        // Label
        const [lx,ly]=radarPoint(i,axisLabelPct);
        ctx.fillStyle=_asmfDimColor(d.plane||'');
        ctx.font=`bold ${axisCodeFont}px system-ui`;
        ctx.textAlign=lx>cx+5?'left':lx<cx-5?'right':'center';
        ctx.fillText(id,lx,ly);
    });

    function drawDataset(values, color, fillAlpha) {
        ctx.beginPath();
        values.forEach((v,i) => {
            const [x,y]=radarPoint(i,v);
            i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);
        });
        ctx.closePath();
        ctx.fillStyle = color + Math.round(fillAlpha*255).toString(16).padStart(2,'0');
        ctx.fill();
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    drawDataset(stage1, '#6b7280', 0.12);
    drawDataset(stage3, '#f59e0b', 0.14);
    drawDataset(stage5, '#22c55e', 0.18);

    // Centre dot
    ctx.beginPath();ctx.arc(cx,cy,5,0,2*Math.PI);ctx.fillStyle='#f1f5f9';ctx.fill();

    if (!_asmfRadarResizeBound) {
        _asmfRadarResizeBound = true;
        window.addEventListener('resize', () => {
            if (_asmfRadarResizeTimer) clearTimeout(_asmfRadarResizeTimer);
            _asmfRadarResizeTimer = setTimeout(() => {
                const pane = document.getElementById('asmf-matrix-pane-radar');
                if (pane && pane.classList.contains('active')) {
                    populateASMFRadar();
                }
            }, 120);
        });
    }
}

// ── ASMF Effort Flow (Sankey-style SVG) ──────────────────────────────────────

async function populateASMFSankey() {
    const el = document.getElementById('asmf-sankey-content');
    if (!el) return;

    const availableW = Math.max(0, Math.floor((el.clientWidth || el.parentElement?.clientWidth || 0) - 4));
    const W = Math.max(760, Math.min(1400, availableW || 900));
    const stageLabels = ASMF_STAGE_LABELS;
    const stageColors = ASMF_STAGE_COLORS;

    // Nodes: columns = operational layers, rows = effort actors
    // Layout: left = inputs, right = outcomes, rows = human/agentic split
    const cols = [
        { x: 60,  label: 'Signal\nSources',    color: '#06b6d4' },
        { x: 220, label: 'Detection &\nEnrichment', color: '#8b5cf6' },
        { x: 380, label: 'AI Reasoning\nEngine', color: '#3b82f6' },
        { x: 540, label: 'Response\nOrchestration', color: '#f59e0b' },
        { x: 700, label: 'Human\nOversight', color: '#f97316' },
        { x: 860, label: 'Business\nOutcomes', color: '#22c55e' },
    ];

    // Effort bands per stage (human% vs agentic%)
    const stages = [
        { human: 95, agentic: 5,  label: 'Stage 0\nTraditional' },
        { human: 75, agentic: 25, label: 'Stage 1\nAssisted' },
        { human: 55, agentic: 45, label: 'Stage 2\nSupervised' },
        { human: 35, agentic: 65, label: 'Stage 3\nDirected' },
        { human: 15, agentic: 85, label: 'Stage 4\nCollaborative' },
        { human: 5,  agentic: 95, label: 'Stage 5\nFully Agentic' },
    ];

    // Shift everything right to give labels room on the left
    const labelW = Math.max(96, Math.min(128, Math.round(W * 0.14))); // px reserved for stage labels
    const barX   = labelW + 10;
    const barW2  = W - barX - 20;
    const rowH = W >= 1200 ? 78 : W >= 920 ? 72 : 64;
    const topY = 60;
    const H = topY + (stages.length * rowH) + 50;
    const nodeW = Math.max(92, Math.min(112, Math.round(W * 0.11)));
    const nodeH = 40;
    const colInnerPad = (nodeW / 2) + 4;
    const colXMin = barX + colInnerPad;
    const colXSpan = Math.max(40, barW2 - (colInnerPad * 2));

    let svg = `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="width:100%;max-width:100%;height:auto;overflow:visible;" font-family="system-ui,sans-serif">`;

    // Column headers (shifted right)
    cols.forEach(c => {
        const cx2 = colXMin + (c.x / 860) * colXSpan;
        const lines = c.label.split('\n');
        svg += `<rect x="${cx2-nodeW/2}" y="${topY-32}" width="${nodeW}" height="26" rx="4" fill="${c.color}22" stroke="${c.color}" stroke-width="1.5"/>`;
        lines.forEach((l,i) => svg += `<text x="${cx2}" y="${topY-32+10+(i*12)}" text-anchor="middle" font-size="10" font-weight="700" fill="${c.color}">${escapeHtml(l)}</text>`);
    });

    // Stage rows — horizontal bands showing human/agentic split
    stages.forEach((s, si) => {
        const y = topY + si * rowH;
        const color = stageColors[si];
        const agW = barW2 * s.agentic / 100;
        const humW = barW2 * s.human / 100;

        svg += `<rect x="${barX}" y="${y}" width="${humW}" height="28" rx="3" fill="#6b728033"/>`;
        svg += `<rect x="${barX+humW}" y="${y}" width="${agW}" height="28" rx="3" fill="${color}44"/>`;
        svg += `<rect x="${barX}" y="${y}" width="${barW2}" height="28" rx="3" fill="none" stroke="${color}33" stroke-width="1"/>`;

        // Labels fully inside the left margin — two lines, right-aligned at labelW-4
        const lines = s.label.split('\n');
        lines.forEach((l,i) => svg += `<text x="${labelW-4}" y="${y+10+(i*12)}" text-anchor="end" font-size="10" font-weight="${i===0?'700':'400'}" fill="${color}">${escapeHtml(l)}</text>`);

        svg += `<text x="${barX+humW/2}" y="${y+18}" text-anchor="middle" font-size="11" fill="#94a3b8">${s.human}% human</text>`;
        svg += `<text x="${barX+humW+agW/2}" y="${y+18}" text-anchor="middle" font-size="11" fill="${color}" font-weight="600">${s.agentic}% agentic</text>`;
    });

    // Column lines (shifted)
    cols.forEach(c => {
        const cx2 = colXMin + (c.x / 860) * colXSpan;
        svg += `<line x1="${cx2}" y1="${topY}" x2="${cx2}" y2="${topY+stages.length*rowH}" stroke="${c.color}40" stroke-width="1" stroke-dasharray="3,3"/>`;
    });

    // Legend
    svg += `<text x="${W/2}" y="${H-10}" text-anchor="middle" font-size="11" fill="#475569">Width of each band = proportion of work handled by humans (grey) vs. agentic systems (colored)</text>`;

    svg += `</svg>`;

    el.innerHTML = `
    <div style="margin-bottom:20px;font-size:13px;color:var(--text-secondary);line-height:1.6;max-width:100%;">
      Each horizontal band represents an adoption stage. As you move from Stage 0 (Traditional) to Stage 5 (Fully Agentic),
      agentic systems absorb an increasing proportion of the work across every operational layer — from signal ingestion through to business outcomes.
    </div>
    <div class="asmf-responsive-svg-wrap">${svg}</div>
    <div style="margin-top:20px;display:flex;flex-wrap:wrap;gap:12px;">
      ${stages.map((s,i)=>`<div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-secondary);">
        <span style="width:14px;height:14px;border-radius:3px;background:${stageColors[i]};display:inline-block;"></span>
        ${escapeHtml(s.label.replace('\n',' — '))}
      </div>`).join('')}
    </div>`;

    if (!_asmfSankeyResizeBound) {
        _asmfSankeyResizeBound = true;
        window.addEventListener('resize', () => {
            if (_asmfSankeyResizeTimer) clearTimeout(_asmfSankeyResizeTimer);
            _asmfSankeyResizeTimer = setTimeout(() => {
                const pane = document.getElementById('asmf-matrix-pane-sankey');
                if (pane && pane.classList.contains('active')) {
                    populateASMFSankey();
                }
            }, 120);
        });
    }
}

// ── ASMF Capability Pyramid ───────────────────────────────────────────────────

async function populateASMFPyramid() {
    const el = document.getElementById('asmf-pyramid-content');
    if (!el) return;
    if (!_asmfFramework) {
        try { const r = await fetch('/api/asmf-framework'); _asmfFramework = await r.json(); }
        catch(e) { el.innerHTML = `<p style="color:#ef4444">${escapeHtml(String(e))}</p>`; return; }
    }

    // 6 pyramid layers, bottom = foundation, top = fully agentic
    const layers = [
        { stage: 0, label: 'Traditional SOC Foundation', color: '#6b7280',
          cap: 'Manual SIEM triage, rule-based alerts, L1/L2/L3 tiering',
          dims: ['SEN','RSN'], outcome: 'Reactive incident response with significant human backlog' },
        { stage: 1, label: 'AI-Assisted Operations', color: '#3b82f6',
          cap: 'ML-aided alert triage, automated enrichment, SOAR playbooks',
          dims: ['SEN','RSN','ACT'], outcome: 'Reduced MTTD, analyst augmentation, faster playbook execution' },
        { stage: 2, label: 'Supervised Autonomy', color: '#8b5cf6',
          cap: 'Agents execute bounded tasks autonomously with human approval gates',
          dims: ['ACT','GOV','HUM'], outcome: 'MTTD < 1hr, automated containment for known threat classes' },
        { stage: 3, label: 'Directed Autonomy', color: '#f59e0b',
          cap: 'Agents define and execute multi-step response chains; humans set objectives',
          dims: ['GOV','LRN','AGT'], outcome: 'Sub-minute response for common threats, strategic human focus' },
        { stage: 4, label: 'Collaborative Agentic', color: '#10b981',
          cap: 'Agent swarms coordinate across domains; humans focus on novel threats and governance',
          dims: ['AGT','SKG','MET'], outcome: 'MTTD seconds, predictive threat disruption, adaptive learning' },
        { stage: 5, label: 'Fully Agentic SOC', color: '#22c55e',
          cap: 'Continuous self-improving autonomous operations; humans set strategy and policy',
          dims: ['TRN','OPS','MET'], outcome: 'Near-zero dwell time, autonomous adversary modeling, self-healing infrastructure' },
    ];

    const totalW = 760;
    const layerH = 72;

    const layerHTML = layers.slice().reverse().map((l, ri) => {
        const si = layers.length - 1 - ri;
        const widthPct = 38 + (si / (layers.length-1)) * 62; // 38% to 100%
        const dimBadges = l.dims.map(d =>
            `<span style="background:${l.color}33;color:${l.color};padding:1px 7px;border-radius:10px;font-size:10px;font-weight:700;margin-right:4px;">${d}</span>`
        ).join('');
        return `
        <div style="display:flex;justify-content:center;margin-bottom:3px;" title="${escapeHtml(l.outcome)}">
          <div style="width:${widthPct}%;min-height:${layerH}px;background:${l.color}22;border:2px solid ${l.color}66;
                      border-radius:6px;padding:10px 16px;position:relative;transition:all 0.2s;cursor:default;"
               onmouseenter="this.style.background='${l.color}44'" onmouseleave="this.style.background='${l.color}22'">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">
              <div>
                <div style="font-size:11px;font-weight:800;color:${l.color};text-transform:uppercase;letter-spacing:0.5px;">Stage ${l.stage} — ${escapeHtml(l.label)}</div>
                <div style="font-size:12px;color:var(--text-secondary);margin-top:3px;line-height:1.4;">${escapeHtml(l.cap)}</div>
                <div style="margin-top:5px;">${dimBadges}</div>
              </div>
            </div>
          </div>
        </div>`;
    }).join('');

    el.innerHTML = `
    <div style="margin-bottom:20px;font-size:13px;color:var(--text-secondary);line-height:1.6;max-width:100%;">
      Each layer represents an adoption stage. The pyramid grows narrower at the top — fewer organizations reach higher stages,
      but those that do achieve exponentially better outcomes. Hover any layer to see the expected outcome.
    </div>
    <div style="padding:0 clamp(0px,2vw,20px);width:100%;">
      <div style="text-align:center;margin-bottom:6px;font-size:11px;color:var(--text-muted);">▲ Increasing autonomy, decreasing mean time to detect &amp; respond</div>
      ${layerHTML}
      <div style="text-align:center;margin-top:6px;font-size:11px;color:var(--text-muted);">▼ Foundation: data sources, sensors, security tooling</div>
    </div>
    <div style="margin-top:28px;padding-top:20px;border-top:1px solid var(--border-color);">
      <div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:12px;">Outcome by stage (hover layers for detail)</div>
      <div style="display:flex;flex-direction:column;gap:6px;">
        ${layers.map(l=>`<div style="display:flex;align-items:baseline;gap:10px;font-size:12px;">
          <span style="color:${l.color};font-weight:700;white-space:nowrap;min-width:70px;">Stage ${l.stage}</span>
          <span style="color:var(--text-secondary);">${escapeHtml(l.outcome)}</span>
        </div>`).join('')}
      </div>
    </div>`;
}

// ── ASMF Journey Timeline ─────────────────────────────────────────────────────

async function populateASMFTimeline() {
    const el = document.getElementById('asmf-timeline-content');
    if (!el) return;
    if (!_asmfFramework) {
        try { const r = await fetch('/api/asmf-framework'); _asmfFramework = await r.json(); }
        catch(e) { el.innerHTML = `<p style="color:#ef4444">${escapeHtml(String(e))}</p>`; return; }
    }

    const phases = (_asmfFramework.transformation_journey?.phases) || [];

    const phaseCards = phases.map((p, i) => {
        const color = ASMF_STAGE_COLORS[i + 1] || '#64748b';
        const acts = (p.key_activities || []).map(a => `<li style="padding:2px 0;">${escapeHtml(a)}</li>`).join('');
        const fails = (p.failure_modes || []).map(f => `<li style="padding:2px 0;color:#ef4444;">${escapeHtml(f)}</li>`).join('');
        const inflections = (p.inflection_points || []).map(ip => `<li style="padding:2px 0;color:#22c55e;">${escapeHtml(ip)}</li>`).join('');
        return `
        <div style="position:relative;flex:1;min-width:180px;background:var(--bg-secondary);border:1px solid var(--border-color);
                    border-top:4px solid ${color};border-radius:8px;padding:16px 14px;">
          <!-- Phase number bubble -->
          <div style="position:absolute;top:-18px;left:50%;transform:translateX(-50%);
                      width:32px;height:32px;border-radius:50%;background:${color};
                      display:flex;align-items:center;justify-content:center;
                      font-size:14px;font-weight:800;color:#fff;border:3px solid var(--bg-primary);">${i+1}</div>
          <div style="font-size:11px;color:${color};font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;margin-top:8px;">${escapeHtml(p.transition||'')}</div>
          <div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:4px;">${escapeHtml(p.label||'')}</div>
          <div style="font-size:11px;color:var(--text-muted);margin-bottom:10px;">⏱ ${escapeHtml(p.approximate_duration||'')}</div>
          <div style="font-size:12px;color:var(--text-secondary);line-height:1.5;margin-bottom:10px;">${escapeHtml(p.description||'')}</div>
          ${acts ? `<div style="font-size:11px;font-weight:700;color:var(--text-muted);margin-bottom:4px;">Key activities</div>
          <ul style="margin:0 0 10px;padding-left:14px;font-size:11px;">${acts}</ul>` : ''}
          ${inflections ? `<div style="font-size:11px;font-weight:700;color:#22c55e;margin-bottom:4px;">✓ Inflection points</div>
          <ul style="margin:0 0 10px;padding-left:14px;font-size:11px;">${inflections}</ul>` : ''}
          ${fails ? `<div style="font-size:11px;font-weight:700;color:#ef4444;margin-bottom:4px;">⚠ Failure modes</div>
          <ul style="margin:0;padding-left:14px;font-size:11px;">${fails}</ul>` : ''}
        </div>`;
    }).join('');

    // Arc connector SVG
    const arcW = Math.max(1, phases.length) * 210;
    let arcSvg = `<svg width="${arcW}" height="30" viewBox="0 0 ${arcW} 30" style="width:100%;max-width:100%;height:auto;overflow:visible;">`;
    for (let i = 0; i < phases.length - 1; i++) {
        const x1 = 105 + i * 210, x2 = x1 + 210;
        const color = ASMF_STAGE_COLORS[i + 2] || '#64748b';
        arcSvg += `<path d="M${x1} 15 Q${(x1+x2)/2} 2 ${x2} 15" fill="none" stroke="${color}" stroke-width="2.5" stroke-dasharray="5,3"/>`;
        arcSvg += `<polygon points="${x2-6},10 ${x2},15 ${x2-6},20" fill="${color}"/>`;
    }
    arcSvg += `</svg>`;

    el.innerHTML = `
    <div style="margin-bottom:28px;font-size:13px;color:var(--text-secondary);line-height:1.6;max-width:100%;">
      The transformation is not linear — each phase has specific inflection points that must be reached before the next phase becomes accessible.
      Organizations that skip phases typically encounter compounding failure modes.
    </div>
        <div style="padding:24px 0 0;width:100%;">
            <div class="asmf-responsive-svg-wrap" style="margin-bottom:4px;">${arcSvg}</div>
            <div class="asmf-timeline-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;width:100%;">${phaseCards}</div>
    </div>`;
}

// ── ASMF Orbital Model (concentric rings canvas) ──────────────────────────────

async function populateASMFOrbital() {
    const el = document.getElementById('asmf-orbital-content');
    if (!el) return;

    // ── Load data (framework + relationship map) ──────────────────────────
    try {
        const toFetch = [];
        if (!_asmfFramework)  toFetch.push(fetch('/api/asmf-framework').then(r=>r.json()).then(d=>{ _asmfFramework=d; }));
        if (!_asmfOrbitalMap) toFetch.push(fetch('/api/asmf-orbital-map').then(r=>r.json()).then(d=>{ _asmfOrbitalMap=d; }));
        if (toFetch.length) await Promise.all(toFetch);
    } catch(e) {
        el.innerHTML = `<p style="color:#ef4444;padding:20px;">${escapeHtml(String(e))}</p>`;
        return;
    }

    const fw       = _asmfFramework;
    const orbMap   = _asmfNormalizeOrbitalMap(_asmfFramework, _asmfOrbitalMap);
    const dims     = Object.entries(fw.dimensions || {});
    const rels     = orbMap.relationships      || [];
    const relTypes = orbMap.relationship_types || {};
    const dimCfg   = orbMap.dim_config         || {};
    const fwAbbr   = fw.framework_abbrev || getASMFRootLabel() || 'ASMF';
    const orbitalTitle = `${fwAbbr} Integration Map`;

    // ── Layout constants ──────────────────────────────────────────────────
    const OV_RING_R  = 215;   // overview dim ring
    const FO_INNER_R = 125;   // focus: sub-dim ring
    const FO_OUTER_R = 285;   // focus: outer dim ring

    // ── Build node list ───────────────────────────────────────────────────
    const allNodes = [];
    function mkNode(o) { return Object.assign({ tx:0, ty:0, alpha:1, talpha:1, tr:20, r:4 }, o); }

    // Root node
    allNodes.push(mkNode({ id:'__root__', type:'root', label:getASMFRootLabel(), x:0, y:0, tx:0, ty:0, r:34, tr:34, color:'#3b82f6' }));

    // Dimension nodes
    const dimCount = dims.length;
    dims.forEach(([id, dim], i) => {
        const cfg   = dimCfg[id] || {};
        const color = cfg.color  || '#3b82f6';
        const a     = (2 * Math.PI * i / dimCount) - Math.PI / 2;
        const ox    = OV_RING_R * Math.cos(a);
        const oy    = OV_RING_R * Math.sin(a);
        allNodes.push(mkNode({
            id, type:'dim', label:id, name:dim.name||id, color,
            plane: cfg.plane||'', overviewAngle:a, overviewX:ox, overviewY:oy,
            x:ox, y:oy, tx:ox, ty:oy, r:24, tr:24, alpha:1, talpha:1,
            dim
        }));
    });

    // Sub-dim nodes (start collapsed at parent position, invisible)
    dims.forEach(([dimId, dim]) => {
        const parent = allNodes.find(n => n.id === dimId);
        const subArr = Object.entries(dim.sub_dimensions || {});
        subArr.forEach(([sdId, sd], si) => {
            allNodes.push(mkNode({
                id:`${dimId}__${sdId}`, type:'subdim', parentId:dimId,
                label:sdId, name:sd.name||sdId, color:parent.color,
                x:parent.x, y:parent.y, tx:parent.x, ty:parent.y,
                r:4, tr:4, alpha:0, talpha:0,
                sd, parentNode:parent, subIdx:si, subCount:subArr.length
            }));
        });
    });

    // ── App state ─────────────────────────────────────────────────────────
    let mode='overview', selectedDim=null, selectedSub=null, hoverId=null;
    let camX=0, camY=0, camZ=1, tX=0, tY=0, tZ=1;
    let dragging=false, dragSX=0, dragSY=0, camSX=0, camSY=0;
    let raf;

    // ── HTML scaffold ─────────────────────────────────────────────────────
        el.style.cssText = 'background:#0a0f1a;position:relative;display:flex;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;';
    el.innerHTML = `
            <canvas id="asmf-orbital-canvas" style="flex:1 1 auto;min-width:0;width:100%;height:100%;cursor:grab;display:block;"></canvas>
                        <div id="asmf-orbital-detail" style="width:clamp(280px,28vw,420px);flex:0 1 clamp(280px,28vw,420px);min-width:min(280px,38vw);max-width:min(420px,42vw);background:#0f172a;border-left:1px solid #334155;display:flex;flex-direction:column;overflow:hidden;position:relative;z-index:2;box-shadow:-18px 0 32px rgba(2,6,23,0.35);">
        <div id="asmf-orbital-hdr" style="padding:14px 18px 12px;border-bottom:1px solid #1e293b;flex-shrink:0;">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
                        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#475569;">${escapeHtml(orbitalTitle)}</div>
            <div style="display:flex;gap:6px;align-items:center;">
              <button id="asmf-orbital-back" style="display:none;background:#1e293b;border:1px solid #334155;color:#94a3b8;font-size:11px;padding:3px 10px;border-radius:4px;cursor:pointer;white-space:nowrap;">← All</button>
              <button id="asmf-orbital-export" style="background:#1e3a5f;border:1px solid #1d4ed8;color:#93c5fd;font-size:11px;padding:3px 10px;border-radius:4px;cursor:pointer;white-space:nowrap;" title="Export as interactive standalone HTML">⬇ Export</button>
            </div>
          </div>
          <div id="asmf-orbital-crumb" style="font-size:12px;color:#64748b;margin-top:5px;">All 11 Dimensions</div>
        </div>
        <div id="asmf-orbital-body" style="flex:1;overflow-y:auto;padding:16px 18px;font-size:12px;color:#94a3b8;"></div>
      </div>`;

    const canvas  = document.getElementById('asmf-orbital-canvas');
    const detBody = document.getElementById('asmf-orbital-body');
    const crumb   = document.getElementById('asmf-orbital-crumb');
    const backBtn   = document.getElementById('asmf-orbital-back');
    const exportBtn = document.getElementById('asmf-orbital-export');
    backBtn.addEventListener('click', () => enterOverview());
    exportBtn.addEventListener('click', () => exportASMFOrbitalAsHTML(_asmfFramework, orbMap));

    function resizeCanvas() { canvas.width = canvas.offsetWidth||700; canvas.height = canvas.offsetHeight||600; }
    resizeCanvas();

    // ── Layout transitions ────────────────────────────────────────────────
    function setLayout(newMode, selId) {
        mode = newMode;
        if (newMode === 'overview') {
            allNodes.find(n=>n.id==='__root__').tx=0; allNodes.find(n=>n.id==='__root__').ty=0;
            allNodes.find(n=>n.id==='__root__').tr=34; allNodes.find(n=>n.id==='__root__').talpha=1;
            allNodes.filter(n=>n.type==='dim').forEach(n => { n.tx=n.overviewX; n.ty=n.overviewY; n.tr=24; n.talpha=1; });
            allNodes.filter(n=>n.type==='subdim').forEach(n => { n.tx=n.parentNode.overviewX; n.ty=n.parentNode.overviewY; n.tr=4; n.talpha=0; });
            tX=0; tY=0; tZ=1;
        } else if (newMode === 'dimfocus') {
            // Selected dim → center
            const focDim = allNodes.find(n=>n.id===selId);
            focDim.tx=0; focDim.ty=0; focDim.tr=44; focDim.talpha=1;
            // Root → faded corner
            const root = allNodes.find(n=>n.id==='__root__');
            root.tx=-310; root.ty=-200; root.tr=18; root.talpha=0.3;
            // Other dims → outer ring
            const otherDims = allNodes.filter(n=>n.type==='dim' && n.id!==selId);
            otherDims.forEach((n,i) => {
                const a = (2*Math.PI*i/otherDims.length) - Math.PI/2;
                n.tx=FO_OUTER_R*Math.cos(a); n.ty=FO_OUTER_R*Math.sin(a); n.tr=20; n.talpha=1;
            });
            // Selected dim's sub-dims → inner ring, full circle
            const mySubs = allNodes.filter(n=>n.type==='subdim' && n.parentId===selId);
            mySubs.forEach((n,i) => {
                const a = (2*Math.PI*i/mySubs.length) - Math.PI/2;
                n.tx=FO_INNER_R*Math.cos(a); n.ty=FO_INNER_R*Math.sin(a); n.tr=17; n.talpha=1;
            });
            // Other sub-dims → collapse to their parent's outer-ring target position
            allNodes.filter(n=>n.type==='subdim' && n.parentId!==selId).forEach(n => {
                const p = otherDims.find(d=>d.id===n.parentId);
                if (p) { n.tx=p.tx; n.ty=p.ty; }
                n.tr=4; n.talpha=0;
            });
            tX=0; tY=0; tZ=1;
        }
    }

    // ── Side panel renderers ──────────────────────────────────────────────
    function renderOverviewPanel() {
        crumb.textContent = `All ${dims.length} Dimensions`;
        backBtn.style.display = 'none';
        const typeHtml = Object.entries(relTypes).map(([k,v]) => `
          <div style="display:flex;align-items:center;gap:9px;margin-bottom:8px;">
            <span style="width:24px;height:3px;background:${v.color};border-radius:2px;flex-shrink:0;display:inline-block;"></span>
            <span style="color:#94a3b8;">${escapeHtml(v.label)}</span>
          </div>`).join('');
        detBody.innerHTML = `
          <p style="line-height:1.75;margin-bottom:16px;">This map shows how all ${dims.length} ${escapeHtml(fwAbbr)} dimensions integrate to form a fully agentic operating model. <strong style="color:#f1f5f9;">Click any dimension</strong> to bring it to the center and reveal every integration link, sub-dimension and capability flow.</p>
          <div style="border-top:1px solid #1e293b;padding-top:14px;margin-bottom:14px;">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Relationship Types</div>
            ${typeHtml}
          </div>
          <div style="border-top:1px solid #1e293b;padding-top:14px;">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:8px;">Controls</div>
            <div style="line-height:2.1;color:#64748b;">🖱 Click dim — focus &amp; see all links<br>🖱 Hover outer dim — see relationship<br>🖱 Click outer dim — shift focus<br>🖱 Click sub-dim — stage descriptors<br>🖱 Scroll — zoom · Drag — pan<br>🖱 Click background or ← All — reset</div>
          </div>`;
    }

    function renderDimPanel(dimId, hoverOtherId) {
        const dn = allNodes.find(n=>n.id===dimId);
        if (!dn) return;
        const weight  = Math.round((dn.dim.weight||0)*100);
        const outRels = rels.filter(r=>r.from===dimId);
        const inRels  = rels.filter(r=>r.to===dimId);

        if (hoverOtherId) {
            // Hover mode: show relationship details for the hovered dim
            const on = allNodes.find(n=>n.id===hoverOtherId);
            if (!on) return;
            const mutual = [
                ...outRels.filter(r=>r.to===hoverOtherId),
                ...inRels.filter(r=>r.from===hoverOtherId)
            ];
            const relHtml = mutual.length
                ? mutual.map(r => {
                    const rt = relTypes[r.type]||{color:'#94a3b8',label:r.type};
                    const dir = r.from===dimId ? `${dimId} → ${r.to}` : `${r.from} → ${dimId}`;
                    return `<div style="margin-bottom:10px;padding:10px 12px;background:#1e293b;border-radius:6px;border-left:3px solid ${rt.color};">
                      <div style="font-size:10px;font-weight:700;color:${rt.color};text-transform:uppercase;margin-bottom:5px;">${escapeHtml(rt.label)} · ${escapeHtml(dir)}</div>
                      <div style="line-height:1.6;color:#cbd5e1;">${escapeHtml(r.label)}</div>
                    </div>`;
                  }).join('')
                : `<div style="color:#475569;font-style:italic;padding:8px 0;">No direct relationship defined.</div>`;
            detBody.innerHTML = `
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">
                <span style="width:11px;height:11px;border-radius:50%;background:${on.color};flex-shrink:0;display:inline-block;"></span>
                <span style="font-size:16px;font-weight:700;color:#f1f5f9;">${escapeHtml(hoverOtherId)}</span>
                <span style="font-size:10px;color:#475569;margin-left:auto;">${escapeHtml(on.plane||'')}</span>
              </div>
              <div style="font-size:12px;color:#94a3b8;margin-bottom:14px;">${escapeHtml(on.name)}</div>
              <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Relationship with ${escapeHtml(dimId)}</div>
              ${relHtml}
              <div style="margin-top:12px;font-size:11px;color:#475569;">Click to shift focus to ${escapeHtml(hoverOtherId)}</div>`;
            return;
        }

        // Full dim detail view
        const subHtml = allNodes.filter(n=>n.type==='subdim'&&n.parentId===dimId).map(sn => `
          <div style="margin-bottom:7px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid ${dn.color};cursor:pointer;" data-subdim="${escapeHtml(sn.id)}">
            <div style="font-size:11px;font-weight:700;color:${dn.color};">${escapeHtml(sn.id.replace(dimId+'__',''))}</div>
            <div style="font-size:11px;color:#cbd5e1;margin-top:2px;">${escapeHtml(sn.name)}</div>
          </div>`).join('');

        const allDimRels = [
            ...outRels.map(r => ({ dir:'→', other:r.to,   r, rt:relTypes[r.type]||{color:'#94a3b8',label:r.type} })),
            ...inRels.map( r => ({ dir:'←', other:r.from, r, rt:relTypes[r.type]||{color:'#94a3b8',label:r.type} }))
        ].sort((a,b) => a.other.localeCompare(b.other));

        const relHtml = allDimRels.map(({dir, other, r, rt}) => {
            const on = allNodes.find(n=>n.id===other);
            return `<div style="margin-bottom:7px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid ${rt.color};">
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">
                <span style="font-size:11px;font-weight:700;color:${rt.color};">${dir}</span>
                <span style="font-size:11px;font-weight:700;color:${on?on.color:'#94a3b8'};">${escapeHtml(other)}</span>
                <span style="font-size:10px;color:#475569;margin-left:auto;">${escapeHtml(rt.label)}</span>
              </div>
              <div style="font-size:11px;color:#94a3b8;line-height:1.5;">${escapeHtml(r.label)}</div>
            </div>`;
        }).join('');

        detBody.innerHTML = `
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
            <span style="width:12px;height:12px;border-radius:50%;background:${dn.color};flex-shrink:0;display:inline-block;"></span>
            <span style="font-size:18px;font-weight:700;color:#f1f5f9;">${escapeHtml(dimId)}</span>
          </div>
          <div style="font-size:12px;color:#94a3b8;margin-bottom:2px;">${escapeHtml(dn.name)}</div>
          <div style="font-size:10px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:14px;">${escapeHtml(dn.plane)} · Weight: ${weight}%</div>
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:8px;">Sub-Dimensions</div>
          ${subHtml}
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:6px;margin-top:16px;">Integration Links <span style="color:#334155;font-weight:400;">${allDimRels.length} connections</span></div>
          <div style="font-size:11px;color:#475569;margin-bottom:10px;">Hover outer nodes to inspect each relationship.</div>
          ${relHtml}`;

        detBody.querySelectorAll('[data-subdim]').forEach(el2 => {
            el2.addEventListener('click', () => {
                const sn = allNodes.find(n=>n.id===el2.dataset.subdim);
                if (sn) { selectedSub=sn.id; renderSubPanel(sn); }
            });
        });
    }

    function renderSubPanel(sn) {
        const sdLabel = sn.id.replace(sn.parentId+'__','');
        const stagesHtml = ['0','1','2','3','4','5'].map(sk => {
            const text  = (sn.sd.stage_descriptors||{})[sk] || '—';
            const color = ASMF_STAGE_COLORS[+sk];
            const lbl   = ASMF_STAGE_LABELS[+sk];
            return `<div style="margin-bottom:8px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid ${color};">
              <div style="font-size:10px;font-weight:700;color:${color};text-transform:uppercase;letter-spacing:0.5px;margin-bottom:3px;">Stage ${sk} — ${escapeHtml(lbl)}</div>
              <div style="font-size:11px;color:#cbd5e1;line-height:1.55;">${escapeHtml(text)}</div>
            </div>`;
        }).join('');
        crumb.textContent = `${selectedDim} › ${sdLabel}`;
        detBody.innerHTML = `
          <div style="font-size:10px;color:#475569;margin-bottom:6px;">↑ ${escapeHtml(sn.parentId)}</div>
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
            <span style="width:10px;height:10px;border-radius:50%;background:${sn.color};flex-shrink:0;display:inline-block;"></span>
            <span style="font-size:15px;font-weight:700;color:#f1f5f9;">${escapeHtml(sdLabel)}</span>
          </div>
          <div style="font-size:12px;color:#94a3b8;margin-bottom:14px;">${escapeHtml(sn.name)}</div>
          <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Adoption Stage Descriptors</div>
          ${stagesHtml}
          <div style="margin-top:14px;">
            <button id="asmf-back-to-dim" style="background:#1e293b;border:1px solid #334155;color:#94a3b8;font-size:11px;padding:5px 12px;border-radius:4px;cursor:pointer;">← Back to ${escapeHtml(sn.parentId)}</button>
          </div>`;
        document.getElementById('asmf-back-to-dim')?.addEventListener('click', () => {
            selectedSub = null;
            crumb.textContent = selectedDim;
            renderDimPanel(selectedDim, null);
        });
    }

    function enterOverview() {
        selectedDim=null; selectedSub=null;
        setLayout('overview', null);
        renderOverviewPanel();
    }

    function enterDimFocus(dimId) {
        selectedDim=dimId; selectedSub=null;
        setLayout('dimfocus', dimId);
        const dn = allNodes.find(n=>n.id===dimId);
        crumb.textContent = `${dimId} — ${dn?.name||''}`;
        backBtn.style.display = 'block';
        renderDimPanel(dimId, null);
    }

    // ── Coord helpers ─────────────────────────────────────────────────────
    function w2s(wx, wy) { return [canvas.width/2+(wx+camX)*camZ, canvas.height/2+(wy+camY)*camZ]; }
    function s2w(sx, sy) { return [(sx-canvas.width/2)/camZ-camX, (sy-canvas.height/2)/camZ-camY]; }

    function hitNode(sx, sy) {
        const [wx,wy] = s2w(sx,sy);
        const candidates = allNodes.filter(n => {
            if (n.alpha < 0.15) return false;
            if (n.type==='subdim' && n.parentId!==selectedDim) return false;
            return true;
        });
        for (let i=candidates.length-1; i>=0; i--) {
            const n=candidates[i];
            const dx=n.x-wx, dy=n.y-wy;
            if (dx*dx+dy*dy <= (n.r+5)*(n.r+5)) return n;
        }
        return null;
    }

    // ── Arrow drawing helper ──────────────────────────────────────────────
    function drawArrow(ctx, fx,fy,fr, tx2,ty2,tr2, color, lw, dash) {
        const dx=tx2-fx, dy=ty2-fy, len=Math.sqrt(dx*dx+dy*dy);
        if (len < fr+tr2+8) return;
        const ux=dx/len, uy=dy/len;
        const sx=fx+ux*(fr+2), sy=fy+uy*(fr+2);
        const ex=tx2-ux*(tr2+2), ey=ty2-uy*(tr2+2);
        ctx.beginPath(); ctx.moveTo(sx,sy); ctx.lineTo(ex,ey);
        ctx.strokeStyle=color; ctx.lineWidth=lw;
        ctx.setLineDash(dash||[]); ctx.stroke(); ctx.setLineDash([]);
        // Arrowhead
        const hs = Math.max(5, 7*camZ);
        ctx.beginPath();
        ctx.moveTo(ex, ey);
        ctx.lineTo(ex - ux*hs + uy*hs*0.45, ey - uy*hs - ux*hs*0.45);
        ctx.lineTo(ex - ux*hs - uy*hs*0.45, ey - uy*hs + ux*hs*0.45);
        ctx.closePath(); ctx.fillStyle=color; ctx.fill();
    }

    // ── Draw loop ─────────────────────────────────────────────────────────
    function draw() {
        // Lerp nodes toward targets
        allNodes.forEach(n => {
            n.x     += (n.tx     - n.x)     * 0.10;
            n.y     += (n.ty     - n.y)     * 0.10;
            n.r     += (n.tr     - n.r)     * 0.12;
            n.alpha += (n.talpha - n.alpha) * 0.10;
        });
        // Lerp camera
        camX += (tX-camX)*0.12; camY += (tY-camY)*0.12; camZ += (tZ-camZ)*0.12;

        const W=canvas.width, H=canvas.height;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0,0,W,H);
        ctx.fillStyle='#0a0f1a'; ctx.fillRect(0,0,W,H);

        // Stars (deterministic)
        for (let i=0;i<120;i++) {
            ctx.globalAlpha=0.06+(i%7)*0.02; ctx.fillStyle='#fff';
            ctx.beginPath(); ctx.arc((i*137.508+11)%W,(i*91.3+17)%H,(i%3)*0.35+0.3,0,Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha=1;

        // Guide rings
        const [ocx,ocy] = w2s(0,0);
        ctx.lineWidth=1;
        if (mode==='overview') {
            ctx.beginPath(); ctx.arc(ocx,ocy,OV_RING_R*camZ,0,Math.PI*2);
            ctx.strokeStyle='#1e293b55'; ctx.setLineDash([4,8]); ctx.stroke(); ctx.setLineDash([]);
        } else {
            ctx.beginPath(); ctx.arc(ocx,ocy,FO_INNER_R*camZ,0,Math.PI*2);
            ctx.strokeStyle='#1e293b77'; ctx.setLineDash([3,6]); ctx.stroke(); ctx.setLineDash([]);
            ctx.beginPath(); ctx.arc(ocx,ocy,FO_OUTER_R*camZ,0,Math.PI*2);
            ctx.strokeStyle='#1e293b33'; ctx.setLineDash([4,10]); ctx.stroke(); ctx.setLineDash([]);
        }

        // ── Cross-dim relationship arrows (focus mode) ────────────────────
        if (mode==='dimfocus' && selectedDim) {
            const cenNode = allNodes.find(n=>n.id===selectedDim);
            const [csx,csy] = w2s(cenNode.x,cenNode.y);
            const dimRels = rels.filter(r=>r.from===selectedDim || r.to===selectedDim);

            dimRels.forEach(r => {
                const othId  = r.from===selectedDim ? r.to : r.from;
                const oth    = allNodes.find(n=>n.id===othId);
                if (!oth || oth.alpha<0.1) return;
                const [osx,osy] = w2s(oth.x,oth.y);
                const rt   = relTypes[r.type]||{color:'#94a3b8',dash:[]};
                const isHov= (hoverId===othId);
                const alpha= isHov ? 0.95 : 0.5;
                const col  = rt.color + Math.round(alpha*255).toString(16).padStart(2,'0');
                const lw   = ((r.strength||1)*0.7 + 0.4) * Math.max(0.6,camZ);

                if (r.from===selectedDim) {
                    drawArrow(ctx, csx,csy,cenNode.r*camZ, osx,osy,oth.r*camZ, col, lw, rt.dash||[]);
                } else {
                    drawArrow(ctx, osx,osy,oth.r*camZ, csx,csy,cenNode.r*camZ, col, lw, rt.dash||[]);
                }

                // Type badge at midpoint (only when visible enough)
                if (camZ > 0.5 && !isHov) {
                    const mx=(csx+osx)/2, my=(csy+osy)/2;
                    const abbr = rt.abbr||r.type.slice(0,2).toUpperCase();
                    const bfs  = Math.max(8, Math.round(8.5*camZ));
                    ctx.font   = `bold ${bfs}px system-ui`;
                    const bw   = ctx.measureText(abbr).width + 6;
                    const bh   = bfs + 4;
                    ctx.fillStyle='#0a0f1aee';
                    ctx.beginPath();
                    ctx.roundRect(mx-bw/2, my-bh/2, bw, bh, 3);
                    ctx.fill();
                    ctx.fillStyle=rt.color;
                    ctx.textAlign='center'; ctx.textBaseline='middle';
                    ctx.fillText(abbr, mx, my);
                    ctx.textBaseline='alphabetic';
                }
            });
        }

        // ── Sub-dim spoke lines ───────────────────────────────────────────
        if (mode==='dimfocus' && selectedDim) {
            const cen = allNodes.find(n=>n.id===selectedDim);
            const [csx,csy] = w2s(cen.x,cen.y);
            allNodes.filter(n=>n.type==='subdim'&&n.parentId===selectedDim&&n.alpha>0.05).forEach(sn=>{
                const [sx2,sy2]=w2s(sn.x,sn.y);
                ctx.beginPath(); ctx.moveTo(csx,csy); ctx.lineTo(sx2,sy2);
                ctx.strokeStyle=sn.color+'44'; ctx.lineWidth=1.5;
                ctx.setLineDash([3,5]); ctx.stroke(); ctx.setLineDash([]);
            });
        }

        // ── Nodes ─────────────────────────────────────────────────────────
        allNodes.forEach(n => {
            if (n.alpha < 0.02) return;
            const [sx,sy] = w2s(n.x,n.y);
            const isHov = hoverId===n.id;
            const isSel = n.id===selectedDim || n.id===selectedSub;
            const nr    = n.r * camZ * (isHov||isSel ? 1.2 : 1);
            ctx.globalAlpha = n.alpha;

            // Glow for selected/hovered
            if (isHov||isSel) {
                const g = ctx.createRadialGradient(sx,sy,nr*0.2,sx,sy,nr*3.2);
                g.addColorStop(0, n.color+'55'); g.addColorStop(1,'transparent');
                ctx.fillStyle=g; ctx.beginPath(); ctx.arc(sx,sy,nr*3.2,0,Math.PI*2); ctx.fill();
            }

            // Circle fill
            ctx.beginPath(); ctx.arc(sx,sy,nr,0,Math.PI*2);
            if (n.type==='root') {
                const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,nr);
                g2.addColorStop(0,'#93c5fd'); g2.addColorStop(1,'#1d4ed8');
                ctx.fillStyle=g2;
            } else {
                ctx.fillStyle = n.color + (isSel?'ff':isHov?'dd':'88');
            }
            ctx.fill();
            ctx.strokeStyle = isSel ? '#fff' : (isHov ? n.color : '#1e293b');
            ctx.lineWidth   = (isSel ? 2.5 : 1.5) * Math.min(1.5,camZ);
            ctx.stroke();

            // Inner label
            const isCen = (mode==='dimfocus' && n.id===selectedDim);
            const fscale = Math.max(0.55, Math.min(1.8, camZ));
            const fs = Math.round((n.type==='root'?12 : isCen?13 : n.type==='dim'?11:9) * fscale);
            ctx.font=`bold ${fs}px system-ui`;
            ctx.fillStyle='#f1f5f9'; ctx.textAlign='center'; ctx.textBaseline='middle';

            if (n.type==='root') {
                ctx.fillText(getASMFRootLabel(),sx,sy-5*Math.min(1.5,camZ));
                ctx.font=`${Math.round(9*fscale)}px system-ui`;
                ctx.fillStyle='#94a3b8'; ctx.fillText('CORE',sx,sy+7*Math.min(1.5,camZ));
            } else if (isCen) {
                // Centered dim: fit full name inside circle — auto-reduce font until it fits
                const maxW = nr * 1.55; // usable chord width inside the circle
                const words = n.name.split(' ');
                // Find most balanced 2-line split
                let cenLines = [n.name];
                if (words.length > 1) {
                    let best = Infinity;
                    for (let wi = 1; wi < words.length; wi++) {
                        const a = words.slice(0, wi).join(' '), b = words.slice(wi).join(' ');
                        const diff = Math.abs(a.length - b.length);
                        if (diff < best) { best = diff; cenLines = [a, b]; }
                    }
                }
                // Shrink font until longest line fits
                let cfs = fs;
                ctx.font = `bold ${cfs}px system-ui`;
                while (cfs > 7 && Math.max(...cenLines.map(l => ctx.measureText(l).width)) > maxW) {
                    cfs--;
                    ctx.font = `bold ${cfs}px system-ui`;
                }
                const clh = cfs * 1.3;
                cenLines.forEach((l, i) => ctx.fillText(l, sx, sy - clh*(cenLines.length-1)/2 + clh*i));
            } else {
                ctx.fillText(n.type==='subdim' ? n.id.replace(n.parentId+'__','') : n.id, sx, sy);
            }

            // Name label outside (dims) — skip for centered node (labeled inside); wrap long names into 2 lines
            if (n.type==='dim' && n.alpha > 0.35 && !isCen) {
                const ang2    = Math.atan2(sy-ocy, sx-ocx);
                const nameOff = nr + 22; // push well clear of the node edge
                const lx=sx+Math.cos(ang2)*nameOff, ly=sy+Math.sin(ang2)*nameOff;
                const nfs = Math.round(9*Math.max(0.5,Math.min(1.5,camZ)));
                ctx.font=`${nfs}px system-ui`;
                ctx.textAlign = lx>sx+3?'left':lx<sx-3?'right':'center';
                ctx.textBaseline='middle';
                // Split name into at most 2 lines at nearest space to midpoint
                const nameFull = n.name;
                const mid = Math.floor(nameFull.length/2);
                const spaceLeft  = nameFull.lastIndexOf(' ', mid);
                const spaceRight = nameFull.indexOf(' ', mid);
                let line1=nameFull, line2=null;
                if(nameFull.length > 14) {
                    const splitAt = (spaceLeft>-1&&spaceRight>-1) ? (Math.abs(spaceLeft-mid)<Math.abs(spaceRight-mid)?spaceLeft:spaceRight) : (spaceLeft>-1?spaceLeft:spaceRight);
                    if(splitAt>-1){line1=nameFull.slice(0,splitAt);line2=nameFull.slice(splitAt+1);}
                }
                const lh = nfs*1.3;
                const lines = line2 ? [line1, line2] : [line1];
                // Draw dark pill background for readability
                const maxW = Math.max(...lines.map(l=>ctx.measureText(l).width));
                const totalH = lines.length * lh;
                const padX=5, padY=3;
                const bgX = ctx.textAlign==='left'?lx-padX : ctx.textAlign==='right'?lx-maxW-padX : lx-maxW/2-padX;
                ctx.fillStyle='#0a0f1acc';
                ctx.beginPath();
                if(ctx.roundRect) ctx.roundRect(bgX, ly-totalH/2-padY, maxW+padX*2, totalH+padY*2, 3);
                else ctx.rect(bgX, ly-totalH/2-padY, maxW+padX*2, totalH+padY*2);
                ctx.fill();
                ctx.fillStyle = n.color + 'ee';
                lines.forEach((l,i)=>ctx.fillText(l, lx, ly - totalH/2 + lh*(i+0.5)));
            }

            ctx.globalAlpha=1; ctx.textBaseline='alphabetic'; ctx.textAlign='center';
        });

        raf = requestAnimationFrame(draw);
    }

    // ── Event listeners ───────────────────────────────────────────────────
    canvas.addEventListener('mousedown', e => {
        dragging=true; dragSX=e.clientX; dragSY=e.clientY;
        camSX=camX; camSY=camY; canvas.style.cursor='grabbing';
    });
    canvas.addEventListener('mousemove', e => {
        if (dragging) {
            tX=camSX+(e.clientX-dragSX)/camZ;
            tY=camSY+(e.clientY-dragSY)/camZ;
        } else {
            const rect=canvas.getBoundingClientRect();
            const hit=hitNode(e.clientX-rect.left, e.clientY-rect.top);
            const nid=hit?hit.id:null;
            if (nid !== hoverId) {
                hoverId=nid;
                canvas.style.cursor = hit?'pointer':'grab';
                // Update side panel on hover in dim-focus mode
                if (mode==='dimfocus' && selectedDim && !selectedSub) {
                    if (hit && hit.type==='dim' && hit.id!==selectedDim) {
                        renderDimPanel(selectedDim, hit.id);
                    } else if (!hit || hit.id===selectedDim || hit.type==='subdim') {
                        renderDimPanel(selectedDim, null);
                    }
                }
            }
        }
    });
    canvas.addEventListener('mouseup', e => {
        const moved = Math.abs(e.clientX-dragSX)>5 || Math.abs(e.clientY-dragSY)>5;
        dragging=false; canvas.style.cursor='grab';
        if (moved) return;
        const rect=canvas.getBoundingClientRect();
        const hit=hitNode(e.clientX-rect.left, e.clientY-rect.top);
        if (!hit || hit.type==='root') { enterOverview(); return; }
        if (hit.type==='dim') { enterDimFocus(hit.id); return; }
        if (hit.type==='subdim') {
            selectedSub=hit.id;
            const sn=allNodes.find(n=>n.id===hit.id);
            if (sn) renderSubPanel(sn);
        }
    });
    canvas.addEventListener('mouseleave', () => {
        dragging=false; canvas.style.cursor='grab'; hoverId=null;
        if (mode==='dimfocus' && selectedDim && !selectedSub) renderDimPanel(selectedDim, null);
    });
    canvas.addEventListener('wheel', e => {
        e.preventDefault();
        tZ=Math.min(4.5,Math.max(0.3,tZ*(e.deltaY<0?1.13:0.88)));
    }, {passive:false});

    // ── Init ──────────────────────────────────────────────────────────────
    setLayout('overview', null);
    renderOverviewPanel();
    raf = requestAnimationFrame(draw);

    const ro = new ResizeObserver(() => { canvas.width=canvas.offsetWidth||700; canvas.height=canvas.offsetHeight||600; });
    ro.observe(canvas);

    // ── Cleanup ───────────────────────────────────────────────────────────
    const graphPanel  = document.getElementById('report-panel-asmf-graph');
    const orbitalPane = document.getElementById('asmf-graph-pane-orbital');
    function stopOrbital() { cancelAnimationFrame(raf); ro.disconnect(); obs.disconnect(); if(paneObs)paneObs.disconnect(); }
    const obs = new MutationObserver(() => { if (!graphPanel?.classList.contains('active')) stopOrbital(); });
    if (graphPanel) obs.observe(graphPanel,{attributes:true,attributeFilter:['class']});
    let paneObs=null;
    if (orbitalPane) {
        paneObs=new MutationObserver(()=>{ if(!orbitalPane.classList.contains('active')) stopOrbital(); });
        paneObs.observe(orbitalPane,{attributes:true,attributeFilter:['class']});
    }
}

// ── ASMF Matrix Report ───────────────────────────────────────────────────────

async function populateASMFMatrix() {
    const el = document.getElementById('asmf-matrix-content');
    if (!el) return;
    el.innerHTML = '<div style="color:var(--text-muted);padding:24px;">Loading framework…</div>';
    try {
        if (!_asmfFramework) {
            const resp = await fetch('/api/asmf-framework');
            _asmfFramework = await resp.json();
        }
        el.innerHTML = _asmfBuildMatrix(_asmfFramework);
        _asmfBindTooltips(el);
    } catch (e) {
        el.innerHTML = `<div style="color:#ef4444;padding:24px;">Error: ${escapeHtml(String(e))}</div>`;
    }
}

function _asmfCellBg(stageIdx, opacity = 0.28) {
    const hex = ASMF_STAGE_COLORS[Math.min(5, Math.max(0, stageIdx))];
    // Convert hex to rgba
    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    return `rgba(${r},${g},${b},${opacity})`;
}

function _asmfBuildMatrix(fw) {
    const dims = fw.dimensions || {};
    const stages = fw.maturity_stages || {};
    const principles = fw.principles || [];
    const journey = (fw.transformation_journey && fw.transformation_journey.phases) ? fw.transformation_journey.phases : (Array.isArray(fw.transformation_journey) ? fw.transformation_journey : []);
    const stageKeys = ['0','1','2','3','4','5'];

    // ── Stage header row ──
    const stageHeaders = stageKeys.map(sk => {
        const s = stages[sk] || {};
        const color = ASMF_STAGE_COLORS[parseInt(sk)];
        return `
        <th style="padding:10px 8px;min-width:clamp(96px,12vw,148px);text-align:center;border-bottom:3px solid ${color};
                   background:${_asmfCellBg(parseInt(sk), 0.18)};">
          <div style="font-size:20px;font-weight:800;color:${color};">${sk}</div>
          <div style="font-size:11px;font-weight:700;color:${color};text-transform:uppercase;letter-spacing:0.4px;line-height:1.3;">${escapeHtml(s.label || '')}</div>
          <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">${escapeHtml(s.typical_year || '')}</div>
        </th>`;
    }).join('');

    // ── Dimension rows ──
    const PLANE_COLORS = {
        'Sensing & Signal': '#06b6d4',
        'Reasoning & Action': '#8b5cf6',
        'Governance & Trust': '#ef4444',
        'Learning & Knowledge': '#10b981',
        'Human & Org': '#f59e0b',
        'Measurement': '#64748b',
    };

    const dimRows = Object.entries(dims).map(([dimId, dim]) => {
        const weight = Math.round((dim.weight || 0) * 100);
        const planeColor = Object.entries(PLANE_COLORS).find(([k]) => (dim.plane||'').includes(k.split(' ')[0]))?.[1] || '#3b82f6';
        const subDims = dim.sub_dimensions || {};

        // Per sub-dimension: one sub-row per sub-dim (4 sub-rows per dimension)
        const subRows = Object.entries(subDims).map(([sdId, sd], sdIdx) => {
            const cells = stageKeys.map(sk => {
                const desc = (sd.stage_descriptors || {})[sk] || '';
                const short = desc.length > 58 ? desc.substring(0, 55) + '…' : desc;
                const bg = _asmfCellBg(parseInt(sk), 0.15);
                const borderColor = _asmfCellBg(parseInt(sk), 0.4);
                return `
                <td style="padding:6px 8px;font-size:11px;color:var(--text-secondary);background:${bg};
                           border:1px solid ${borderColor};line-height:1.4;cursor:default;vertical-align:top;"
                    data-full="${escapeHtml(desc)}">
                  ${escapeHtml(short)}
                </td>`;
            }).join('');

            // Left label cell (only show dim id on first sub-dim row)
            const isFirst = sdIdx === 0;
            const rowspan = Object.keys(subDims).length;
            const dimCell = isFirst ? `
                <td rowspan="${rowspan}" style="padding:10px 8px;vertical-align:top;border-right:3px solid ${planeColor};
                            background:var(--bg-secondary);width:clamp(76px,8vw,100px);min-width:76px;max-width:110px;">
                  <div style="font-size:13px;font-weight:800;color:${planeColor};">${escapeHtml(dimId)}</div>
                  <div style="font-size:11px;color:var(--text-primary);font-weight:600;line-height:1.3;margin-top:2px;white-space:normal;word-break:break-word;">${escapeHtml(dim.name||'')}</div>
                  <div style="font-size:10px;color:var(--text-muted);margin-top:4px;display:inline-block;
                              background:${planeColor}22;padding:1px 5px;border-radius:8px;">${weight}% <span style='opacity:0.6;font-size:9px;'>wt</span></div>
                </td>` : '';

            const sdColor = planeColor;
            return `
            <tr style="border-bottom:1px solid var(--border-color);">
              ${dimCell}
              <td style="padding:5px 8px;font-size:11px;color:${sdColor};font-weight:600;width:clamp(110px,12vw,150px);min-width:100px;max-width:160px;
                         background:var(--bg-secondary);border-right:1px solid var(--border-color);">
                <span>
                  ${escapeHtml(sdId)}<br>
                  <span style="font-weight:400;color:var(--text-muted);font-size:10px;word-break:break-word;">${escapeHtml(sd.name||'')}</span>
                </span>
              </td>
              ${cells}
            </tr>`;
        }).join('');

        // Dim separator row
        return subRows + `<tr style="height:4px;background:var(--bg-primary);"><td colspan="8"></td></tr>`;
    }).join('');

    // ── Principles grid ──
    const principleCards = principles.map(p => `
    <div style="background:var(--bg-secondary);border:1px solid var(--border-color);border-left:3px solid #3b82f6;
                border-radius:6px;padding:12px 14px;flex:1;min-width:220px;">
      <div style="font-size:11px;font-weight:700;color:#3b82f6;margin-bottom:4px;">${escapeHtml(p.id||'')} — ${escapeHtml(p.label||'')}</div>
      <div style="font-size:12px;color:var(--text-secondary);line-height:1.5;">${escapeHtml(p.statement||'')}</div>
    </div>`).join('');

    // ── Journey arc ──
    const journeySteps = journey.map((phase, i) => {
        const color = ASMF_STAGE_COLORS[i + 1] || '#64748b';
        const acts = (phase.key_activities||[]).slice(0,3);
        const fails = (phase.failure_modes||[]).slice(0,2);
        return `
        <div style="flex:1;min-width:160px;background:var(--bg-secondary);border:1px solid var(--border-color);
                    border-top:3px solid ${color};border-radius:6px;padding:12px 14px;position:relative;">
          <div style="font-size:12px;font-weight:700;color:${color};margin-bottom:6px;">${escapeHtml(phase.transition||'')}</div>
          <ul style="margin:0 0 8px;padding-left:14px;">
            ${acts.map(a=>`<li style="font-size:11px;color:var(--text-secondary);padding:1px 0;">${escapeHtml(a)}</li>`).join('')}
          </ul>
          ${fails.length ? `<div style="font-size:10px;color:#ef4444;margin-top:4px;">⚠ ${escapeHtml(fails[0])}</div>` : ''}
        </div>`;
    }).join('');

    // ── Plane legend ──
    const planeLegend = Object.entries(PLANE_COLORS).map(([label, color]) =>
        `<span style="display:inline-flex;align-items:center;gap:5px;margin-right:12px;">
           <span style="width:10px;height:10px;border-radius:50%;background:${color};display:inline-block;"></span>
           <span style="font-size:11px;color:var(--text-muted);">${label}</span>
         </span>`
    ).join('');

    return `
    <!-- Framework intro -->
    <div style="margin-bottom:24px;">
      <p style="font-size:13px;color:var(--text-secondary);line-height:1.6;max-width:800px;">${escapeHtml(fw.description||'')}</p>
      <div style="margin-top:10px;">${planeLegend}</div>
    </div>

    <!-- THE MATRIX -->
    <div style="overflow-x:auto;margin-bottom:32px;width:100%;">
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">
        Hover any cell to read the full stage descriptor. Each row = one sub-dimension across 6 adoption stages.
      </div>
    <table style="border-collapse:collapse;width:100%;min-width:100%;table-layout:auto;">
        <thead>
          <tr>
            <th style="padding:10px 8px;text-align:left;background:var(--bg-secondary);border-right:3px solid var(--border-color);min-width:76px;">
              <span style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.5px;">Dimension</span>
            </th>
            <th style="padding:10px 8px;text-align:left;background:var(--bg-secondary);border-right:1px solid var(--border-color);min-width:100px;">
              <span style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.5px;">Sub-Dimension</span>
            </th>
            ${stageHeaders}
          </tr>
        </thead>
        <tbody>${dimRows}</tbody>
      </table>
    </div>

    <!-- Transformation Journey -->
    <div style="margin-bottom:28px;">
      <h3 style="font-size:15px;font-weight:700;color:var(--text-primary);margin:0 0 12px;border-bottom:1px solid var(--border-color);padding-bottom:8px;">Transformation Journey</h3>
      <div style="display:flex;gap:10px;flex-wrap:wrap;">${journeySteps}</div>
    </div>

    <!-- Governing Principles -->
    <div style="margin-bottom:16px;">
      <h3 style="font-size:15px;font-weight:700;color:var(--text-primary);margin:0 0 12px;border-bottom:1px solid var(--border-color);padding-bottom:8px;">Governing Principles</h3>
      <div style="display:flex;flex-wrap:wrap;gap:10px;">${principleCards}</div>
    </div>

    <!-- Tooltip overlay (hidden by default) -->
    <div id="asmf-tooltip" style="display:none;position:fixed;z-index:9999;background:#0f172a;border:1px solid #334155;
         border-radius:8px;padding:12px 16px;max-width:360px;font-size:12px;color:#e2e8f0;line-height:1.6;
         box-shadow:0 8px 32px rgba(0,0,0,0.5);pointer-events:none;"></div>`;
}

function _asmfBindTooltips(container) {
    const tooltip = document.getElementById('asmf-tooltip');
    if (!tooltip) return;
    container.querySelectorAll('td[data-full]').forEach(cell => {
        cell.addEventListener('mouseenter', (e) => {
            const text = cell.dataset.full;
            if (!text) return;
            tooltip.textContent = text;
            tooltip.style.display = 'block';
        });
        cell.addEventListener('mousemove', (e) => {
            let left = e.clientX + 16;
            let top = e.clientY + 10;
            const w = tooltip.offsetWidth, h = tooltip.offsetHeight;
            if (left + w > window.innerWidth - 8) left = e.clientX - w - 12;
            if (top + h > window.innerHeight - 8) top = e.clientY - h - 12;
            tooltip.style.left = left + 'px';
            tooltip.style.top = top + 'px';
        });
        cell.addEventListener('mouseleave', () => {
            tooltip.style.display = 'none';
        });
    });
}

function exportASMFOrbitalAsHTML(fw, orbMap) {
    const fwJson  = JSON.stringify(fw).replace(/<\/script>/gi, '<\\/script>');
    const mapJson = JSON.stringify(orbMap).replace(/<\/script>/gi, '<\\/script>');
    const stageColors = JSON.stringify(ASMF_STAGE_COLORS);
    const stageLabels = JSON.stringify(ASMF_STAGE_LABELS);
    const ts = new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
    const fwAbbr = fw.framework_abbrev || 'ASMF';
    const fwName = fw.framework_name || 'Agentic Adoption Framework';
    const orbitalTitle = `${fwAbbr} Integration Map`;

    const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${fwAbbr} Integration Map — ${fwName}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100vh;width:100vw;overflow:hidden;background:#0a0f1a;font-family:'Segoe UI',system-ui,-apple-system,BlinkMacSystemFont,sans-serif;color:#94a3b8}
@supports(height:100dvh){html,body{height:100dvh}}
#app{display:flex;flex-direction:column;height:100%;width:100%}
#topbar{display:flex;align-items:center;gap:16px;padding:10px 20px;background:#0f172a;border-bottom:1px solid #1e293b;flex-shrink:0;}
#topbar h1{font-size:14px;font-weight:700;color:#f1f5f9;letter-spacing:0.3px}
#topbar .sub{font-size:11px;color:#475569;margin-left:auto}
#main{display:flex;flex:1 1 auto;min-height:0;min-width:0;width:100%}
#canvas-wrap{flex:1 1 auto;min-width:0;min-height:0;position:relative;overflow:hidden}
canvas{position:absolute;top:0;left:0;width:100%;height:100%;cursor:grab;display:block}
#panel{width:clamp(280px,28vw,420px);flex:0 1 clamp(280px,28vw,420px);min-width:min(280px,38vw);max-width:min(420px,42vw);background:#0f172a;border-left:1px solid #1e293b;display:flex;flex-direction:column;overflow:hidden}
#panel-hdr{padding:14px 18px 12px;border-bottom:1px solid #1e293b;flex-shrink:0}
#panel-hdr .row{display:flex;align-items:center;justify-content:space-between;gap:8px}
#panel-hdr .title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#475569}
#back-btn{display:none;background:#1e293b;border:1px solid #334155;color:#94a3b8;font-size:11px;padding:3px 10px;border-radius:4px;cursor:pointer}
#crumb{font-size:12px;color:#64748b;margin-top:5px}
#body{flex:1;overflow-y:auto;padding:16px 18px;font-size:12px}
@media(max-width:900px){#main{flex-direction:column}#panel{width:100%;max-width:none;min-width:0;flex:0 0 min(42%,360px);border-left:0;border-top:1px solid #1e293b}}
</style>
</head>
<body>
<div id="app">
  <div id="topbar">
    <h1>${fwAbbr} — ${fwName} Integration Map</h1>
    <span class="sub">Exported ${ts}</span>
  </div>
  <div id="main">
    <div id="canvas-wrap"><canvas id="canvas"></canvas></div>
    <div id="panel">
      <div id="panel-hdr">
        <div class="row">
          <div class="title">${orbitalTitle}</div>
          <button id="back-btn">← All</button>
        </div>
        <div id="crumb">All 11 Dimensions</div>
      </div>
      <div id="body"></div>
    </div>
  </div>
</div>
<script>
const FW      = ${fwJson};
const ORBMAP  = ${mapJson};
const STAGE_COLORS = ${stageColors};
const STAGE_LABELS = ${stageLabels};

// ── helpers ───────────────────────────────────────────────────────────────
function esc(s){const d=document.createElement('div');d.textContent=String(s??'');return d.innerHTML;}

const dims      = Object.entries(FW.dimensions||{});
const rels      = ORBMAP.relationships||[];
const relTypes  = ORBMAP.relationship_types||{};
const dimCfg    = ORBMAP.dim_config||{};

const OV_RING_R  = 215;
const FO_INNER_R = 125;
const FO_OUTER_R = 285;

const allNodes = [];
function mkNode(o){return Object.assign({tx:0,ty:0,alpha:1,talpha:1,tr:20,r:4},o);}

allNodes.push(mkNode({id:'__root__',type:'root',label:${JSON.stringify(fwAbbr)},x:0,y:0,tx:0,ty:0,r:34,tr:34,color:'#3b82f6'}));
const dimCount=dims.length;
dims.forEach(([id,dim],i)=>{
    const cfg=dimCfg[id]||{};
    const color=cfg.color||'#3b82f6';
    const a=(2*Math.PI*i/dimCount)-Math.PI/2;
    const ox=OV_RING_R*Math.cos(a),oy=OV_RING_R*Math.sin(a);
    allNodes.push(mkNode({id,type:'dim',label:id,name:dim.name||id,color,plane:cfg.plane||'',overviewAngle:a,overviewX:ox,overviewY:oy,x:ox,y:oy,tx:ox,ty:oy,r:24,tr:24,alpha:1,talpha:1,dim}));
});
dims.forEach(([dimId,dim])=>{
    const parent=allNodes.find(n=>n.id===dimId);
    const subArr=Object.entries(dim.sub_dimensions||{});
    subArr.forEach(([sdId,sd],si)=>{
        allNodes.push(mkNode({id:dimId+'__'+sdId,type:'subdim',parentId:dimId,label:sdId,name:sd.name||sdId,color:parent.color,x:parent.x,y:parent.y,tx:parent.x,ty:parent.y,r:4,tr:4,alpha:0,talpha:0,sd,parentNode:parent,subIdx:si,subCount:subArr.length}));
    });
});

let mode='overview',selectedDim=null,selectedSub=null,hoverId=null;
let camX=0,camY=0,camZ=1,tX=0,tY=0,tZ=1;
let dragging=false,dragSX=0,dragSY=0,camSX=0,camSY=0;

const canvas=document.getElementById('canvas');
const detBody=document.getElementById('body');
const crumb=document.getElementById('crumb');
const backBtn=document.getElementById('back-btn');
backBtn.addEventListener('click',()=>enterOverview());

function resizeCanvas(){
    const wrap=canvas.parentElement;
    const r=wrap?wrap.getBoundingClientRect():{width:0,height:0};
    const w=Math.max(1,Math.floor(r.width||window.innerWidth||800));
    const h=Math.max(1,Math.floor(r.height||window.innerHeight||600));
    canvas.width=w;
    canvas.height=h;
    canvas.style.width=w+'px';
    canvas.style.height=h+'px';
}
resizeCanvas();
// Re-measure once layout settles (Safari/iOS file:// race where flex children compute to 0)
requestAnimationFrame(function(){requestAnimationFrame(resizeCanvas);});
window.addEventListener('load',resizeCanvas);
window.addEventListener('resize',resizeCanvas);
window.addEventListener('orientationchange',resizeCanvas);
if(typeof ResizeObserver!=='undefined'){try{new ResizeObserver(resizeCanvas).observe(canvas.parentElement);}catch(e){}}

function setLayout(newMode,selId){
    mode=newMode;
    if(newMode==='overview'){
        allNodes.find(n=>n.id==='__root__').tx=0; allNodes.find(n=>n.id==='__root__').ty=0;
        allNodes.find(n=>n.id==='__root__').tr=34; allNodes.find(n=>n.id==='__root__').talpha=1;
        allNodes.filter(n=>n.type==='dim').forEach(n=>{n.tx=n.overviewX;n.ty=n.overviewY;n.tr=24;n.talpha=1;});
        allNodes.filter(n=>n.type==='subdim').forEach(n=>{n.tx=n.parentNode.overviewX;n.ty=n.parentNode.overviewY;n.tr=4;n.talpha=0;});
        tX=0;tY=0;tZ=1;
    } else if(newMode==='dimfocus'){
        const focDim=allNodes.find(n=>n.id===selId);
        focDim.tx=0;focDim.ty=0;focDim.tr=44;focDim.talpha=1;
        const root=allNodes.find(n=>n.id==='__root__');
        root.tx=-310;root.ty=-200;root.tr=18;root.talpha=0.3;
        const otherDims=allNodes.filter(n=>n.type==='dim'&&n.id!==selId);
        otherDims.forEach((n,i)=>{const a=(2*Math.PI*i/otherDims.length)-Math.PI/2;n.tx=FO_OUTER_R*Math.cos(a);n.ty=FO_OUTER_R*Math.sin(a);n.tr=20;n.talpha=1;});
        const mySubs=allNodes.filter(n=>n.type==='subdim'&&n.parentId===selId);
        mySubs.forEach((n,i)=>{const a=(2*Math.PI*i/mySubs.length)-Math.PI/2;n.tx=FO_INNER_R*Math.cos(a);n.ty=FO_INNER_R*Math.sin(a);n.tr=17;n.talpha=1;});
        allNodes.filter(n=>n.type==='subdim'&&n.parentId!==selId).forEach(n=>{const p=otherDims.find(d=>d.id===n.parentId);if(p){n.tx=p.tx;n.ty=p.ty;}n.tr=4;n.talpha=0;});
        tX=0;tY=0;tZ=1;
    }
}

function renderOverviewPanel(){
    crumb.textContent='All '+dims.length+' Dimensions';
    backBtn.style.display='none';
    const typeHtml=Object.entries(relTypes).map(([k,v])=>'<div style="display:flex;align-items:center;gap:9px;margin-bottom:8px;"><span style="width:24px;height:3px;background:'+v.color+';border-radius:2px;flex-shrink:0;display:inline-block;"></span><span>'+esc(v.label)+'</span></div>').join('');
    detBody.innerHTML='<p style="line-height:1.75;margin-bottom:16px;color:#94a3b8;">This map shows how all '+dims.length+' '+esc(FW.framework_abbrev||'ASMF')+' dimensions integrate to form a fully agentic operating model. <strong style="color:#f1f5f9;">Click any dimension</strong> to bring it to center and reveal every integration link, sub-dimension and capability flow.</p><div style="border-top:1px solid #1e293b;padding-top:14px;margin-bottom:14px;"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Relationship Types</div>'+typeHtml+'</div><div style="border-top:1px solid #1e293b;padding-top:14px;"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:8px;">Controls</div><div style="line-height:2.1;color:#64748b;">🖱 Click dim — focus &amp; see all links<br>🖱 Hover outer dim — see relationship<br>🖱 Click outer dim — shift focus<br>🖱 Click sub-dim — stage descriptors<br>🖱 Scroll — zoom · Drag — pan<br>🖱 Click background or ← All — reset</div></div>';
}

function renderDimPanel(dimId,hoverOtherId){
    const dn=allNodes.find(n=>n.id===dimId);if(!dn)return;
    const weight=Math.round((dn.dim.weight||0)*100);
    const outRels=rels.filter(r=>r.from===dimId);
    const inRels=rels.filter(r=>r.to===dimId);
    if(hoverOtherId){
        const on=allNodes.find(n=>n.id===hoverOtherId);if(!on)return;
        const mutual=[...outRels.filter(r=>r.to===hoverOtherId),...inRels.filter(r=>r.from===hoverOtherId)];
        const relHtml=mutual.length?mutual.map(r=>{const rt=relTypes[r.type]||{color:'#94a3b8',label:r.type};const dir=r.from===dimId?dimId+' → '+r.to:r.from+' → '+dimId;return'<div style="margin-bottom:10px;padding:10px 12px;background:#1e293b;border-radius:6px;border-left:3px solid '+rt.color+'"><div style="font-size:10px;font-weight:700;color:'+rt.color+';text-transform:uppercase;margin-bottom:5px;">'+esc(rt.label)+' · '+esc(dir)+'</div><div style="line-height:1.6;color:#cbd5e1;">'+esc(r.label)+'</div></div>';}).join(''):'<div style="color:#475569;font-style:italic;padding:8px 0;">No direct relationship defined.</div>';
        detBody.innerHTML='<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><span style="width:11px;height:11px;border-radius:50%;background:'+on.color+';flex-shrink:0;display:inline-block;"></span><span style="font-size:16px;font-weight:700;color:#f1f5f9;">'+esc(hoverOtherId)+'</span><span style="font-size:10px;color:#475569;margin-left:auto;">'+esc(on.plane||'')+'</span></div><div style="font-size:12px;color:#94a3b8;margin-bottom:14px;">'+esc(on.name)+'</div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Relationship with '+esc(dimId)+'</div>'+relHtml+'<div style="margin-top:12px;font-size:11px;color:#475569;">Click to shift focus to '+esc(hoverOtherId)+'</div>';
        return;
    }
    const subHtml=allNodes.filter(n=>n.type==='subdim'&&n.parentId===dimId).map(sn=>'<div style="margin-bottom:7px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid '+dn.color+';cursor:pointer;" data-subdim="'+esc(sn.id)+'"><div style="font-size:11px;font-weight:700;color:'+dn.color+';">'+esc(sn.id.replace(dimId+'__',''))+'</div><div style="font-size:11px;color:#cbd5e1;margin-top:2px;">'+esc(sn.name)+'</div></div>').join('');
    const allDimRels=[...outRels.map(r=>({dir:'→',other:r.to,r,rt:relTypes[r.type]||{color:'#94a3b8',label:r.type}})),...inRels.map(r=>({dir:'←',other:r.from,r,rt:relTypes[r.type]||{color:'#94a3b8',label:r.type}}))].sort((a,b)=>a.other.localeCompare(b.other));
    const relHtml=allDimRels.map(({dir,other,r,rt})=>{const on=allNodes.find(n=>n.id===other);return'<div style="margin-bottom:7px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid '+rt.color+'"><div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;"><span style="font-size:11px;font-weight:700;color:'+rt.color+';">'+dir+'</span><span style="font-size:11px;font-weight:700;color:'+(on?on.color:'#94a3b8')+';">'+esc(other)+'</span><span style="font-size:10px;color:#475569;margin-left:auto;">'+esc(rt.label)+'</span></div><div style="font-size:11px;color:#94a3b8;line-height:1.5;">'+esc(r.label)+'</div></div>';}).join('');
    detBody.innerHTML='<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;"><span style="width:12px;height:12px;border-radius:50%;background:'+dn.color+';flex-shrink:0;display:inline-block;"></span><span style="font-size:18px;font-weight:700;color:#f1f5f9;">'+esc(dimId)+'</span></div><div style="font-size:12px;color:#94a3b8;margin-bottom:2px;">'+esc(dn.name)+'</div><div style="font-size:10px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:14px;">'+esc(dn.plane)+' · Weight: '+weight+'%</div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:8px;">Sub-Dimensions</div>'+subHtml+'<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:6px;margin-top:16px;">Integration Links <span style="color:#334155;font-weight:400;">'+allDimRels.length+' connections</span></div><div style="font-size:11px;color:#475569;margin-bottom:10px;">Hover outer nodes to inspect each relationship.</div>'+relHtml;
    detBody.querySelectorAll('[data-subdim]').forEach(el2=>{el2.addEventListener('click',()=>{const sn=allNodes.find(n=>n.id===el2.dataset.subdim);if(sn){selectedSub=sn.id;renderSubPanel(sn);}});});
}

function renderSubPanel(sn){
    const sdLabel=sn.id.replace(sn.parentId+'__','');
    const stagesHtml=['0','1','2','3','4','5'].map(sk=>{const text=(sn.sd.stage_descriptors||{})[sk]||'—';const color=STAGE_COLORS[+sk];const lbl=STAGE_LABELS[+sk];return'<div style="margin-bottom:8px;padding:8px 10px;background:#1e293b;border-radius:6px;border-left:3px solid '+color+'"><div style="font-size:10px;font-weight:700;color:'+color+';text-transform:uppercase;letter-spacing:0.5px;margin-bottom:3px;">Stage '+sk+' — '+esc(lbl)+'</div><div style="font-size:11px;color:#cbd5e1;line-height:1.55;">'+esc(text)+'</div></div>';}).join('');
    crumb.textContent=selectedDim+' › '+sdLabel;
    detBody.innerHTML='<div style="font-size:10px;color:#475569;margin-bottom:6px;">↑ '+esc(sn.parentId)+'</div><div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;"><span style="width:10px;height:10px;border-radius:50%;background:'+sn.color+';flex-shrink:0;display:inline-block;"></span><span style="font-size:15px;font-weight:700;color:#f1f5f9;">'+esc(sdLabel)+'</span></div><div style="font-size:12px;color:#94a3b8;margin-bottom:14px;">'+esc(sn.name)+'</div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#475569;margin-bottom:10px;">Maturity Stage Descriptors</div>'+stagesHtml+'<div style="margin-top:14px;"><button id="back-to-dim" style="background:#1e293b;border:1px solid #334155;color:#94a3b8;font-size:11px;padding:5px 12px;border-radius:4px;cursor:pointer;">← Back to '+esc(sn.parentId)+'</button></div>';
    document.getElementById('back-to-dim')?.addEventListener('click',()=>{selectedSub=null;crumb.textContent=selectedDim;renderDimPanel(selectedDim,null);});
}

function enterOverview(){selectedDim=null;selectedSub=null;setLayout('overview',null);renderOverviewPanel();}
function enterDimFocus(dimId){
    selectedDim=dimId;selectedSub=null;
    setLayout('dimfocus',dimId);
    const dn=allNodes.find(n=>n.id===dimId);
    crumb.textContent=dimId+' — '+(dn?.name||'');
    backBtn.style.display='block';
    renderDimPanel(dimId,null);
}

function w2s(wx,wy){return[canvas.width/2+(wx+camX)*camZ,canvas.height/2+(wy+camY)*camZ];}
function s2w(sx,sy){return[(sx-canvas.width/2)/camZ-camX,(sy-canvas.height/2)/camZ-camY];}
function hitNode(sx,sy){
    const[wx,wy]=s2w(sx,sy);
    const candidates=allNodes.filter(n=>{if(n.alpha<0.15)return false;if(n.type==='subdim'&&n.parentId!==selectedDim)return false;return true;});
    for(let i=candidates.length-1;i>=0;i--){const n=candidates[i];const dx=n.x-wx,dy=n.y-wy;if(dx*dx+dy*dy<=(n.r+5)*(n.r+5))return n;}
    return null;
}

function drawArrow(ctx,fx,fy,fr,tx2,ty2,tr2,color,lw,dash){
    const dx=tx2-fx,dy=ty2-fy,len=Math.sqrt(dx*dx+dy*dy);
    if(len<fr+tr2+8)return;
    const ux=dx/len,uy=dy/len;
    const sx=fx+ux*(fr+2),sy=fy+uy*(fr+2),ex=tx2-ux*(tr2+2),ey=ty2-uy*(tr2+2);
    ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ex,ey);
    ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.setLineDash(dash||[]);ctx.stroke();ctx.setLineDash([]);
    const hs=Math.max(5,7*camZ);
    ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-ux*hs+uy*hs*0.45,ey-uy*hs-ux*hs*0.45);ctx.lineTo(ex-ux*hs-uy*hs*0.45,ey-uy*hs+ux*hs*0.45);ctx.closePath();ctx.fillStyle=color;ctx.fill();
}

function toHex(n){return Math.round(n).toString(16).padStart(2,'0');}

function draw(){
    allNodes.forEach(n=>{n.x+=(n.tx-n.x)*0.10;n.y+=(n.ty-n.y)*0.10;n.r+=(n.tr-n.r)*0.12;n.alpha+=(n.talpha-n.alpha)*0.10;});
    camX+=(tX-camX)*0.12;camY+=(tY-camY)*0.12;camZ+=(tZ-camZ)*0.12;
    const W=canvas.width,H=canvas.height;
    const ctx=canvas.getContext('2d');
    ctx.clearRect(0,0,W,H);ctx.fillStyle='#0a0f1a';ctx.fillRect(0,0,W,H);
    for(let i=0;i<120;i++){ctx.globalAlpha=0.06+(i%7)*0.02;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc((i*137.508+11)%W,(i*91.3+17)%H,(i%3)*0.35+0.3,0,Math.PI*2);ctx.fill();}
    ctx.globalAlpha=1;
    const[ocx,ocy]=w2s(0,0);
    ctx.lineWidth=1;
    if(mode==='overview'){ctx.beginPath();ctx.arc(ocx,ocy,OV_RING_R*camZ,0,Math.PI*2);ctx.strokeStyle='#1e293b55';ctx.setLineDash([4,8]);ctx.stroke();ctx.setLineDash([]);}
    else{ctx.beginPath();ctx.arc(ocx,ocy,FO_INNER_R*camZ,0,Math.PI*2);ctx.strokeStyle='#1e293b77';ctx.setLineDash([3,6]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(ocx,ocy,FO_OUTER_R*camZ,0,Math.PI*2);ctx.strokeStyle='#1e293b33';ctx.setLineDash([4,10]);ctx.stroke();ctx.setLineDash([]);}
    if(mode==='dimfocus'&&selectedDim){
        const cenNode=allNodes.find(n=>n.id===selectedDim);
        const[csx,csy]=w2s(cenNode.x,cenNode.y);
        const dimRels=rels.filter(r=>r.from===selectedDim||r.to===selectedDim);
        dimRels.forEach(r=>{
            const othId=r.from===selectedDim?r.to:r.from;
            const oth=allNodes.find(n=>n.id===othId);
            if(!oth||oth.alpha<0.1)return;
            const[osx,osy]=w2s(oth.x,oth.y);
            const rt=relTypes[r.type]||{color:'#94a3b8',dash:[]};
            const isHov=(hoverId===othId);
            const alpha=isHov?0.95:0.5;
            const col=rt.color+toHex(alpha*255);
            const lw=((r.strength||1)*0.7+0.4)*Math.max(0.6,camZ);
            if(r.from===selectedDim)drawArrow(ctx,csx,csy,cenNode.r*camZ,osx,osy,oth.r*camZ,col,lw,rt.dash||[]);
            else drawArrow(ctx,osx,osy,oth.r*camZ,csx,csy,cenNode.r*camZ,col,lw,rt.dash||[]);
            if(camZ>0.5&&!isHov){
                const mx=(csx+osx)/2,my=(csy+osy)/2;
                const abbr=rt.abbr||r.type.slice(0,2).toUpperCase();
                const bfs=Math.max(8,Math.round(8.5*camZ));
                ctx.font='bold '+bfs+'px system-ui';
                const bw=ctx.measureText(abbr).width+6,bh=bfs+4;
                ctx.fillStyle='#0a0f1aee';
                ctx.beginPath();if(ctx.roundRect)ctx.roundRect(mx-bw/2,my-bh/2,bw,bh,3);else ctx.rect(mx-bw/2,my-bh/2,bw,bh);ctx.fill();
                ctx.fillStyle=rt.color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(abbr,mx,my);ctx.textBaseline='alphabetic';
            }
        });
        allNodes.filter(n=>n.type==='subdim'&&n.parentId===selectedDim&&n.alpha>0.05).forEach(sn=>{
            const[sx2,sy2]=w2s(sn.x,sn.y);
            ctx.beginPath();ctx.moveTo(csx,csy);ctx.lineTo(sx2,sy2);ctx.strokeStyle=sn.color+'44';ctx.lineWidth=1.5;ctx.setLineDash([3,5]);ctx.stroke();ctx.setLineDash([]);
        });
    }
    allNodes.forEach(n=>{
        if(n.alpha<0.02)return;
        const[sx,sy]=w2s(n.x,n.y);
        const isHov=hoverId===n.id,isSel=n.id===selectedDim||n.id===selectedSub;
        const nr=n.r*camZ*(isHov||isSel?1.2:1);
        ctx.globalAlpha=n.alpha;
        if(isHov||isSel){const g=ctx.createRadialGradient(sx,sy,nr*0.2,sx,sy,nr*3.2);g.addColorStop(0,n.color+'55');g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.beginPath();ctx.arc(sx,sy,nr*3.2,0,Math.PI*2);ctx.fill();}
        ctx.beginPath();ctx.arc(sx,sy,nr,0,Math.PI*2);
        if(n.type==='root'){const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,nr);g2.addColorStop(0,'#93c5fd');g2.addColorStop(1,'#1d4ed8');ctx.fillStyle=g2;}
        else ctx.fillStyle=n.color+(isSel?'ff':isHov?'dd':'88');
        ctx.fill();
        ctx.strokeStyle=isSel?'#fff':(isHov?n.color:'#1e293b');ctx.lineWidth=(isSel?2.5:1.5)*Math.min(1.5,camZ);ctx.stroke();
        const isCen=(mode==='dimfocus'&&n.id===selectedDim);
        const fscale=Math.max(0.55,Math.min(1.8,camZ));
        const fs=Math.round((n.type==='root'?12:isCen?13:n.type==='dim'?11:9)*fscale);
        ctx.font='bold '+fs+'px system-ui';ctx.fillStyle='#f1f5f9';ctx.textAlign='center';ctx.textBaseline='middle';
        if(n.type==='root'){ctx.fillText(${JSON.stringify(fwAbbr)},sx,sy-5*Math.min(1.5,camZ));ctx.font=Math.round(9*fscale)+'px system-ui';ctx.fillStyle='#94a3b8';ctx.fillText('CORE',sx,sy+7*Math.min(1.5,camZ));}
        else if(isCen){
            const _mw=nr*1.55,_ws=n.name.split(' ');
            let _cl=[n.name];
            if(_ws.length>1){let _bf=Infinity;for(let _wi=1;_wi<_ws.length;_wi++){const _a=_ws.slice(0,_wi).join(' '),_b=_ws.slice(_wi).join(' '),_d=Math.abs(_a.length-_b.length);if(_d<_bf){_bf=_d;_cl=[_a,_b];}}}
            let _cfs=fs;ctx.font='bold '+_cfs+'px system-ui';
            while(_cfs>7&&Math.max(..._cl.map(l=>ctx.measureText(l).width))>_mw){_cfs--;ctx.font='bold '+_cfs+'px system-ui';}
            const _clh=_cfs*1.3;_cl.forEach((_l,_i)=>ctx.fillText(_l,sx,sy-_clh*(_cl.length-1)/2+_clh*_i));
        }
        else ctx.fillText(n.type==='subdim'?n.id.replace(n.parentId+'__',''):n.id,sx,sy);
        if(n.type==='dim'&&n.alpha>0.35&&!(mode==='dimfocus'&&n.id===selectedDim)){
                const ang2=Math.atan2(sy-ocy,sx-ocx);
                const lx=sx+Math.cos(ang2)*(nr+22),ly=sy+Math.sin(ang2)*(nr+22);
                const nfs=Math.round(9*Math.max(0.5,Math.min(1.5,camZ)));
                ctx.font=nfs+'px system-ui';ctx.fillStyle=n.color+'ee';
                ctx.textAlign=lx>sx+3?'left':lx<sx-3?'right':'center';ctx.textBaseline='middle';
                const _nf=n.name,_mid=Math.floor(_nf.length/2),_sl=_nf.lastIndexOf(' ',_mid),_sr=_nf.indexOf(' ',_mid);
                let _l1=_nf,_l2=null;
                if(_nf.length>14){const _sp=(_sl>-1&&_sr>-1)?(Math.abs(_sl-_mid)<Math.abs(_sr-_mid)?_sl:_sr):(_sl>-1?_sl:_sr);if(_sp>-1){_l1=_nf.slice(0,_sp);_l2=_nf.slice(_sp+1);}}
                const _lines=_l2?[_l1,_l2]:[_l1];const _lh=nfs*1.3;const _totalH=_lines.length*_lh;
                const _maxW=Math.max(..._lines.map(l=>ctx.measureText(l).width));
                const _px=5,_py=3;const _bgX=ctx.textAlign==='left'?lx-_px:ctx.textAlign==='right'?lx-_maxW-_px:lx-_maxW/2-_px;
                ctx.fillStyle='#0a0f1acc';ctx.beginPath();if(ctx.roundRect)ctx.roundRect(_bgX,ly-_totalH/2-_py,_maxW+_px*2,_totalH+_py*2,3);else ctx.rect(_bgX,ly-_totalH/2-_py,_maxW+_px*2,_totalH+_py*2);ctx.fill();
                ctx.fillStyle=n.color+'ee';_lines.forEach((_l,_i)=>ctx.fillText(_l,lx,ly-_totalH/2+_lh*(_i+0.5)));
            }
        ctx.globalAlpha=1;ctx.textBaseline='alphabetic';ctx.textAlign='center';
    });
    requestAnimationFrame(draw);
}

canvas.addEventListener('mousedown',e=>{dragging=true;dragSX=e.clientX;dragSY=e.clientY;camSX=camX;camSY=camY;canvas.style.cursor='grabbing';});
canvas.addEventListener('mousemove',e=>{
    if(dragging){tX=camSX+(e.clientX-dragSX)/camZ;tY=camSY+(e.clientY-dragSY)/camZ;}
    else{const rect=canvas.getBoundingClientRect();const hit=hitNode(e.clientX-rect.left,e.clientY-rect.top);const nid=hit?hit.id:null;
        if(nid!==hoverId){hoverId=nid;canvas.style.cursor=hit?'pointer':'grab';
            if(mode==='dimfocus'&&selectedDim&&!selectedSub){if(hit&&hit.type==='dim'&&hit.id!==selectedDim)renderDimPanel(selectedDim,hit.id);else if(!hit||hit.id===selectedDim||hit.type==='subdim')renderDimPanel(selectedDim,null);}}}
});
canvas.addEventListener('mouseup',e=>{
    const moved=Math.abs(e.clientX-dragSX)>5||Math.abs(e.clientY-dragSY)>5;
    dragging=false;canvas.style.cursor='grab';if(moved)return;
    const rect=canvas.getBoundingClientRect();const hit=hitNode(e.clientX-rect.left,e.clientY-rect.top);
    if(!hit||hit.type==='root'){enterOverview();return;}
    if(hit.type==='dim'){enterDimFocus(hit.id);return;}
    if(hit.type==='subdim'){selectedSub=hit.id;const sn=allNodes.find(n=>n.id===hit.id);if(sn)renderSubPanel(sn);}
});
canvas.addEventListener('mouseleave',()=>{dragging=false;canvas.style.cursor='grab';hoverId=null;if(mode==='dimfocus'&&selectedDim&&!selectedSub)renderDimPanel(selectedDim,null);});
canvas.addEventListener('wheel',e=>{e.preventDefault();tZ=Math.min(4.5,Math.max(0.3,tZ*(e.deltaY<0?1.13:0.88)));},{passive:false});

setLayout('overview',null);
renderOverviewPanel();
requestAnimationFrame(draw);
<\/script>
</body>
</html>`;

    const blob = new Blob([html], {type:'text/html'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${fwAbbr}_Integration_Map.html`;
    a.click();
    URL.revokeObjectURL(a.href);
}

async function exportASMFPosterAsHTML() {
    if (!_asmfFramework) {
        try {
            const resp = await fetch('/api/asmf-framework');
            _asmfFramework = await resp.json();
        } catch(e) {
            alert('Could not load framework data.');
            return;
        }
    }
    const fw = _asmfFramework;
    const matrixInner = _asmfBuildMatrix(fw);
    const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${escapeHtml(fw.framework_abbrev||'ASMF')} — ${escapeHtml(fw.framework_name||'Agentic Adoption Framework')}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0a0f1a;color:#e2e8f0;font-family:'Segoe UI',system-ui,sans-serif;padding:32px 28px}
:root{--bg-primary:#0a0f1a;--bg-secondary:#0f172a;--border-color:#1e293b;--text-primary:#f1f5f9;--text-secondary:#94a3b8;--text-muted:#475569}
h1{font-size:28px;font-weight:800;color:#f8fafc;margin-bottom:6px}
h3{font-size:15px;font-weight:700;color:var(--text-primary);margin:0 0 12px;border-bottom:1px solid var(--border-color);padding-bottom:8px}
table{border-collapse:collapse}
</style>
</head>
<body>
<div style="margin-bottom:28px;">
  <div style="font-size:11px;color:#3b82f6;text-transform:uppercase;letter-spacing:1.5px;font-weight:700;margin-bottom:4px;">
    ${escapeHtml(fw.framework_abbrev||'ASAF')} ${escapeHtml(fw.schema_version||'v1.0')}
  </div>
    <h1>${escapeHtml(fw.framework_name||'Agentic Adoption Framework')}</h1>
  <p style="font-size:13px;color:#64748b;margin-top:6px;">${escapeHtml(fw.scope||'')}</p>
</div>
${matrixInner.replace(/var\(--bg-primary\)/g,'#0a0f1a').replace(/var\(--bg-secondary\)/g,'#0f172a').replace(/var\(--border-color\)/g,'#1e293b').replace(/var\(--text-primary\)/g,'#f1f5f9').replace(/var\(--text-secondary\)/g,'#94a3b8').replace(/var\(--text-muted\)/g,'#475569')}
<script>
document.querySelectorAll('td[data-full]').forEach(cell=>{
  const t=document.createElement('div');
  t.style.cssText='display:none;position:fixed;z-index:9999;background:#0f172a;border:1px solid #334155;border-radius:8px;padding:12px 16px;max-width:360px;font-size:12px;color:#e2e8f0;line-height:1.6;box-shadow:0 8px 32px rgba(0,0,0,.5);pointer-events:none;';
  document.body.appendChild(t);
  cell.addEventListener('mouseenter',e=>{t.textContent=cell.dataset.full;t.style.display='block';});
  cell.addEventListener('mousemove',e=>{
    let l=e.clientX+16,top=e.clientY+10;
    if(l+t.offsetWidth>window.innerWidth-8)l=e.clientX-t.offsetWidth-12;
    if(top+t.offsetHeight>window.innerHeight-8)top=e.clientY-t.offsetHeight-12;
    t.style.left=l+'px';t.style.top=top+'px';
  });
  cell.addEventListener('mouseleave',()=>t.style.display='none');
});
</script>
</body></html>`;

    const blob = new Blob([html], {type:'text/html'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${fw.framework_abbrev || 'ASMF'}_Adoption_Matrix_Poster.html`;
    a.click();
    URL.revokeObjectURL(a.href);
}



const ASMF_STAGE_COLORS = ['#6b7280','#3b82f6','#8b5cf6','#f59e0b','#10b981','#22c55e'];
const ASMF_STAGE_LABELS = ['Traditional','Assisted','Supervised Autonomy','Directed Autonomy','Collaborative Agentic','Fully Agentic'];

let _asmfFramework = null;
let _asmfOrbitalMap = null;
let _asmfSankeyResizeBound = false;
let _asmfSankeyResizeTimer = null;
let _asmfRadarResizeBound = false;
let _asmfRadarResizeTimer = null;

function resetASMFVisualizations() {
    _asmfFramework = null;
    _asmfGraph = null;

    [
        'asmf-content',
        'asmf-matrix-content',
        'asmf-radar-content',
        'asmf-sankey-content',
        'asmf-pyramid-content',
        'asmf-timeline-content',
        'asmf-graph-3d',
        'asmf-graph-detail',
        'asmf-orbital-content'
    ].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.innerHTML = '';
            delete el.dataset.rendered;
        }
    });

    [
        'asmf-matrix-pane-matrix',
        'asmf-matrix-pane-radar',
        'asmf-matrix-pane-sankey',
        'asmf-matrix-pane-pyramid',
        'asmf-matrix-pane-timeline',
        'asmf-graph-pane-force',
        'asmf-graph-pane-orbital'
    ].forEach(id => {
        const pane = document.getElementById(id);
        if (pane) delete pane.dataset.rendered;
    });
}

// ── ASMF inner-tab switching (event delegation — always works) ──────────────

document.addEventListener('click', function(e) {
    const btn = e.target.closest('.asmf-inner-tab');
    if (!btn) return;

    const tab   = btn.dataset.asmfTab;
    const panel = btn.dataset.panel; // 'asmf-matrix' or 'asmf-graph'
    const parentPanel = btn.closest('.asmf-panel-full');
    if (!parentPanel) return;

    // Activate tab button
    parentPanel.querySelectorAll('.asmf-inner-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');

    // Activate pane — pane IDs are like "asmf-matrix-pane-matrix", "asmf-graph-pane-force"
    // panel is already "asmf-matrix" / "asmf-graph", so just use `${panel}-pane-${tab}`
    parentPanel.querySelectorAll('.asmf-inner-pane').forEach(p => p.classList.remove('active'));
    const pane = document.getElementById(`${panel}-pane-${tab}`);
    if (!pane) { console.error('[ASMF] pane not found:', `${panel}-pane-${tab}`); return; }
    pane.classList.add('active');

    // Lazy-render (only once per pane)
    if (pane.dataset.rendered === '1') return;
    pane.dataset.rendered = '1';

    if (panel === 'asmf-matrix') {
        if (tab === 'matrix')   populateASMFMatrix();
        if (tab === 'radar')    populateASMFRadar();
        if (tab === 'sankey')   populateASMFSankey();
        if (tab === 'pyramid')  populateASMFPyramid();
        if (tab === 'timeline') populateASMFTimeline();
    } else if (panel === 'asmf-graph') {
        if (tab === 'force')   populateASMFGraph();
        if (tab === 'orbital') populateASMFOrbital();
    }
});

// ── ASAF Positioning Statement ───────────────────────────────────────────────

function populateASAFPositioning() {
    const body = document.getElementById('report-asaf-positioning-body');
    if (!body) return;

    // Scroll container to top so dropdown is always visible on activation
    const panel = document.getElementById('report-panel-asaf-positioning');
    if (panel) panel.scrollTop = 0;

    // First call: inject selector shell; subsequent calls: noop (dropdown handles re-render)
    if (!body.dataset.init) {
        body.dataset.init = '1';
        body.innerHTML = `
        <div style="padding:0 0 20px;">
            <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:16px 20px;background:var(--bg-tertiary);border-radius:8px;border:1px solid var(--border-color);margin-bottom:4px;">
                <label style="font-size:13px;font-weight:600;color:var(--text-primary);white-space:nowrap;">Select Positioning Statement:</label>
                <select id="asaf-pos-select" style="flex:1;min-width:220px;max-width:540px;padding:8px 12px;border-radius:6px;border:1px solid var(--border-color);background:var(--bg-primary);color:var(--text-primary);font-size:13px;cursor:pointer;">
                    <option value="product-alignment">1 — Product Architecture: The Alert-Triage Sunset</option>
                    <option value="functional-integration">2 — Functional Integration: The Cybernetic Loop Requirement</option>
                    <option value="ethics-governance">3 — Ethics &amp; Governance: The Runtime Control Signal Imperative</option>
                </select>
            </div>
        </div>
        <div id="asaf-pos-content"></div>`;

        document.getElementById('asaf-pos-select').addEventListener('change', e => {
            _renderASAFPositioningStatement(e.target.value);
        });
    }
    _renderASAFPositioningStatement(document.getElementById('asaf-pos-select')?.value || 'product-alignment');
}

