    svg.style.maxWidth = '1200px';
    svg.style.background = '#fafaf8';
    svg.style.borderRadius = '16px';
    svg.style.border = '2px solid #e0ddd5';
    container.innerHTML = '';
    container.appendChild(svg);

    const rc = rough.svg(svg);
    const seed = 77;
