    const STICKY_BLUE = dk ? '#2a3545' : '#e3f2fd';
    const STICKY_GREEN = dk ? '#2a4530' : '#e8f5e9';
    const STICKY_ORANGE = dk ? '#4a3a28' : '#fff3e0';

    function addText(x, y, text, size, weight, color, anchor, rotate) {
        const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        t.setAttribute('x', x); t.setAttribute('y', y);
        t.setAttribute('font-size', size);
        t.setAttribute('font-weight', weight || '400');
        t.setAttribute('fill', color || DARK);
        t.setAttribute('font-family', "'Caveat', 'Marker Felt', 'Comic Sans MS', cursive");
        t.setAttribute('text-anchor', anchor || 'start');
        if (rotate) t.setAttribute('transform', `rotate(${rotate}, ${x}, ${y})`);
        t.textContent = text; svg.appendChild(t); return t;
    }
    function addMultiText(x, y, lines, size, color, lineH, anchor) {
        lines.forEach((ln, i) => addText(x, y + i * (lineH || size * 1.45), ln, size, '400', color || MED, anchor));
    }

    // ═══ WHITEBOARD FRAME — dashed border like a real board edge ═══
    svg.appendChild(rc.rectangle(8, 8, W - 16, H - 16, { roughness: 3, bowing: 1, seed, strokeWidth: 1.5, stroke: BOARD_LINE, strokeLineDash: [12, 8] }));

    // ═══ TITLE — hand-scrawled banner ═══
