async function exportMDRInfographicPPTX() {
    try {
        const resp = await fetch('/api/mdr-infographic-pptx');
        if (!resp.ok) throw new Error('Server returned ' + resp.status);
        const blob = await resp.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'MDR_Pricing_Evolution_Infographic.pptx';
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
    } catch (e) {
        alert('PPTX export failed: ' + e.message);
    }
}

/** Export ALL MDR graphics as multi-slide PowerPoint */
async function exportMDRAllGraphicsPPTX() {
    try {
        const resp = await fetch('/api/mdr-all-graphics-pptx?t=' + Date.now());
        if (!resp.ok) throw new Error('Server returned ' + resp.status);
        const blob = await resp.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'MDR_All_Graphics.pptx';
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
    } catch (e) {
        alert('PPTX export failed: ' + e.message);
    }
}

