function _miRenderPositioning(data) {
    const panel = document.getElementById('mi-panel-positioning');
    if (!panel) return;

    const pja = _miPositioningStatements[data.id];
    if (!pja) {
        panel.innerHTML = '<p class="mi-empty">No positioning statement available for this perspective.</p>';
        return;
    }

    let html = '';

    // PJA Flow Diagram
    html += '<div style="text-align: center; padding: 20px 0 24px;">';
    html += '<div style="display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap;">';
    html += '<div style="background: var(--color-primary); color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83C\uDFAF POSITION<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Declarative stance on<br>an important issue</span></div>';
    html += '<span style="font-size: 24px; color: var(--text-secondary);">\u2192</span>';
    html += '<div style="background: #0078d4; color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83D\uDCD0 JUSTIFICATION<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Evidence & logic that<br>validates the position</span></div>';
    html += '<span style="font-size: 24px; color: var(--text-secondary);">\u2192</span>';
    html += '<div style="background: #107c10; color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83D\uDE80 ACTIONS<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Specific client response<br>to achieve success</span></div>';
    html += '</div></div>';

    // ── Position Statement ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83C\uDFAF</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Position Statement</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    html += '<div class="report-sp-section">';
    html += '<blockquote style="border-left: 4px solid var(--color-primary); padding: 16px 20px; margin: 0; background: var(--bg-tertiary); border-radius: 0 8px 8px 0; font-size: 16px; font-weight: 600; line-height: 1.5; color: var(--text-primary);">';
    html += escapeHtml(pja.position);
    html += '</blockquote></div>';

    // Position Components
    const pc = pja.positionComponents;
    html += '<div class="report-sp-section"><h4>Position Components</h4>';
    const compItems = [
        { label: 'Important Issue', text: pc.importantIssue, color: '#d83b01' },
        { label: 'Judgment', text: pc.judgment, color: 'var(--color-primary)' },
        { label: 'State', text: pc.state, color: '#0078d4' },
        { label: 'Drama (Attention + Motivation)', text: pc.drama, color: '#8764b8' }
    ];
    compItems.forEach(c => {
        html += '<div style="margin-bottom: 12px; padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px; border-left: 3px solid ' + c.color + ';">';
        html += '<strong style="color: ' + c.color + ';">' + c.label + '</strong>';
        html += '<p style="margin: 6px 0 0; font-size: 13px; color: var(--text-secondary);">' + escapeHtml(c.text) + '</p>';
        html += '</div>';
    });
    html += '</div>';
    html += '</div></div>';

    // ── Justification ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDCD0</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Justification</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    const justItems = [
        { label: 'Context', text: pja.justification.context },
        { label: 'Evidence & Logic', text: pja.justification.evidence },
        { label: 'Action Bridge', text: pja.justification.actionBridge }
    ];
    justItems.forEach(j => {
        html += '<div class="report-sp-section">';
        html += '<h4>' + j.label + '</h4>';
        html += '<p style="font-size: 13px; line-height: 1.6; color: var(--text-secondary);">' + escapeHtml(j.text) + '</p>';
        html += '</div>';
    });
    html += '</div></div>';

    // ── Recommended Actions ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDE80</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Recommended Actions</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    pja.actions.forEach((a, i) => {
        html += '<div class="report-sp-section" style="border-bottom: 1px solid var(--border-color); padding-bottom: 16px; margin-bottom: 16px;">';
        html += '<h4>Action ' + (i + 1) + '</h4>';
        html += '<p style="font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 8px;">' + escapeHtml(a.action) + '</p>';
        html += '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">';
        html += '<div style="padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px;">';
        html += '<strong style="font-size: 11px; text-transform: uppercase; color: var(--text-secondary);">Why Non-Obvious</strong>';
        html += '<p style="margin: 4px 0 0; font-size: 12px; color: var(--text-secondary);">' + escapeHtml(a.whyNonObvious) + '</p>';
        html += '</div>';
        html += '<div style="padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px;">';
        html += '<strong style="font-size: 11px; text-transform: uppercase; color: var(--text-secondary);">Expected Outcome</strong>';
        html += '<p style="margin: 4px 0 0; font-size: 12px; color: var(--text-secondary);">' + escapeHtml(a.outcome) + '</p>';
        html += '</div></div></div>';
    });
    html += '</div></div>';

    // ── Report Alignment ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDD17</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Report Alignment</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';

    // Position → Finding
    html += '<div class="report-sp-section">';
    html += '<h4>Position \u2192 Key Finding</h4>';
    html += '<p style="font-size: 13px; color: var(--text-secondary); padding: 8px 14px; background: var(--bg-tertiary); border-radius: 6px;">' + escapeHtml(pja.alignment.positionToFinding) + '</p>';
    html += '</div>';

    // Actions → Recommendations
    html += '<div class="report-sp-section">';
    html += '<h4>Actions \u2192 Recommendations</h4>';
    html += '<div style="display: flex; flex-direction: column; gap: 6px;">';
    pja.alignment.actionsToRecs.forEach(m => {
        html += '<div style="font-size: 12px; color: var(--text-secondary); padding: 6px 14px; background: var(--bg-tertiary); border-radius: 4px;">' + escapeHtml(m) + '</div>';
    });
    html += '</div></div>';

    // Justification → Sources
    html += '<div class="report-sp-section">';
    html += '<h4>Justification Sources</h4>';
    html += '<p style="font-size: 13px; color: var(--text-secondary); padding: 8px 14px; background: var(--bg-tertiary); border-radius: 6px;">' + escapeHtml(pja.alignment.justificationSources) + '</p>';
    html += '</div>';

    html += '</div></div>';

    panel.innerHTML = html;
}

/** MDR Market Insight inline editing */
function miToggleEdit() {
    _miEditMode = true;
    document.getElementById('mi-edit-btn').style.display = 'none';
    document.getElementById('mi-save-btn').style.display = '';
    document.getElementById('mi-cancel-btn').style.display = '';

    const reportPanel = document.getElementById('report-panel-mdr-market-insight');
    reportPanel.querySelectorAll('[data-mi-field]').forEach(el => {
        el.contentEditable = 'true';
        el.classList.add('pci-editable');
    });
}

async function miSaveEdits() {
    const reportPanel = document.getElementById('report-panel-mdr-market-insight');
    const perspectiveId = _miCurrentPerspective;
    if (!perspectiveId) return;

    const payload = { id: perspectiveId };

    const simpleFields = ['title', 'summary', 'spa', 'background', 'impact', 'conclusion'];
    simpleFields.forEach(field => {
        const el = reportPanel.querySelector(`[data-mi-field="${field}"]`);
        if (el) payload[field] = el.innerText.trim();
    });

    const findings = [];
    let fi = 0;
    while (true) {
        const hEl = reportPanel.querySelector(`[data-mi-field="finding-header-${fi}"]`);
        const bEl = reportPanel.querySelector(`[data-mi-field="finding-body-${fi}"]`);
        if (!hEl && !bEl) break;
        findings.push({
            header: hEl ? hEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        fi++;
    }
    if (findings.length) payload.findings = findings;

    const recommendations = [];
    let ri = 0;
    while (true) {
        const hEl = reportPanel.querySelector(`[data-mi-field="rec-header-${ri}"]`);
        const bEl = reportPanel.querySelector(`[data-mi-field="rec-body-${ri}"]`);
        if (!hEl && !bEl) break;
        recommendations.push({
            header: hEl ? hEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        ri++;
    }
    if (recommendations.length) payload.recommendations = recommendations;

    const analysisSections = [];
    let ai = 0;
    while (true) {
        const tEl = reportPanel.querySelector(`[data-mi-field="analysis-title-${ai}"]`);
        const bEl = reportPanel.querySelector(`[data-mi-field="analysis-body-${ai}"]`);
        if (!tEl && !bEl) break;
        analysisSections.push({
            title: tEl ? tEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        ai++;
    }
    if (analysisSections.length) payload.analysis_sections = analysisSections;

    try {
        const resp = await fetch('/api/mdr-market-insight', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const result = await resp.json();
        if (result.error) {
            alert('Save failed: ' + result.error);
            return;
        }
    } catch (e) {
        alert('Save failed: ' + e.message);
        return;
    }

    _miEditMode = false;
    document.getElementById('mi-edit-btn').style.display = '';
    document.getElementById('mi-save-btn').style.display = 'none';
    document.getElementById('mi-cancel-btn').style.display = 'none';

    const panel = document.getElementById('mi-panel-exec-summary');
    if (panel) panel.dataset.loaded = '';
    populateMDRMarketInsight(_miCurrentPerspective);
}

function miCancelEdit() {
    _miEditMode = false;
    document.getElementById('mi-edit-btn').style.display = '';
    document.getElementById('mi-save-btn').style.display = 'none';
    document.getElementById('mi-cancel-btn').style.display = 'none';

    const panel = document.getElementById('mi-panel-exec-summary');
    if (panel) panel.dataset.loaded = '';
    populateMDRMarketInsight(_miCurrentPerspective);
}

