function _pciRenderPositioning(data) {
    const panel = document.getElementById('pci-panel-positioning');
    if (!panel) return;

    const pja = _pciPositioningStatements[data.id];
    if (!pja) {
        panel.innerHTML = '<p class="mi-empty">No positioning statement available for this perspective.</p>';
        return;
    }

    let html = '';

    // PJA Flow Diagram
    html += '<div style="text-align: center; padding: 20px 0 24px;">';
    html += '<div style="display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap;">';
    html += '<div style="background: var(--color-primary); color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83C\uDFAF POSITION<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Declarative stance on<br>an important issue</span></div>';
    html += '<span style="font-size: 24px; color: var(--text-secondary);">\u2192</span>';
    html += '<div style="background: #0078d4; color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83D\uDCD0 JUSTIFICATION<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Evidence & logic that<br>validates the position</span></div>';
    html += '<span style="font-size: 24px; color: var(--text-secondary);">\u2192</span>';
    html += '<div style="background: #107c10; color: #fff; padding: 14px 24px; border-radius: 10px; font-weight: 700; font-size: 15px; min-width: 140px;">';
    html += '\uD83D\uDE80 ACTIONS<br><span style="font-weight: 400; font-size: 11px; opacity: 0.85;">Specific client response<br>to achieve success</span></div>';
    html += '</div></div>';

    // ── Position Statement ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83C\uDFAF</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Position Statement</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    html += '<div class="report-sp-section">';
    html += '<blockquote style="border-left: 4px solid var(--color-primary); padding: 16px 20px; margin: 0; background: var(--bg-tertiary); border-radius: 0 8px 8px 0; font-size: 16px; font-weight: 600; line-height: 1.5; color: var(--text-primary);">';
    html += escapeHtml(pja.position);
    html += '</blockquote></div>';

    // Position Components
    const pc = pja.positionComponents;
    html += '<div class="report-sp-section"><h4>Position Components</h4>';
    const compItems = [
        { label: 'Important Issue', text: pc.importantIssue, color: '#d83b01' },
        { label: 'Judgment', text: pc.judgment, color: 'var(--color-primary)' },
        { label: 'State', text: pc.state, color: '#0078d4' },
        { label: 'Drama (Attention + Motivation)', text: pc.drama, color: '#8764b8' }
    ];
    compItems.forEach(c => {
        html += '<div style="margin-bottom: 12px; padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px; border-left: 3px solid ' + c.color + ';">';
        html += '<strong style="color: ' + c.color + ';">' + c.label + '</strong>';
        html += '<p style="margin: 6px 0 0; font-size: 13px; color: var(--text-secondary);">' + escapeHtml(c.text) + '</p>';
        html += '</div>';
    });
    html += '</div>';
    html += '</div></div>';

    // ── Justification ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDCD0</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Justification</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    const justItems = [
        { label: 'Context', text: pja.justification.context },
        { label: 'Evidence & Logic', text: pja.justification.evidence },
        { label: 'Action Bridge', text: pja.justification.actionBridge }
    ];
    justItems.forEach(j => {
        html += '<div class="report-sp-section">';
        html += '<h4>' + j.label + '</h4>';
        html += '<p style="font-size: 13px; line-height: 1.6; color: var(--text-secondary);">' + escapeHtml(j.text) + '</p>';
        html += '</div>';
    });
    html += '</div></div>';

    // ── Recommended Actions ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDE80</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Recommended Actions</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';
    pja.actions.forEach((a, i) => {
        html += '<div class="report-sp-section" style="border-bottom: 1px solid var(--border-color); padding-bottom: 16px; margin-bottom: 16px;">';
        html += '<h4>Action ' + (i + 1) + '</h4>';
        html += '<p style="font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 8px;">' + escapeHtml(a.action) + '</p>';
        html += '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">';
        html += '<div style="padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px;">';
        html += '<strong style="font-size: 11px; text-transform: uppercase; color: var(--text-secondary);">Why Non-Obvious</strong>';
        html += '<p style="margin: 4px 0 0; font-size: 12px; color: var(--text-secondary);">' + escapeHtml(a.whyNonObvious) + '</p>';
        html += '</div>';
        html += '<div style="padding: 10px 14px; background: var(--bg-tertiary); border-radius: 6px;">';
        html += '<strong style="font-size: 11px; text-transform: uppercase; color: var(--text-secondary);">Expected Outcome</strong>';
        html += '<p style="margin: 4px 0 0; font-size: 12px; color: var(--text-secondary);">' + escapeHtml(a.outcome) + '</p>';
        html += '</div></div></div>';
    });
    html += '</div></div>';

    // ── Report Alignment ──
    html += '<div class="report-pillar-section">';
    html += '<div class="report-pillar-header">';
    html += '<span class="report-pillar-code">\uD83D\uDD17</span>';
    html += '<div class="report-pillar-header-text">';
    html += '<h2 class="report-pillar-name">Report Alignment</h2>';
    html += '</div></div>';
    html += '<div class="report-sp-longform-card">';

    // Position → Finding
    html += '<div class="report-sp-section">';
    html += '<h4>Position \u2192 Key Finding</h4>';
    html += '<p style="font-size: 13px; color: var(--text-secondary); padding: 8px 14px; background: var(--bg-tertiary); border-radius: 6px;">' + escapeHtml(pja.alignment.positionToFinding) + '</p>';
    html += '</div>';

    // Actions → Recommendations
    html += '<div class="report-sp-section">';
    html += '<h4>Actions \u2192 Recommendations</h4>';
    html += '<div style="display: flex; flex-direction: column; gap: 6px;">';
    pja.alignment.actionsToRecs.forEach(m => {
        html += '<div style="font-size: 12px; color: var(--text-secondary); padding: 6px 14px; background: var(--bg-tertiary); border-radius: 4px;">' + escapeHtml(m) + '</div>';
    });
    html += '</div></div>';

    // Justification → Sources
    html += '<div class="report-sp-section">';
    html += '<h4>Justification Sources</h4>';
    html += '<p style="font-size: 13px; color: var(--text-secondary); padding: 8px 14px; background: var(--bg-tertiary); border-radius: 6px;">' + escapeHtml(pja.alignment.justificationSources) + '</p>';
    html += '</div>';

    html += '</div></div>';

    panel.innerHTML = html;
}

/* ── PreCyber Market Insight Edit Mode ── */

function pciToggleEdit() {
    _pciEditMode = true;
    document.getElementById('pci-edit-btn').style.display = 'none';
    document.getElementById('pci-save-btn').style.display = '';
    document.getElementById('pci-cancel-btn').style.display = '';

    // Make all tagged text elements editable
    const reportPanel = document.getElementById('report-panel-precyber-market-insight');
    reportPanel.querySelectorAll('[data-pci-field]').forEach(el => {
        el.contentEditable = 'true';
        el.classList.add('pci-editable');
    });
}

async function pciSaveEdits() {
    const reportPanel = document.getElementById('report-panel-precyber-market-insight');
    const perspectiveId = _pciCurrentPerspective;
    if (!perspectiveId) return;

    // Collect edited content
    const payload = { id: perspectiveId };

    // Simple text fields (title, summary, spa, background, impact, conclusion)
    const simpleFields = ['title', 'summary', 'spa', 'background', 'impact', 'conclusion'];
    simpleFields.forEach(field => {
        const el = reportPanel.querySelector(`[data-pci-field="${field}"]`);
        if (el) payload[field] = el.innerText.trim();
    });

    // Findings (header + body pairs)
    const findings = [];
    let fi = 0;
    while (true) {
        const hEl = reportPanel.querySelector(`[data-pci-field="finding-header-${fi}"]`);
        const bEl = reportPanel.querySelector(`[data-pci-field="finding-body-${fi}"]`);
        if (!hEl && !bEl) break;
        findings.push({
            header: hEl ? hEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        fi++;
    }
    if (findings.length) payload.findings = findings;

    // Recommendations (header + body pairs)
    const recommendations = [];
    let ri = 0;
    while (true) {
        const hEl = reportPanel.querySelector(`[data-pci-field="rec-header-${ri}"]`);
        const bEl = reportPanel.querySelector(`[data-pci-field="rec-body-${ri}"]`);
        if (!hEl && !bEl) break;
        recommendations.push({
            header: hEl ? hEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        ri++;
    }
    if (recommendations.length) payload.recommendations = recommendations;

    // Analysis sections (title + body pairs)
    const analysisSections = [];
    let ai = 0;
    while (true) {
        const tEl = reportPanel.querySelector(`[data-pci-field="analysis-title-${ai}"]`);
        const bEl = reportPanel.querySelector(`[data-pci-field="analysis-body-${ai}"]`);
        if (!tEl && !bEl) break;
        analysisSections.push({
            title: tEl ? tEl.innerText.trim() : '',
            body: bEl ? bEl.innerText.trim() : ''
        });
        ai++;
    }
    if (analysisSections.length) payload.analysis_sections = analysisSections;

    try {
        const resp = await fetch('/api/precyber-market-insight', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const result = await resp.json();
        if (result.error) {
            alert('Save failed: ' + result.error);
            return;
        }
    } catch (e) {
        alert('Save failed: ' + e.message);
        return;
    }

    // Exit edit mode and re-render from server
    _pciEditMode = false;
    document.getElementById('pci-edit-btn').style.display = '';
    document.getElementById('pci-save-btn').style.display = 'none';
    document.getElementById('pci-cancel-btn').style.display = 'none';

    // Force re-fetch
    const panel = document.getElementById('pci-panel-exec-summary');
    if (panel) panel.dataset.loaded = '';
    populatePreCyberMarketInsight(_pciCurrentPerspective);
}

function pciCancelEdit() {
    _pciEditMode = false;
    document.getElementById('pci-edit-btn').style.display = '';
    document.getElementById('pci-save-btn').style.display = 'none';
    document.getElementById('pci-cancel-btn').style.display = 'none';

    // Re-render from cached data (discard edits)
    const panel = document.getElementById('pci-panel-exec-summary');
    if (panel) panel.dataset.loaded = '';
    populatePreCyberMarketInsight(_pciCurrentPerspective);
}

// ── DFIR Market Insight ────────────────────────────────────────────────

let _dfiCurrentPerspective = null;
let _dfiEditMode = false;
let _dfiCachedData = null;

async function populateDFIRMarketInsight(forcePerspective) {
    const panel = document.getElementById('dfi-panel-exec-summary');
    if (!panel) return;

    const select = document.getElementById('dfi-perspective-select');

    // Load perspective list on first visit
    if (select && select.options.length <= 1 && !select.dataset.loaded) {
        try {
            const pResp = await fetch('/api/dfir-market-insight/perspectives');
            const pData = await pResp.json();
            if (pData.perspectives && pData.perspectives.length) {
                select.innerHTML = '';
                pData.perspectives.forEach(p => {
                    const opt = document.createElement('option');
                    opt.value = p.id;
                    opt.textContent = p.label;
                    select.appendChild(opt);
                });
                _dfiCurrentPerspective = pData.perspectives[0].id;
                select.value = _dfiCurrentPerspective;
            }
        } catch (e) { /* leave default option */ }
        select.dataset.loaded = 'true';

        select.addEventListener('change', () => {
            const newPerspective = select.value;
            if (newPerspective && newPerspective !== _dfiCurrentPerspective) {
                _dfiCurrentPerspective = newPerspective;
                panel.dataset.loaded = '';
                populateDFIRMarketInsight(newPerspective);
            }
        });
    }

    const perspectiveId = forcePerspective || _dfiCurrentPerspective || '';
    if (panel.dataset.loaded === perspectiveId) return;

    let data;
    try {
        const url = perspectiveId
            ? `/api/dfir-market-insight?perspective=${encodeURIComponent(perspectiveId)}`
            : '/api/dfir-market-insight';
        const resp = await fetch(url);
        data = await resp.json();
        if (data.error) throw new Error(data.error);
    } catch (e) {
        panel.innerHTML = `<p class="mi-empty">DFIR Market Insight data not available: ${escapeHtml(e.message)}</p>`;
        return;
    }

    panel.dataset.loaded = perspectiveId;
    _dfiCachedData = data;

    // Set header
    const titleEl = document.getElementById('dfi-title');
    titleEl.textContent = data.title || 'DFIR Market Insight';
    titleEl.setAttribute('data-dfi-field', 'title');
    const summaryEl = document.getElementById('dfi-summary');
    summaryEl.textContent = data.summary || '';
    summaryEl.setAttribute('data-dfi-field', 'summary');

    // Setup inner tab switching (once)
    const tabContainer = document.getElementById('dfi-inner-tabs');
    if (tabContainer && !tabContainer._dfiListenersAttached) {
        tabContainer._dfiListenersAttached = true;
        tabContainer.addEventListener('click', e => {
            const tab = e.target.closest('.mi-inner-tab');
            if (!tab) return;
            tabContainer.querySelectorAll('.mi-inner-tab').forEach(t => t.classList.remove('active'));
            document.querySelectorAll('#dfi-tab-content .mi-inner-panel').forEach(p => p.classList.remove('active'));
            tab.classList.add('active');
            const panelId = `dfi-panel-${tab.dataset.dfiTab}`;
            const p = document.getElementById(panelId);
            if (p) p.classList.add('active');
        });
    }

    _dfiRenderExecSummary(data);
    _dfiRenderAnalysis(data);
    _dfiRenderBackground(data);
    _dfiRenderImpact(data);
    _dfiRenderConclusion(data);
    _dfiRenderGlossary(data);
    _dfiRenderGraphics(data);
}

function _dfiRenderExecSummary(data) {
    const panel = document.getElementById('dfi-panel-exec-summary');
    if (!panel) return;

    // KPI bar with key DFIR stats from the report
    const kpiHtml = `<div class="mi-kpi-bar">
        <div class="mi-kpi"><div class="mi-kpi-val">138</div><div class="mi-kpi-lbl">Vendors Analyzed</div></div>
        <div class="mi-kpi"><div class="mi-kpi-val" style="color:#0078d4">80%+</div><div class="mi-kpi-lbl">ForensicLLM Accuracy</div></div>
        <div class="mi-kpi"><div class="mi-kpi-val" style="color:#ca5010">62%</div><div class="mi-kpi-lbl">Traditional Vendors</div></div>
        <div class="mi-kpi"><div class="mi-kpi-val" style="color:#107c10">23%</div><div class="mi-kpi-lbl">AI-First Startups</div></div>
        <div class="mi-kpi"><div class="mi-kpi-val" style="color:#a80000">0%</div><div class="mi-kpi-lbl">AI-Native Traditional</div></div>
        <div class="mi-kpi"><div class="mi-kpi-val" style="color:#0078d4">50%</div><div class="mi-kpi-lbl">AI-Native Startups</div></div>
    </div>`;

    // SPA callout
    const spaHtml = data.spa ? `<div class="mi-spa-box">
        <div class="mi-spa-label">Strategic Planning Assumption</div>
        <p data-dfi-field="spa">${_miInlineFormat(data.spa)}</p>
    </div>` : '';

    // Key Findings
    let findingsHtml = '<div class="mi-findings"><h3>Key Findings</h3>';
    data.findings.forEach((f, i) => {
        findingsHtml += `<div class="mi-finding-item">
            <div class="mi-finding-num">${i + 1}</div>
            <div class="mi-finding-body"><strong data-dfi-field="finding-header-${i}">${_miInlineFormat(f.header)}</strong> <span data-dfi-field="finding-body-${i}">${_miInlineFormat(f.body)}</span></div>
        </div>`;
    });
    findingsHtml += '</div>';

    // Recommendations
    let recsHtml = '<div class="mi-recs"><h3>Recommendations</h3>';
    data.recommendations.forEach((r, i) => {
        recsHtml += `<div class="mi-rec-item">
            <div class="mi-rec-num">R${i + 1}</div>
            <div class="mi-rec-body"><strong data-dfi-field="rec-header-${i}">${_miInlineFormat(r.header)}</strong> <span data-dfi-field="rec-body-${i}">${_miInlineFormat(r.body)}</span></div>
        </div>`;
    });
    recsHtml += '</div>';

    // Finding-Recommendation correlation matrix
    let matrixHtml = '';
    if (data.findings.length > 0 && data.recommendations.length > 0) {
        matrixHtml = '<div class="mi-matrix"><h3>Finding \u2194 Recommendation Alignment</h3><div class="mi-matrix-grid">';
        const n = Math.min(data.findings.length, data.recommendations.length);
        for (let i = 0; i < n; i++) {
            const fShort = data.findings[i].header.substring(0, 80) + (data.findings[i].header.length > 80 ? '\u2026' : '');
            const rShort = data.recommendations[i].header.substring(0, 80) + (data.recommendations[i].header.length > 80 ? '\u2026' : '');
            matrixHtml += `<div class="mi-matrix-row">
                <div class="mi-matrix-finding"><span class="mi-matrix-tag">F${i+1}</span> ${escapeHtml(fShort)}</div>
                <div class="mi-matrix-arrow">\u2192</div>
                <div class="mi-matrix-rec"><span class="mi-matrix-tag mi-matrix-tag-rec">R${i+1}</span> ${escapeHtml(rShort)}</div>
            </div>`;
        }
        matrixHtml += '</div></div>';
    }

    panel.innerHTML = kpiHtml + spaHtml + findingsHtml + recsHtml + matrixHtml;
}

