function _dfiRenderGlossary(data) {
    const panel = document.getElementById('dfi-panel-glossary');
    if (!panel) return;

    let html = '<div class="mi-analysis-section"><h3>Acronym Key and Glossary Terms</h3>';
    html += '<div class="mi-glossary-grid">';
    data.glossary.forEach(g => {
        html += `<div class="mi-glossary-item">
            <div class="mi-glossary-term">${escapeHtml(g.term)}</div>
            <div class="mi-glossary-def">${_miInlineFormat(g.definition)}</div>
        </div>`;
    });
    html += '</div></div>';

    html += '<div class="mi-analysis-section"><h3>Evidence</h3><ul class="mi-evidence-list">';
    data.evidence.forEach(e => {
        html += `<li>${_miInlineFormat(e)}</li>`;
    });
    html += '</ul></div>';

    panel.innerHTML = html;
}

