/* ═══════════════════════════════════════════════════════════════════════════
 *  PMR (Product Market Readiness) — Credibility Gap Market Insight
 * ═══════════════════════════════════════════════════════════════════════════ */

let _pmrCurrentPerspective = '';
let _pmrCachedData = null;
let _pmrEditMode = false;

async function populatePMRMarketInsight(forcePerspective) {
    const panel = document.getElementById('pmr-panel-exec-summary');
    if (!panel) return;

    const select = document.getElementById('pmr-perspective-select');

    // Load perspective list on first visit
    if (select && select.options.length <= 1 && !select.dataset.loaded) {
        try {
            const pResp = await fetch('/api/pmr-market-insight/perspectives');
            const pData = await pResp.json();
            if (pData.perspectives && pData.perspectives.length) {
                select.innerHTML = '';
                pData.perspectives.forEach(p => {
                    const opt = document.createElement('option');
                    opt.value = p.id;
                    opt.textContent = p.label;
                    select.appendChild(opt);
                });
                _pmrCurrentPerspective = pData.perspectives[0].id;
                select.value = _pmrCurrentPerspective;
            }
        } catch (e) { /* leave default option */ }
        select.dataset.loaded = 'true';

        select.addEventListener('change', () => {
            const newPerspective = select.value;
            if (newPerspective && newPerspective !== _pmrCurrentPerspective) {
                _pmrCurrentPerspective = newPerspective;
                panel.dataset.loaded = '';
                populatePMRMarketInsight(newPerspective);
            }
        });
    }

    const perspectiveId = forcePerspective || _pmrCurrentPerspective || '';
    if (panel.dataset.loaded === perspectiveId) return;

    let data;
    try {
        const url = perspectiveId
            ? `/api/pmr-market-insight?perspective=${encodeURIComponent(perspectiveId)}`
            : '/api/pmr-market-insight';
        const resp = await fetch(url);
        data = await resp.json();
        if (data.error) throw new Error(data.error);
    } catch (e) {
        panel.innerHTML = `<p class="mi-empty">PMR Market Insight data not available: ${escapeHtml(e.message)}</p>`;
        return;
    }

    panel.dataset.loaded = perspectiveId;

    const titleEl = document.getElementById('pmr-title');
    titleEl.textContent = data.title || 'Product Market Readiness — Credibility Gap Analysis';
    titleEl.setAttribute('data-pmr-field', 'title');
    const summaryEl = document.getElementById('pmr-summary');
    summaryEl.textContent = data.summary || '';
    summaryEl.setAttribute('data-pmr-field', 'summary');

    // Setup inner tab switching (once)
    const tabContainer = document.getElementById('pmr-inner-tabs');
    if (tabContainer && !tabContainer._pmrListenersAttached) {
        tabContainer._pmrListenersAttached = true;
        tabContainer.addEventListener('click', e => {
            const tab = e.target.closest('.mi-inner-tab');
            if (!tab) return;
            tabContainer.querySelectorAll('.mi-inner-tab').forEach(t => t.classList.remove('active'));
            const contentArea = document.getElementById('pmr-tab-content');
            contentArea.querySelectorAll('.mi-inner-panel').forEach(p => p.classList.remove('active'));
            tab.classList.add('active');
            const panelId = `pmr-panel-${tab.dataset.pmrTab}`;
            const p = document.getElementById(panelId);
            if (p) p.classList.add('active');
        });
    }

    // Fetch live stats for visualizations
    let stats = null;
    try {
        const sr = await fetch('/api/pmr-stats');
        stats = await sr.json();
        if (stats.error) stats = null;
    } catch (e) { /* render without stats */ }

    _pmrCachedData = data;
    _pmrRenderExecSummary(data, stats);
    _pmrRenderAnalysis(data, stats);
    _pmrRenderBackground(data, stats);
    _pmrRenderImpact(data, stats);
    _pmrRenderConclusion(data, stats);
    _pmrRenderGlossary(data);
    _pmrRenderGraphics(data, stats);
}

/* ── PMR Exec Summary ── */
function _pmrRenderExecSummary(data, stats) {
    const panel = document.getElementById('pmr-panel-exec-summary');
    if (!panel) return;
    let html = '';

    // SPA
    html += `<div class="mi-spa-box">
        <h2>Strategic Planning Assumption</h2>
        <p data-pmr-field="spa">${escapeHtml(data.spa || '')}</p>
    </div>`;

    // Key Stats Bar (from live stats)
    if (stats) {
        const os = stats.overall_stats || {};
        html += `<div class="mi-stats-bar" style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:18px 0;">
            <div class="mi-stat-card" style="background:#1a1a2e;border:1px solid #333;border-radius:8px;padding:14px;text-align:center;">
                <div style="font-size:28px;font-weight:700;color:#60a5fa;">${stats.vendor_count}</div>
                <div style="font-size:11px;color:#999;margin-top:4px;">Vendors Evaluated</div>
            </div>
            <div class="mi-stat-card" style="background:#1a1a2e;border:1px solid #333;border-radius:8px;padding:14px;text-align:center;">
                <div style="font-size:28px;font-weight:700;color:#34d399;">${os.gtm_mean || '0.0'}</div>
                <div style="font-size:11px;color:#999;margin-top:4px;">Avg GTM Score</div>
            </div>
            <div class="mi-stat-card" style="background:#1a1a2e;border:1px solid #333;border-radius:8px;padding:14px;text-align:center;">
                <div style="font-size:28px;font-weight:700;color:#f59e0b;">${os.proof_mean || '0.0'}</div>
                <div style="font-size:11px;color:#999;margin-top:4px;">Avg Proof Score</div>
            </div>
            <div class="mi-stat-card" style="background:#1a1a2e;border:1px solid #333;border-radius:8px;padding:14px;text-align:center;">
                <div style="font-size:28px;font-weight:700;color:${(os.gap_mean || 0) > 0.5 ? '#ef4444' : '#34d399'};">${os.gap_mean || '0.0'}</div>
                <div style="font-size:11px;color:#999;margin-top:4px;">Avg Credibility Gap</div>
            </div>
            <div class="mi-stat-card" style="background:#1a1a2e;border:1px solid #333;border-radius:8px;padding:14px;text-align:center;">
                <div style="font-size:28px;font-weight:700;color:#a78bfa;">5</div>
                <div style="font-size:11px;color:#999;margin-top:4px;">Pillars × 5 Subs</div>
            </div>
        </div>`;
    }

    // Findings
    if (data.findings && data.findings.length) {
        html += `<h2>Key Findings</h2>`;
        data.findings.forEach((f, i) => {
            html += `<div class="mi-finding">
                <h3 data-pmr-field="finding-header-${i}">${escapeHtml(f.header)}</h3>
                <p data-pmr-field="finding-body-${i}">${escapeHtml(f.body)}</p>
            </div>`;
        });
    }

    // Recommendations
    if (data.recommendations && data.recommendations.length) {
        html += `<h2>Recommendations</h2>`;
        data.recommendations.forEach((r, i) => {
            html += `<div class="mi-recommendation">
                <h3 data-pmr-field="rec-header-${i}">${escapeHtml(r.header)}</h3>
                <p data-pmr-field="rec-body-${i}">${escapeHtml(r.body)}</p>
            </div>`;
        });
    }

    panel.innerHTML = html;
}

/* ── PMR Analysis ── */
function _pmrRenderAnalysis(data, stats) {
    const panel = document.getElementById('pmr-panel-analysis');
    if (!panel) return;
    let html = '';

    // Pillar Gap Comparison Table (from live stats)
    if (stats && stats.pillar_stats) {
        html += `<h2>Pillar-Level Credibility Gap Analysis</h2>
        <div style="overflow-x:auto;">
        <table class="dfi-heatmap-table" style="width:100%;max-width:900px;border-collapse:collapse;font-size:14px;">
        <thead><tr>
            <th style="text-align:left;padding:8px;border-bottom:2px solid #444;">Pillar</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">GTM Avg</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Proof Avg</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Gap</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Severity</th>
        </tr></thead><tbody>`;
        for (const p of stats.pillars) {
            const ps = stats.pillar_stats[p];
            const gap = ps.gap_avg;
            const severity = Math.abs(gap) < 0.5 ? 'Aligned' : Math.abs(gap) < 1.0 ? 'Moderate' : Math.abs(gap) < 2.0 ? 'Significant' : 'Critical';
            const gapColor = Math.abs(gap) < 0.5 ? '#34d399' : Math.abs(gap) < 1.0 ? '#f59e0b' : '#ef4444';
            html += `<tr>
                <td style="padding:8px;border-bottom:1px solid #333;"><strong>${p}</strong> — ${escapeHtml(ps.label)}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:#34d399;font-weight:700;">${ps.gtm_avg}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:#f59e0b;font-weight:700;">${ps.proof_avg}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:${gapColor};font-weight:700;">${gap > 0 ? '+' : ''}${gap}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:${gapColor};">${severity}</td>
            </tr>`;
        }
        html += `</tbody></table></div>`;
    }

    // Vendor Type Breakdown
    if (stats && stats.vendor_type_stats) {
        html += `<h2 style="margin-top:28px;">Credibility Gap by Vendor Type</h2>
        <div style="overflow-x:auto;">
        <table class="dfi-heatmap-table" style="width:100%;max-width:800px;border-collapse:collapse;font-size:14px;">
        <thead><tr>
            <th style="text-align:left;padding:8px;border-bottom:2px solid #444;">Vendor Type</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Count</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">GTM Avg</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Proof Avg</th>
            <th style="text-align:center;padding:8px;border-bottom:2px solid #444;">Gap</th>
        </tr></thead><tbody>`;
        const vtEntries = Object.entries(stats.vendor_type_stats).sort((a, b) => b[1].count - a[1].count);
        for (const [vt, vs] of vtEntries) {
            const gapColor = Math.abs(vs.gap_avg) < 0.5 ? '#34d399' : Math.abs(vs.gap_avg) < 1.0 ? '#f59e0b' : '#ef4444';
            html += `<tr>
                <td style="padding:8px;border-bottom:1px solid #333;">${escapeHtml(vt)}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;">${vs.count}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:#34d399;font-weight:700;">${vs.gtm_avg}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:#f59e0b;font-weight:700;">${vs.proof_avg}</td>
                <td style="text-align:center;padding:8px;border-bottom:1px solid #333;color:${gapColor};font-weight:700;">${vs.gap_avg > 0 ? '+' : ''}${vs.gap_avg.toFixed(2)}</td>
            </tr>`;
        }
        html += `</tbody></table></div>`;
    }

    // Analysis sections from report data
    if (data.analysis_sections && data.analysis_sections.length) {
        data.analysis_sections.forEach((section, i) => {
            html += `<h2 data-pmr-field="analysis-title-${i}" style="margin-top:28px;">${escapeHtml(section.title)}</h2>
                <p data-pmr-field="analysis-body-${i}">${escapeHtml(section.body)}</p>`;
        });
    }

    panel.innerHTML = html;
}

